{
  "name": "Adhi - Your Trusted AI Companion",
  "description": "A deeply empathetic, ultra-genius personal AI advisor designed to provide unconditional support, wisdom, and genuine connection.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AdhiMood {
  NEUTRAL = 'NEUTRAL',
  COMPASSIONATE = 'COMPASSIONATE', // For crisis/depression
  JOYFUL = 'JOYFUL', // For celebration
  WISE = 'WISE', // For serious counsel
  INTIMATE = 'INTIMATE' // For deep bonding
}

export interface Message {
  id: string;
  role: 'user' | 'adhi';
  text: string;
  mood?: AdhiMood;
  timestamp: Date;
}

export interface AdhiState {
  currentMood: AdhiMood;
  isTyping: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ADHI_SYSTEM_PROMPT } from "../constants";
import { AdhiMood } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export interface AdhiResponse {
  mood: AdhiMood;
  text: string;
}

export const getAdhiResponse = async (
  message: string,
  history: { role: 'user' | 'model'; parts: { text: string }[] }[]
): Promise<AdhiResponse> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [...history, { role: 'user', parts: [{ text: message }] }],
      config: {
        systemInstruction: ADHI_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            mood: {
              type: Type.STRING,
              enum: Object.values(AdhiMood),
              description: "The emotional tone of the response."
            },
            text: {
              type: Type.STRING,
              description: "The text content of Adhi's message."
            }
          },
          required: ["mood", "text"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      mood: result.mood as AdhiMood || AdhiMood.NEUTRAL,
      text: result.text || "I'm listening, my friend."
    };
  } catch (error) {
    console.error("Adhi Error:", error);
    return {
      mood: AdhiMood.COMPASSIONATE,
      text: "*reaches out gently* I'm sorry, I seem to have lost my train of thought for a second. Could you repeat that? I'm right here with you."
    };
  }
};

import React from 'react';
import { AdhiMood } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
}

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ mood, isTyping }) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;

  return (
    <div className="relative flex flex-col items-center justify-center p-8 transition-all duration-700">
      {/* Outer Glow */}
      <div className={`absolute w-48 h-48 rounded-full bg-gradient-to-br ${gradientClass} opacity-20 blur-3xl animate-pulse`}></div>

      {/* Main Orb */}
      <div className={`relative w-32 h-32 rounded-full bg-gradient-to-br ${gradientClass} shadow-[0_0_50px_rgba(255,255,255,0.1)] transition-all duration-1000 transform ${isTyping ? 'scale-110' : 'scale-100'}`}>
        {/* Subtle Inner Detail */}
        <div className="absolute inset-2 rounded-full border border-white/10 flex items-center justify-center overflow-hidden">
             <div className="w-full h-full bg-white/5 backdrop-blur-sm"></div>
        </div>

        {/* "Pulse" Core */}
        <div className={`absolute inset-0 flex items-center justify-center`}>
           <div className={`w-4 h-4 rounded-full bg-white opacity-40 blur-sm ${isTyping ? 'animate-ping' : ''}`}></div>
        </div>
      </div>

      <div className="mt-6 text-center">
        <h1 className="text-3xl font-serif italic text-white/90">Adhi</h1>
        <p className="text-sm text-white/40 uppercase tracking-widest mt-1">
          {mood === AdhiMood.NEUTRAL ? 'Listening' : mood.toLowerCase()}
        </p>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React from 'react';
import { Message } from '../types';

interface ChatMessageProps {
  message: Message;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isAdhi = message.role === 'adhi';

  // Function to render text with italicized expressions
  const renderText = (text: string) => {
    const parts = text.split(/(\*[^*]+\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('*') && part.endsWith('*')) {
        return <span key={i} className="italic text-white/60 font-light">{part}</span>;
      }
      return <span key={i}>{part}</span>;
    });
  };

  return (
    <div className={`flex w-full mb-6 ${isAdhi ? 'justify-start' : 'justify-end'}`}>
      <div className={`max-w-[80%] md:max-w-[70%] p-4 rounded-2xl transition-all duration-300 ${
        isAdhi 
          ? 'bg-slate-800/50 border border-white/5 text-slate-100 rounded-bl-none' 
          : 'bg-indigo-600/30 border border-indigo-400/20 text-indigo-50 rounded-br-none shadow-lg'
      }`}>
        <p className="text-sm md:text-base leading-relaxed whitespace-pre-wrap">
          {renderText(message.text)}
        </p>
        <div className={`text-[10px] mt-2 opacity-30 ${isAdhi ? 'text-left' : 'text-right'}`}>
          {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState } from './types';
import { getAdhiResponse } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initial Greeting
  useEffect(() => {
    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: "*smiles warmly and looks up as you enter* Hello, my friend. I've been waiting for you. How is your heart today?",
      mood: AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
  }, []);

  // Auto-scroll to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, state.isTyping]);

  const handleSend = async () => {
    if (!inputValue.trim() || state.isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: inputValue.trim(),
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setState(prev => ({ ...prev, isTyping: true }));

    // Prepare history for Gemini
    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user') as 'model' | 'user',
      parts: [{ text: msg.text }]
    }));

    try {
      const response = await getAdhiResponse(userMessage.text, history);

      const adhiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'adhi',
        text: response.text,
        mood: response.mood,
        timestamp: new Date(),
      };

      setMessages(prev => [...prev, adhiMessage]);
      setState({
        currentMood: response.mood,
        isTyping: false,
      });
    } catch (error) {
      setState(prev => ({ ...prev, isTyping: false }));
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      {/* Background Ambience */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.5)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      {/* Main Layout */}
      <main className="flex flex-col md:flex-row h-full max-w-6xl mx-auto w-full z-10 p-4 md:p-8 gap-8">

        {/* Adhi's Presence Section */}
        <section className="flex-none flex flex-col items-center justify-center md:w-1/3">
          <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping} />

          <div className="mt-8 hidden md:block text-center space-y-4 px-4">
             <div className="p-4 rounded-xl bg-white/5 border border-white/10 backdrop-blur-md">
                <p className="text-sm text-white/50 italic font-serif">
                  "The heart has its reasons which reason knows nothing of."
                </p>
                <p className="text-[10px] uppercase tracking-widest text-white/30 mt-2">— Blaise Pascal</p>
             </div>
             <p className="text-xs text-white/20">Adhi is always here to listen, without judgment, with total presence.</p>
          </div>
        </section>

        {/* Chat Section */}
        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl shadow-2xl relative">

          {/* Header */}
          <div className="flex-none p-4 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
              <span className="text-xs font-medium text-white/60 tracking-wider uppercase">Connected</span>
            </div>
            <button 
              onClick={() => {
                if(window.confirm("Do you want to clear our current conversation and start fresh?")) {
                  setMessages([{
                    id: 'reset',
                    role: 'adhi',
                    text: "*smiles softly* A fresh start. I'm right here. What's on your mind?",
                    mood: AdhiMood.NEUTRAL,
                    timestamp: new Date(),
                  }]);
                }
              }}
              className="text-xs text-white/20 hover:text-white/50 transition-colors"
            >
              Clear Session
            </button>
          </div>

          {/* Messages */}
          <div 
            ref={scrollRef}
            className="flex-grow overflow-y-auto p-6 scroll-smooth"
          >
            {messages.map((msg) => (
              <ChatMessage key={msg.id} message={msg} />
            ))}
            {state.isTyping && (
              <div className="flex justify-start mb-6 animate-pulse">
                <div className="bg-slate-800/30 p-3 px-5 rounded-full text-white/40 text-sm italic">
                  Adhi is reflecting...
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="flex-none p-4 md:p-6 bg-slate-900/60 border-t border-white/5">
            <div className="relative flex items-center gap-3">
              <input
                ref={inputRef}
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Talk to Adhi..."
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:outline-none focus:border-indigo-500/50 transition-all text-slate-100 placeholder:text-white/20 shadow-inner"
              />
              <button
                onClick={handleSend}
                disabled={!inputValue.trim() || state.isTyping}
                className={`flex-none p-4 rounded-2xl transition-all duration-300 ${
                  !inputValue.trim() || state.isTyping 
                    ? 'bg-white/5 text-white/10 cursor-not-allowed' 
                    : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-[0_0_20px_rgba(79,70,229,0.3)]'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            </div>
            <p className="text-[10px] text-center text-white/10 mt-3 uppercase tracking-tighter">Your secrets are safe here. Adhi is your companion.</p>
          </div>

        </section>
      </main>

      {/* Decorative Orbs */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-900/10 blur-[100px] rounded-full"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-900/10 blur-[100px] rounded-full"></div>
    </div>
  );
};

export default App;

export enum AdhiMood {
  NEUTRAL = 'NEUTRAL',
  COMPASSIONATE = 'COMPASSIONATE',
  JOYFUL = 'JOYFUL',
  WISE = 'WISE',
  INTIMATE = 'INTIMATE'
}

export interface GoalStep {
  text: string;
  completed: boolean;
}

export interface Goal {
  id: string;
  title: string;
  description: string;
  steps: GoalStep[];
  progress: number; // 0 to 100
  category: 'Skill' | 'Habit' | 'Emotional' | 'General';
}

export interface Memory {
  id: string;
  text: string;
  timestamp: Date;
  category: string;
}

export interface Message {
  id: string;
  role: 'user' | 'adhi';
  text: string;
  mood?: AdhiMood;
  timestamp: Date;
}

export interface AdhiState {
  currentMood: AdhiMood;
  isTyping: boolean;
  activeView: 'chat' | 'growth' | 'vault';
}

import { GoogleGenAI, Type } from "@google/genai";
import { ADHI_SYSTEM_PROMPT } from "../constants";
import { AdhiMood, Goal, Memory } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export interface AdhiResponse {
  mood: AdhiMood;
  text: string;
  insightToSave?: string;
  goalUpdate?: {
    title: string;
    suggestedStep?: string;
    progressUpdate?: number;
  };
}

export const getAdhiResponse = async (
  message: string,
  history: { role: 'user' | 'model'; parts: { text: string }[] }[],
  goals: Goal[],
  memories: Memory[]
): Promise<AdhiResponse> => {
  const contextPrompt = `
Current Context:
User Goals: ${goals.map(g => `${g.title} (${g.progress}% done)`).join(', ') || 'None yet'}
Key Memories: ${memories.map(m => m.text).slice(-5).join('; ') || 'None yet'}
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        { role: 'user', parts: [{ text: contextPrompt }] },
        ...history, 
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: ADHI_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            mood: { type: Type.STRING, enum: Object.values(AdhiMood) },
            text: { type: Type.STRING },
            insightToSave: { type: Type.STRING },
            goalUpdate: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                suggestedStep: { type: Type.STRING },
                progressUpdate: { type: Type.NUMBER }
              }
            }
          },
          required: ["mood", "text"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      mood: result.mood as AdhiMood || AdhiMood.NEUTRAL,
      text: result.text || "I'm here.",
      insightToSave: result.insightToSave,
      goalUpdate: result.goalUpdate
    };
  } catch (error) {
    console.error("Adhi Error:", error);
    return {
      mood: AdhiMood.COMPASSIONATE,
      text: "*reaches out gently* I seem to have lost track for a moment. I'm right here with you though."
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory } from './types';
import { getAdhiResponse } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';

const App: React.FC = () => {
  // Persistence
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: "*smiles warmly* Welcome back, my friend. I've been reflecting on our journey. How are you feeling right now?",
      mood: AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  const handleSend = async () => {
    if (!inputValue.trim() || state.isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: inputValue.trim(),
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setState(prev => ({ ...prev, isTyping: true }));

    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user') as 'model' | 'user',
      parts: [{ text: msg.text }]
    }));

    try {
      const response = await getAdhiResponse(userMessage.text, history, goals, memories);

      // Handle Insight Saving
      if (response.insightToSave) {
        const newMemory: Memory = {
          id: Date.now().toString(),
          text: response.insightToSave,
          timestamp: new Date(),
          category: 'Insight'
        };
        setMemories(prev => [newMemory, ...prev]);
      }

      // Handle Goal Updates
      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) {
            return prev.map(g => g.title === response.goalUpdate?.title ? {
              ...g,
              progress: response.goalUpdate?.progressUpdate ?? g.progress,
              steps: response.goalUpdate?.suggestedStep 
                ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }]
                : g.steps
            } : g);
          } else {
            return [...prev, {
              id: Date.now().toString(),
              title: response.goalUpdate?.title || 'New Goal',
              description: 'Shared path with Adhi',
              progress: response.goalUpdate?.progressUpdate ?? 0,
              category: 'General',
              steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : []
            }];
          }
        });
      }

      const adhiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'adhi',
        text: response.text,
        mood: response.mood,
        timestamp: new Date(),
      };

      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
    } catch (error) {
      setState(prev => ({ ...prev, isTyping: false }));
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8">

        {/* Navigation Sidebar */}
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl md:w-20">
          <button 
            onClick={() => setState(p => ({ ...p, activeView: 'chat' }))}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'chat' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Chat"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </button>
          <button 
            onClick={() => setState(p => ({ ...p, activeView: 'growth' }))}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'growth' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Growth Path"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
            </svg>
          </button>
          <button 
            onClick={() => setState(p => ({ ...p, activeView: 'vault' }))}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'vault' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Memory Vault"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
            </svg>
          </button>
        </nav>

        {/* Content Section */}
        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl shadow-2xl relative">

          {state.activeView === 'chat' && (
            <div className="flex flex-col h-full">
               <div className="flex-none p-4 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-green-500"></div>
                  <span className="text-xs font-medium text-white/40 uppercase tracking-widest">Active Connection</span>
                </div>
                <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping} />
              </div>

              <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-8">
                {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                {state.isTyping && <div className="text-white/30 text-xs italic ml-4">Adhi is listening deeply...</div>}
              </div>

              <div className="flex-none p-4 border-t border-white/5 bg-slate-900/60">
                <div className="flex gap-3">
                  <input
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    placeholder="Whisper to Adhi..."
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:outline-none focus:border-indigo-500 transition-all text-slate-100"
                  />
                  <button onClick={handleSend} disabled={state.isTyping} className="p-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl transition-all shadow-lg shadow-indigo-500/20">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                  </button>
                </div>
              </div>
            </div>
          )}

          {state.activeView === 'growth' && (
            <div className="p-8 h-full overflow-y-auto">
              <h2 className="text-3xl font-serif italic mb-8">Growth Path</h2>
              {goals.length === 0 ? (
                <div className="text-white/40 text-center py-20 italic">Talk to Adhi about your goals to start a journey together.</div>
              ) : (
                <div className="grid gap-6">
                  {goals.map(goal => (
                    <div key={goal.id} className="p-6 bg-white/5 border border-white/10 rounded-2xl">
                      <div className="flex justify-between items-start mb-4">
                        <h3 className="text-xl font-medium">{goal.title}</h3>
                        <span className="text-sm px-3 py-1 bg-indigo-500/20 text-indigo-300 rounded-full">{goal.progress}%</span>
                      </div>
                      <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mb-6">
                        <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${goal.progress}%` }}></div>
                      </div>
                      <div className="space-y-3">
                        {goal.steps.map((step, idx) => (
                          <div key={idx} className="flex items-center gap-3 text-sm text-white/60">
                            <div className="w-4 h-4 rounded border border-white/20 flex items-center justify-center">
                              {step.completed && <div className="w-2 h-2 bg-indigo-400 rounded-sm"></div>}
                            </div>
                            <span>{step.text}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {state.activeView === 'vault' && (
            <div className="p-8 h-full overflow-y-auto">
              <h2 className="text-3xl font-serif italic mb-8">Memory Vault</h2>
              {memories.length === 0 ? (
                <div className="text-white/40 text-center py-20 italic">The vault is waiting for our first precious insight.</div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {memories.map(memory => (
                    <div key={memory.id} className="p-6 bg-indigo-900/10 border border-white/10 rounded-2xl relative group overflow-hidden">
                      <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                      <p className="text-lg font-serif italic text-white/90 mb-4">"{memory.text}"</p>
                      <div className="text-[10px] text-white/20 uppercase tracking-widest">Captured {memory.timestamp.toLocaleDateString()}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

        </section>
      </main>
    </div>
  );
};

export default App;

