import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData } from './types';
import { getAdhiResponse } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';

// Audio constants
const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Live session refs
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: "*smiles warmly* Welcome back, my friend. I've been reflecting on our journey. How are you feeling right now?",
      mood: AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  // --- Live Session Logic ---

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const createAudioBlob = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (frameIntervalRef.current) {
      clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    if (audioContextInRef.current) {
      audioContextInRef.current.close();
      audioContextInRef.current = null;
    }
    if (audioContextOutRef.current) {
      audioContextOutRef.current.close();
      audioContextOutRef.current = null;
    }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }, // Elegant voice
          },
          systemInstruction: "You are Adhi, in a live audio-visual session. Be ultra-genius, empathetic, and wise. You can see the user through their camera. React naturally to their presence and environment.",
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            console.log('Live session opened');
            setIsLive(true);

            // Audio streaming
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createAudioBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);

            // Video/Frame streaming
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.width = 320; // Lower res for efficiency
                canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                  canvas.toBlob(async (blob) => {
                    if (blob) {
                      const reader = new FileReader();
                      reader.onloadend = () => {
                        const base64Data = (reader.result as string).split(',')[1];
                        sessionPromise.then(session => {
                          session.sendRealtimeInput({
                            media: { data: base64Data, mimeType: 'image/jpeg' }
                          });
                        });
                      };
                      reader.readAsDataURL(blob);
                    }
                  }, 'image/jpeg', 0.6);
                }
              }
            }, 1000); // 1 FPS for visual context
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle audio output
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, OUTPUT_SAMPLE_RATE, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputNode);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              audioSourcesRef.current.add(source);
            }

            // Handle interruption
            if (message.serverContent?.interrupted) {
              audioSourcesRef.current.forEach(s => s.stop());
              audioSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }

            // Transcription support (UI feedback)
            if (message.serverContent?.outputTranscription) {
              // Optionally push to chat history
            }
          },
          onclose: () => stopLiveSession(),
          onerror: (e) => {
            console.error('Live Error:', e);
            stopLiveSession();
          },
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error('Failed to start live session:', err);
      alert("Please ensure camera and microphone permissions are granted.");
    }
  };

  // --- End Live Logic ---

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = (reader.result as string).split(',')[1];
        setPendingFile({
          data: base64Data,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;

    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you think of this?" : "");

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: currentText,
      fileData: currentFile || undefined,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));

    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user') as 'model' | 'user',
      parts: [
        { text: msg.text },
        ...(msg.fileData ? [{ inlineData: { data: msg.fileData.data, mimeType: msg.fileData.mimeType } }] : [])
      ]
    }));

    try {
      const response = await getAdhiResponse(currentText, history, goals, memories, currentFile || undefined);

      if (response.insightToSave) {
        const newMemory: Memory = {
          id: Date.now().toString(),
          text: response.insightToSave,
          timestamp: new Date(),
          category: 'Insight'
        };
        setMemories(prev => [newMemory, ...prev]);
      }

      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) {
            return prev.map(g => g.title === response.goalUpdate?.title ? {
              ...g,
              progress: response.goalUpdate?.progressUpdate ?? g.progress,
              steps: response.goalUpdate?.suggestedStep 
                ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }]
                : g.steps
            } : g);
          } else {
            return [...prev, {
              id: Date.now().toString(),
              title: response.goalUpdate?.title || 'New Goal',
              description: 'Shared path with Adhi',
              progress: response.goalUpdate?.progressUpdate ?? 0,
              category: 'General',
              steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : []
            }];
          }
        });
      }

      const adhiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'adhi',
        text: response.text,
        mood: response.mood,
        timestamp: new Date(),
      };

      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
    } catch (error) {
      setState(prev => ({ ...prev, isTyping: false }));
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8">

        {/* Navigation Sidebar */}
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl md:w-20">
          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'chat' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Chat"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </button>
          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'growth' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Growth Path"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
            </svg>
          </button>
          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }}
            className={`p-3 rounded-xl transition-all ${state.activeView === 'vault' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`}
            title="Memory Vault"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
            </svg>
          </button>
        </nav>

        {/* Content Section */}
        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl shadow-2xl relative">

          {state.activeView === 'chat' && (
            <div className="flex flex-col h-full">
               <div className="flex-none p-4 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-2 rounded-full ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                  <span className="text-xs font-medium text-white/40 uppercase tracking-widest">{isLive ? 'Live Session' : 'Text Connection'}</span>
                  <button 
                    onClick={isLive ? stopLiveSession : startLiveSession}
