          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'vault' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
