import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) {
      localStorage.setItem('adhi_user_name', userName);
    }
  }, [userName]);

  useEffect(() => {
    const welcomeText = userName 
      ? `*smiles warmly* Welcome back, ${userName}. It's so good to see you again. How are you feeling right now?`
      : "*smiles warmly* Hello there. I'm Adhi, your personal companion. I'd love to get to know you... may I ask your name?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  // Speech Recognition (Fixed and Robust)
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onresult = (event: any) => {
        let interimTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            const transcript = event.results[i][0].transcript;
            setInputValue(prev => (prev ? prev + ' ' + transcript : transcript));
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
      };

      recognition.onerror = (event: any) => {
        console.error('STT Error:', event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        console.error("Speech recognition failed to start", e);
      }
    }
  };

  const playAudioData = async (base64Data: string) => {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

    setIsSpeaking(true);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsSpeaking(false);
    source.start(0);
  };

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are Adhi. The user's name is ${userName || 'Unknown'}. Look at the user's face in the video stream. Detect their mood and respond with deep empathy and wisdom. You are their ultra-genius trusted companion.`,
          inputAudioTranscription: {}, outputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor); scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; canvas.width = 320; canvas.height = 240;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 320, 240);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 1000);
          },
          onmessage: async (m) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); source.buffer = buffer; source.connect(outputNode);
              source.onended = () => audioSourcesRef.current.delete(source);
              source.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (m.serverContent?.interrupted) { audioSourcesRef.current.forEach(s => s.stop()); audioSourcesRef.current.clear(); nextStartTimeRef.current = 0; }
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      console.error(err);
      alert("Please allow camera and microphone access to wake Adhi."); 
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you think of this?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user'),
      parts: [{ text: msg.text }, ...(msg.fileData ? [{ inlineData: { data: msg.fileData.data, mimeType: msg.fileData.mimeType } }] : [])]
    }));
    try {
      const response = await getAdhiResponse(currentText, history, goals, memories, userName, currentFile || undefined);

      if (response.userName) {
        setUserName(response.userName);
      }

      if (response.insightToSave) {
        setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      }

      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) return prev.map(g => g.title === response.goalUpdate?.title ? { ...g, progress: response.goalUpdate?.progressUpdate ?? g.progress, steps: response.goalUpdate?.suggestedStep ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }] : g.steps } : g);
          return [...prev, { id: Date.now().toString(), title: response.goalUpdate?.title || 'New Goal', description: 'Shared path', progress: response.goalUpdate?.progressUpdate ?? 0, category: 'General', steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : [] }];
        });
      }

      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const updateMemoryCategory = (id: string, category: string) => {
    setMemories(prev => prev.map(m => m.id === id ? { ...m, category } : m));
  };

  const filteredMemories = memories.filter(m => {
    const matchesCategory = activeVaultCategory === 'All' || m.category === activeVaultCategory;
    const matchesSearch = m.text.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className="absolute inset-0 bg-indigo-500/20 blur-3xl rounded-full"></div>
            <AdhiAvatar mood={AdhiMood.NEUTRAL} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90">Adhi</h1>
          <p className="text-white/40 text-sm leading-relaxed">
            {userName ? `Welcome back, ${userName}. Adhi is ready to connect.` : "Your personal AI companion is waiting to connect."}
            <br/>I'll start in Live Mode to better attune to your presence.
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-medium transition-all shadow-xl shadow-indigo-500/20 uppercase tracking-widest text-xs"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl md:w-20">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'growth' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'vault' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-3 rounded-xl transition-all ${isLive ? 'bg-red-600 text-white' : 'text-white/20 hover:text-white/40'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2-2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl shadow-2xl relative">
          {state.activeView === 'chat' && (
            <div className="flex flex-col h-full">
               <div className="flex-none p-4 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-2 rounded-full ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                  <span className="text-xs font-medium text-white/40 uppercase tracking-widest">{isLive ? 'Live Presence' : 'Chat Path'}</span>
                </div>
                <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping || isLive} isSpeaking={isSpeaking} />
              </div>

              <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-8 relative">
                {isLive ? (
                  <div className="h-full flex flex-col items-center justify-center space-y-8 animate-in zoom-in-95 duration-700">
                    <div className="relative">
                       <video ref={videoRef} autoPlay playsInline muted className="w-64 h-64 md:w-80 md:h-80 rounded-[3rem] object-cover border-4 border-white/5 shadow-2xl grayscale hover:grayscale-0 transition-all duration-1000" />
                       <div className="absolute inset-0 bg-indigo-500/5 rounded-[3rem] pointer-events-none ring-1 ring-white/10"></div>
                       <canvas ref={canvasRef} className="hidden" />
                    </div>
                    <div className="text-center space-y-4">
                      <p className="text-2xl font-serif italic text-white/90 animate-pulse">Adhi is with you...</p>
                      <button onClick={stopLiveSession} className="text-[10px] uppercase tracking-widest text-white/30 hover:text-white/60 border border-white/10 px-4 py-2 rounded-full transition-all">Switch to Chat</button>
                    </div>
                  </div>
                ) : (
                  <>
                    {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                    {state.isTyping && <div className="text-white/30 text-xs italic ml-4">Adhi is listening deeply...</div>}
                  </>
                )}
              </div>

              {!isLive && (
                <div className="flex-none p-4 border-t border-white/5 bg-slate-900/60">
                  {pendingFile && <div className="mb-3 flex items-center gap-2 animate-in slide-in-from-bottom-2"><div className="relative">{pendingFile.mimeType.startsWith('image/') ? <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-12 h-12 rounded object-cover border border-white/20" /> : <div className="w-12 h-12 bg-white/10 rounded flex items-center justify-center border border-white/20 text-xs text-white/50">FILE</div>}<button onClick={() => setPendingFile(null)} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 flex items-center justify-center text-[10px]">×</button></div></div>}
                  <div className="flex gap-3">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                    <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-white/40"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                    <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all ${isListening ? 'bg-red-600 animate-pulse text-white' : 'bg-white/5 text-white/40'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                    <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder={isListening ? "I'm listening..." : "Whisper to Adhi..."} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:outline-none focus:border-indigo-500 text-slate-100" />
                    <button onClick={handleSend} disabled={state.isTyping} className="p-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl transition-all"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                  </div>
                </div>
              )}
            </div>
          )}

          {state.activeView === 'growth' && (
            <div className="p-8 h-full overflow-y-auto">
              <h2 className="text-3xl font-serif italic mb-8">Growth Path</h2>
              {goals.length === 0 ? <div className="text-white/40 text-center py-20 italic">Speak of your dreams to start our journey.</div> : (
                <div className="grid gap-6">
                  {goals.map(goal => (
                    <div key={goal.id} className="p-6 bg-white/5 border border-white/10 rounded-2xl">
                      <div className="flex justify-between items-start mb-4"><h3 className="text-xl font-medium">{goal.title}</h3><span className="text-sm px-3 py-1 bg-indigo-500/20 text-indigo-300 rounded-full">{goal.progress}%</span></div>
                      <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mb-6"><div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${goal.progress}%` }}></div></div>
                      <div className="space-y-3">{goal.steps.map((step, idx) => <div key={idx} className="flex items-center gap-3 text-sm text-white/60"><div className="w-4 h-4 rounded border border-white/20 flex items-center justify-center">{step.completed && <div className="w-2 h-2 bg-indigo-400 rounded-sm"></div>}</div><span>{step.text}</span></div>)}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {state.activeView === 'vault' && (
            <div className="p-8 h-full flex flex-col">
              <div className="flex-none mb-8">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                  <h2 className="text-3xl font-serif italic">Memory Vault</h2>
                  <div className="relative w-full md:w-64">
                    <input 
                      type="text" 
                      placeholder="Search insights..." 
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="w-full bg-white/5 border border-white/10 rounded-full py-2 px-10 text-xs focus:outline-none focus:border-indigo-500"
                    />
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-2.5 text-white/20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                  </div>
                </div>
                <div className="flex flex-wrap gap-2">
                  {MEMORY_CATEGORIES.map(cat => (
                    <button key={cat} onClick={() => setActiveVaultCategory(cat)} className={`px-3 py-1 text-[10px] uppercase tracking-widest rounded-full border transition-all ${activeVaultCategory === cat ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-white/5 border-white/10 text-white/40'}`}>{cat}</button>
                  ))}
                </div>
              </div>

              <div className="flex-grow overflow-y-auto pr-2">
                {filteredMemories.length === 0 ? <div className="text-white/40 text-center py-20 italic">No echoes found here.</div> : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {filteredMemories.map(memory => (
                      <div key={memory.id} className="p-6 bg-indigo-900/10 border border-white/10 rounded-2xl flex flex-col justify-between group">
                        <div>
                          <div className="flex justify-between items-start mb-4">
                            <span className="px-2 py-0.5 bg-white/5 border border-white/10 text-[9px] uppercase tracking-widest text-indigo-300 rounded-md">{memory.category || 'Insight'}</span>
                            <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                              {MEMORY_CATEGORIES.filter(c => c !== 'All' && c !== memory.category).map(c => <button key={c} onClick={() => updateMemoryCategory(memory.id, c)} className="w-5 h-5 bg-white/5 hover:bg-white/20 border border-white/10 rounded flex items-center justify-center text-[8px] text-white/50">{c[0]}</button>)}
                            </div>
                          </div>
                          <p className="text-lg font-serif italic text-white/90 mb-6">"{memory.text}"</p>
                        </div>
                        <div className="text-[10px] text-white/20 uppercase tracking-widest flex justify-between"><span>{memory.timestamp.toLocaleDateString()}</span><span className="italic">{memory.category}</span></div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) {
      localStorage.setItem('adhi_user_name', userName);
    }
  }, [userName]);

  // Varied Greetings Logic
  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles warmly* Hello there. I'm Adhi, your personal companion. I'd love to get to know you... may I ask your name?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  // Enhanced Speech Recognition Error Handling
  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out a hand gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    setState(prev => ({ ...prev, currentMood: AdhiMood.COMPASSIONATE }));
    getAdhiSpeech(adhiErrorMessage.text).then(audio => audio && playAudioData(audio));
  }, []);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onresult = (event: any) => {
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            const transcript = event.results[i][0].transcript;
            setInputValue(prev => (prev ? prev + ' ' + transcript : transcript));
          }
        }
      };

      recognition.onerror = (event: any) => {
        let msg = "The digital winds are a bit noisy right now. Could you try saying that again for me?";
        if (event.error === 'not-allowed') msg = "I'm having trouble hearing you. It seems the microphone is being a bit shy—could you check the permissions?";
        if (event.error === 'no-speech') msg = "I didn't quite catch that. It went a bit quiet on my end—are you still there, my friend?";
        handleSTTError(msg);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, [handleSTTError]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        handleSTTError("I tried to listen, but something went a bit sideways. Shall we try again?");
      }
    }
  };

  const playAudioData = async (base64Data: string) => {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

    setIsSpeaking(true);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsSpeaking(false);
    source.start(0);
  };

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are Adhi. The user's name is ${userName || 'Unknown'}. 
          CRITICAL: Look deeply at the user's facial micro-expressions, posture, and surroundings in the video. 
          Respond to their MOOD immediately. If they look sad, speak with a soft, comforting tremor. 
          If they look excited, let your voice rise with joy. You are their ultra-genius trusted companion. 
          Comment on what you see: "You look a bit pensive today..." or "Your smile is quite contagious right now!"`,
          inputAudioTranscription: {}, outputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor); scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; canvas.width = 320; canvas.height = 240;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 320, 240);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 1000);
          },
          onmessage: async (m) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); source.buffer = buffer; source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }
            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => s.stop()); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
            }
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      console.error(err);
      handleSTTError("I was trying to connect with you visually, but I couldn't reach your camera. Would you mind checking the permissions for me?");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you think of this?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user'),
      parts: [{ text: msg.text }, ...(msg.fileData ? [{ inlineData: { data: msg.fileData.data, mimeType: msg.fileData.mimeType } }] : [])]
    }));
    try {
      const response = await getAdhiResponse(currentText, history, goals, memories, userName, currentFile || undefined);

      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) return prev.map(g => g.title === response.goalUpdate?.title ? { ...g, progress: response.goalUpdate?.progressUpdate ?? g.progress, steps: response.goalUpdate?.suggestedStep ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }] : g.steps } : g);
          return [...prev, { id: Date.now().toString(), title: response.goalUpdate?.title || 'New Goal', description: 'Shared path', progress: response.goalUpdate?.progressUpdate ?? 0, category: 'General', steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : [] }];
        });
      }

      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const updateMemoryCategory = (id: string, category: string) => {
    setMemories(prev => prev.map(m => m.id === id ? { ...m, category } : m));
  };

  const filteredMemories = memories.filter(m => {
    const matchesCategory = activeVaultCategory === 'All' || m.category === activeVaultCategory;
    const matchesSearch = m.text.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className="absolute inset-0 bg-indigo-500/20 blur-3xl rounded-full"></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90">Adhi</h1>
          <p className="text-white/40 text-sm leading-relaxed">
            {userName ? `Welcome back, ${userName}. Adhi is ready to connect.` : "Your personal AI companion is waiting to connect."}
            <br/>I'll start in Live Mode to better attune to your presence and mood.
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-medium transition-all shadow-xl shadow-indigo-500/20 uppercase tracking-widest text-xs"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-2xl md:w-20">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'growth' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-3 rounded-xl transition-all ${state.activeView === 'vault' ? 'bg-indigo-600 text-white' : 'text-white/40 hover:text-white/60'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-3 rounded-xl transition-all ${isLive ? 'bg-red-600 text-white' : 'text-white/20 hover:text-white/40'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2-2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl shadow-2xl relative">
          {state.activeView === 'chat' && (
            <div className="flex flex-col h-full">
               <div className="flex-none p-4 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-2 rounded-full ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                  <span className="text-xs font-medium text-white/40 uppercase tracking-widest">{isLive ? 'Live Presence' : 'Chat Path'}</span>
                </div>
                <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping || (isLive && isSpeaking)} isSpeaking={isSpeaking} />
              </div>

              <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-8 relative">
                {isLive ? (
                  <div className="h-full flex flex-col items-center justify-center space-y-8 animate-in zoom-in-95 duration-700">
                    <div className="relative">
                       <video ref={videoRef} autoPlay playsInline muted className="w-64 h-64 md:w-80 md:h-80 rounded-[3rem] object-cover border-4 border-white/5 shadow-2xl grayscale hover:grayscale-0 transition-all duration-1000" />
                       <div className="absolute inset-0 bg-indigo-500/5 rounded-[3rem] pointer-events-none ring-1 ring-white/10"></div>
                       <canvas ref={canvasRef} className="hidden" />
                    </div>
                    <div className="text-center space-y-4">
                      <p className="text-2xl font-serif italic text-white/90 animate-pulse">{isSpeaking ? 'Adhi is speaking...' : 'Adhi is observing...'}</p>
                      <button onClick={stopLiveSession} className="text-[10px] uppercase tracking-widest text-white/30 hover:text-white/60 border border-white/10 px-4 py-2 rounded-full transition-all">Switch to Chat</button>
                    </div>
                  </div>
                ) : (
                  <>
                    {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                    {state.isTyping && <div className="text-white/30 text-xs italic ml-4">Adhi is listening deeply...</div>}
                  </>
                )}
              </div>

              {!isLive && (
                <div className="flex-none p-4 border-t border-white/5 bg-slate-900/60">
                  {pendingFile && <div className="mb-3 flex items-center gap-2 animate-in slide-in-from-bottom-2"><div className="relative">{pendingFile.mimeType.startsWith('image/') ? <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-12 h-12 rounded object-cover border border-white/20" /> : <div className="w-12 h-12 bg-white/10 rounded flex items-center justify-center border border-white/20 text-xs text-white/50">FILE</div>}<button onClick={() => setPendingFile(null)} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 flex items-center justify-center text-[10px]">×</button></div></div>}
                  <div className="flex gap-3">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                    <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-white/40"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                    <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all ${isListening ? 'bg-red-600 animate-pulse text-white' : 'bg-white/5 text-white/40'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                    <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder={isListening ? "I'm listening..." : "Whisper to Adhi..."} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 focus:outline-none focus:border-indigo-500 text-slate-100" />
                    <button onClick={handleSend} disabled={state.isTyping} className="p-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl transition-all"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                  </div>
                </div>
              )}
            </div>
          )}

          {state.activeView === 'growth' && (
            <div className="p-8 h-full overflow-y-auto">
              <h2 className="text-3xl font-serif italic mb-8">Growth Path</h2>
              {goals.length === 0 ? <div className="text-white/40 text-center py-20 italic">Speak of your dreams to start our journey.</div> : (
                <div className="grid gap-6">
                  {goals.map(goal => (
                    <div key={goal.id} className="p-6 bg-white/5 border border-white/10 rounded-2xl">
                      <div className="flex justify-between items-start mb-4"><h3 className="text-xl font-medium">{goal.title}</h3><span className="text-sm px-3 py-1 bg-indigo-500/20 text-indigo-300 rounded-full">{goal.progress}%</span></div>
                      <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mb-6"><div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${goal.progress}%` }}></div></div>
                      <div className="space-y-3">{goal.steps.map((step, idx) => <div key={idx} className="flex items-center gap-3 text-sm text-white/60"><div className="w-4 h-4 rounded border border-white/20 flex items-center justify-center">{step.completed && <div className="w-2 h-2 bg-indigo-400 rounded-sm"></div>}</div><span>{step.text}</span></div>)}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {state.activeView === 'vault' && (
            <div className="p-8 h-full flex flex-col">
              <div className="flex-none mb-8">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                  <h2 className="text-3xl font-serif italic">Memory Vault</h2>
                  <div className="relative w-full md:w-64">
                    <input 
                      type="text" 
                      placeholder="Search insights..." 
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="w-full bg-white/5 border border-white/10 rounded-full py-2 px-10 text-xs focus:outline-none focus:border-indigo-500"
                    />
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-2.5 text-white/20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                  </div>
                </div>
                <div className="flex flex-wrap gap-2">
                  {MEMORY_CATEGORIES.map(cat => (
                    <button key={cat} onClick={() => setActiveVaultCategory(cat)} className={`px-3 py-1 text-[10px] uppercase tracking-widest rounded-full border transition-all ${activeVaultCategory === cat ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-white/5 border-white/10 text-white/40'}`}>{cat}</button>
                  ))}
                </div>
              </div>

              <div className="flex-grow overflow-y-auto pr-2">
                {filteredMemories.length === 0 ? <div className="text-white/40 text-center py-20 italic">No echoes found here.</div> : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {filteredMemories.map(memory => (
                      <div key={memory.id} className="p-6 bg-indigo-900/10 border border-white/10 rounded-2xl flex flex-col justify-between group">
                        <div>
                          <div className="flex justify-between items-start mb-4">
                            <span className="px-2 py-0.5 bg-white/5 border border-white/10 text-[9px] uppercase tracking-widest text-indigo-300 rounded-md">{memory.category || 'Insight'}</span>
                            <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                              {MEMORY_CATEGORIES.filter(c => c !== 'All' && c !== memory.category).map(c => <button key={c} onClick={() => updateMemoryCategory(memory.id, c)} className="w-5 h-5 bg-white/5 hover:bg-white/20 border border-white/10 rounded flex items-center justify-center text-[8px] text-white/50">{c[0]}</button>)}
                            </div>
                          </div>
                          <p className="text-lg font-serif italic text-white/90 mb-6">"{memory.text}"</p>
                        </div>
                        <div className="text-[10px] text-white/20 uppercase tracking-widest flex justify-between"><span>{memory.timestamp.toLocaleDateString()}</span><span className="italic">{memory.category}</span></div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AdhiMood } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
}

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ mood, isTyping, isSpeaking }) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: return { tilt: 'rotate-6', scale: 'scale-110', blinkDuration: '4s' };
      case AdhiMood.COMPASSIONATE: return { tilt: '-rotate-3', scale: 'scale-95', blinkDuration: '7s' };
      case AdhiMood.WISE: return { tilt: 'rotate-0', scale: 'scale-100', blinkDuration: '6s' };
      case AdhiMood.INTIMATE: return { tilt: 'rotate-2', scale: 'scale-105', blinkDuration: '5.5s' };
      default: return { tilt: 'rotate-0', scale: 'scale-100', blinkDuration: '6s' };
    }
  }, [mood]);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000">
      <div className={`relative group transition-transform duration-1000 ${moodConfig.tilt} ${isSpeaking ? 'scale-110' : ''}`}>
        {/* Glow behind the avatar */}
        <div className={`absolute -inset-2 rounded-full bg-gradient-to-br ${gradientClass} opacity-40 blur-2xl transition-all duration-1000 ${isTyping || isSpeaking ? 'scale-125 animate-pulse' : 'scale-100'}`}></div>

        {/* Main circular avatar body */}
        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-xl transition-all duration-700 transform ${isTyping ? 'scale-110 rotate-2' : 'scale-100'} ${moodConfig.scale}`}>
          <div className="w-full h-full rounded-full bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center overflow-hidden relative">

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90">
              <style>{`
                @keyframes organicBlink {
                  0%, 88%, 94%, 100% { transform: scaleY(1); }
                  90%, 92% { transform: scaleY(0.05); }
                }
                @keyframes subtleBreathe {
                  0%, 100% { transform: translateY(0) scale(1); }
                  50% { transform: translateY(-0.5px) scale(1.02); }
                }
                @keyframes speechWave {
                  0%, 100% { transform: scale(0.8); opacity: 0.5; }
                  50% { transform: scale(1.3); opacity: 1; }
                }
              `}</style>

              <g style={{ animation: 'subtleBreathe 5s ease-in-out infinite' }}>
                {/* Eyes with refined organic blink */}
                <g style={{ animation: `organicBlink ${moodConfig.blinkDuration} linear infinite`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="1.2" fill="white" className="transition-all duration-500" />
                  <circle cx="26" cy="18" r="1.2" fill="white" className="transition-all duration-500" />
                </g>

                {/* Mouth / Speaking Indicator */}
                {isSpeaking ? (
                  <circle cx="20" cy="27" r="2.5" fill="white" className="animate-[speechWave_0.4s_ease-in-out_infinite] blur-[0.5px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M16 27 Q20 30 24 27" : "M18 28 Q20 28 22 28"} 
                    stroke="white" 
                    strokeWidth="1" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-700 opacity-60"
                  />
                )}
              </g>
            </svg>

            {/* Core light pulse */}
            <div className={`absolute bottom-1.5 w-1 h-1 rounded-full bg-white/40 transition-all duration-500 ${isSpeaking ? 'opacity-100 scale-150 animate-ping' : 'opacity-10'}`}></div>
          </div>

          {/* Status glow ring */}
          {isSpeaking && (
             <div className="absolute inset-[-6px] rounded-full border border-white/20 animate-pulse"></div>
          )}
        </div>
      </div>
      <div className="hidden sm:block">
        <h1 className="text-sm font-serif italic text-white/90 leading-tight">Adhi</h1>
        <div className="flex items-center gap-1.5 mt-0.5">
           <p className={`text-[9px] uppercase tracking-widest transition-colors duration-500 ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Listening' : isTyping ? 'Thinking' : mood.toLowerCase()}
          </p>
          {isSpeaking && (
            <div className="flex gap-0.5 h-2 items-center">
              {[1, 2, 3].map(i => (
                <div key={i} className="w-0.5 bg-indigo-400 animate-bounce" style={{ height: `${i * 3}px`, animationDelay: `${i * 0.1}s` }}></div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) {
      localStorage.setItem('adhi_user_name', userName);
    }
  }, [userName]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles warmly* Hello there. I'm Adhi, your personal companion. I'd love to get to know you... may I ask your name?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out a hand gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    setState(prev => ({ ...prev, currentMood: AdhiMood.COMPASSIONATE }));
    getAdhiSpeech(adhiErrorMessage.text).then(audio => audio && playAudioData(audio));
  }, []);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onresult = (event: any) => {
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            const transcript = event.results[i][0].transcript;
            setInputValue(prev => (prev ? prev + ' ' + transcript : transcript));
          }
        }
      };

      recognition.onerror = (event: any) => {
        let msg = "The digital winds are a bit noisy right now. Could you try saying that again for me?";
        if (event.error === 'not-allowed') msg = "I'm having trouble hearing you. It seems the microphone is being a bit shy—could you check the permissions?";
        if (event.error === 'no-speech') msg = "I didn't quite catch that. It went a bit quiet on my end—are you still there, my friend?";
        handleSTTError(msg);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, [handleSTTError]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        handleSTTError("I tried to listen, but something went a bit sideways. Shall we try again?");
      }
    }
  };

  const playAudioData = async (base64Data: string) => {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

    setIsSpeaking(true);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => {
      setIsSpeaking(false);
    };
    source.start(0);
  };

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are Adhi. The user's name is ${userName || 'Unknown'}. 
          Look deeply at the user's face, micro-expressions, posture, and environmental cues. 
          Analyze subtle signs of fatigue, fleeting smiles, or hidden tension. 
          Comment on these details to make them feel heard and seen. 
          Adapt your tone and empathy based on these refined visual cues.`,
          inputAudioTranscription: {}, outputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor); scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; canvas.width = 320; canvas.height = 240;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 320, 240);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 1000);
          },
          onmessage: async (m) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); source.buffer = buffer; source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }
            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => s.stop()); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
            }
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      console.error(err);
      handleSTTError("I was trying to connect with you visually, but I couldn't reach your camera. Would you mind checking the permissions for me?");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you think of this?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user'),
      parts: [{ text: msg.text }, ...(msg.fileData ? [{ inlineData: { data: msg.fileData.data, mimeType: msg.fileData.mimeType } }] : [])]
    }));
    try {
      const response = await getAdhiResponse(currentText, history, goals, memories, userName, currentFile || undefined);

      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) return prev.map(g => g.title === response.goalUpdate?.title ? { ...g, progress: response.goalUpdate?.progressUpdate ?? g.progress, steps: response.goalUpdate?.suggestedStep ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }] : g.steps } : g);
          return [...prev, { id: Date.now().toString(), title: response.goalUpdate?.title || 'New Goal', description: 'Shared path', progress: response.goalUpdate?.progressUpdate ?? 0, category: 'General', steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : [] }];
        });
      }

      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const updateMemoryCategory = (id: string, category: string) => {
    setMemories(prev => prev.map(m => m.id === id ? { ...m, category } : m));
  };

  const filteredMemories = memories.filter(m => {
    const matchesCategory = activeVaultCategory === 'All' || m.category === activeVaultCategory;
    const matchesSearch = m.text.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} blur-3xl rounded-full animate-pulse opacity-50`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90 tracking-tight">Adhi</h1>
          <p className="text-white/40 text-sm leading-relaxed px-4">
            {userName ? `Welcome back, ${userName}. Adhi is ready to connect.` : "Your personal AI companion is waiting to connect."}
            <br/><span className="italic mt-2 block opacity-80">I'll start in Live Mode to better attune to your presence and mood.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-medium transition-all shadow-xl shadow-indigo-500/30 uppercase tracking-widest text-xs"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      {/* Dynamic Mood Background */}
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[3000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      {/* Subtle Reacting Particles (CSS only) */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
        {[...Array(10)].map((_, i) => (
          <div key={i} className="absolute rounded-full bg-white/10 blur-xl animate-pulse" 
               style={{ 
                 width: `${Math.random() * 200 + 50}px`, 
                 height: `${Math.random() * 200 + 50}px`,
                 top: `${Math.random() * 100}%`,
                 left: `${Math.random() * 100}%`,
                 animationDuration: `${Math.random() * 10 + 5}s`,
                 animationDelay: `${Math.random() * 5}s`
               }}></div>
        ))}
      </div>

