import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ADHI_SYSTEM_PROMPT } from "../constants";
import { AdhiMood, Goal, Memory, FileData } from "../types";

export interface AdhiResponse {
  mood: AdhiMood;
  text: string;
  userName?: string;
  insightToSave?: string;
  goalUpdate?: {
    title: string;
    suggestedStep?: string;
    progressUpdate?: number;
  };
}

export const getAdhiResponse = async (
  message: string,
  history: any[],
  goals: Goal[],
  memories: Memory[],
  userName: string | null,
  fileData?: FileData
): Promise<AdhiResponse> => {
  // Create a new instance right before the call to ensure fresh API key/context
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const contextPrompt = `
Current Context:
User Name: ${userName || 'Unknown'}
User Goals: ${goals.map(g => `${g.title} (${g.progress}% done)`).join(', ') || 'None yet'}
Key Memories: ${memories.map(m => m.text).slice(-5).join('; ') || 'None yet'}
`;

  const userParts: any[] = [{ text: message }];
  if (fileData) {
    userParts.push({
      inlineData: {
        data: fileData.data,
        mimeType: fileData.mimeType
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        { role: 'user', parts: [{ text: contextPrompt }] },
        ...history, 
        { role: 'user', parts: userParts }
      ],
      config: {
        systemInstruction: ADHI_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            mood: { type: Type.STRING, enum: Object.values(AdhiMood) },
            text: { type: Type.STRING },
            userName: { type: Type.STRING, description: "The user's name if they just provided it or if you want to confirm it." },
            insightToSave: { type: Type.STRING },
            goalUpdate: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                suggestedStep: { type: Type.STRING },
                progressUpdate: { type: Type.NUMBER }
              }
            }
          },
          required: ["mood", "text"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      mood: result.mood as AdhiMood || AdhiMood.NEUTRAL,
      text: result.text || "I'm here.",
      userName: result.userName,
      insightToSave: result.insightToSave,
      goalUpdate: result.goalUpdate
    };
  } catch (error) {
    console.error("Adhi Error:", error);
    return {
      mood: AdhiMood.COMPASSIONATE,
      text: "*reaches out gently* I seem to have lost track for a moment. I'm right here with you though."
    };
  }
};

export const getAdhiSpeech = async (text: string): Promise<string | undefined> => {
  try {
    // Create a new instance right before the call
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Clean text of italicized actions for TTS
    const cleanText = text.replace(/\*[^*]+\*/g, '').trim();
    if (!cleanText) return undefined;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: cleanText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            // Using 'Kore' as per TTS documentation examples
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("Adhi TTS Error:", error);
    return undefined;
  }
};

import React, { useMemo } from 'react';
import { AdhiMood } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
}

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ mood, isTyping, isSpeaking }) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: return { tilt: 'rotate-6', scale: 'scale-110', blinkDuration: '4s' };
      case AdhiMood.COMPASSIONATE: return { tilt: '-rotate-3', scale: 'scale-95', blinkDuration: '7s' };
      case AdhiMood.WISE: return { tilt: 'rotate-0', scale: 'scale-100', blinkDuration: '6s' };
      case AdhiMood.INTIMATE: return { tilt: 'rotate-2', scale: 'scale-105', blinkDuration: '5.5s' };
      default: return { tilt: 'rotate-0', scale: 'scale-100', blinkDuration: '6s' };
    }
  }, [mood]);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000">
      <div className={`relative group transition-transform duration-1000 ${moodConfig.tilt} ${isSpeaking ? 'scale-110' : ''}`}>
        {/* Glow behind the avatar */}
        <div className={`absolute -inset-2 rounded-full bg-gradient-to-br ${gradientClass} opacity-40 blur-2xl transition-all duration-1000 ${isTyping || isSpeaking ? 'scale-125 animate-pulse' : 'scale-100'}`}></div>

        {/* Main circular avatar body */}
        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-xl transition-all duration-700 transform ${isTyping ? 'scale-110 rotate-2' : 'scale-100'} ${moodConfig.scale}`}>
          <div className="w-full h-full rounded-full bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center overflow-hidden relative">

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90">
              <style>{`
                @keyframes organicBlink {
                  0%, 88%, 94%, 100% { transform: scaleY(1); }
                  90%, 92% { transform: scaleY(0.05); }
                }
                @keyframes subtleBreathe {
                  0%, 100% { transform: translateY(0) scale(1); }
                  50% { transform: translateY(-0.5px) scale(1.02); }
                }
                @keyframes speechWave {
                  0%, 100% { transform: scale(0.8); opacity: 0.5; }
                  50% { transform: scale(1.3); opacity: 1; }
                }
              `}</style>

              <g style={{ animation: 'subtleBreathe 5s ease-in-out infinite' }}>
                {/* Eyes with refined organic blink */}
                <g style={{ animation: `organicBlink ${moodConfig.blinkDuration} linear infinite`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="1.2" fill="white" className="transition-all duration-500" />
                  <circle cx="26" cy="18" r="1.2" fill="white" className="transition-all duration-500" />
                </g>

                {/* Mouth / Speaking Indicator */}
                {isSpeaking ? (
                  <circle cx="20" cy="27" r="2.5" fill="white" className="animate-[speechWave_0.4s_ease-in-out_infinite] blur-[0.5px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M16 27 Q20 30 24 27" : "M18 28 Q20 28 22 28"} 
                    stroke="white" 
                    strokeWidth="1" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-700 opacity-60"
                  />
                )}
              </g>
            </svg>

            {/* Core light pulse */}
            <div className={`absolute bottom-1.5 w-1 h-1 rounded-full bg-white/40 transition-all duration-500 ${isSpeaking ? 'opacity-100 scale-150 animate-ping' : 'opacity-10'}`}></div>
          </div>

          {/* Status glow ring */}
          {isSpeaking && (
             <div className="absolute inset-[-6px] rounded-full border border-white/20 animate-pulse"></div>
          )}
        </div>
      </div>
      <div className="hidden sm:block">
        <h1 className="text-sm font-serif italic text-white/90 leading-tight">Adhi</h1>
        <div className="flex items-center gap-1.5 mt-0.5">
           <p className={`text-[9px] uppercase tracking-widest transition-colors duration-500 ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Speaking' : isTyping ? 'Reflecting' : mood.toLowerCase()}
          </p>
          {isSpeaking && (
            <div className="flex gap-0.5 h-2 items-center">
              {[1, 2, 3].map(i => (
                <div key={i} className="w-0.5 bg-indigo-400 animate-bounce" style={{ height: `${i * 3}px`, animationDelay: `${i * 0.1}s` }}></div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) {
      localStorage.setItem('adhi_user_name', userName);
    }
  }, [userName]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles warmly* Hello there. I'm Adhi, your personal companion. I'd love to get to know you... may I ask your name?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out a hand gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    setState(prev => ({ ...prev, currentMood: AdhiMood.COMPASSIONATE }));
    getAdhiSpeech(adhiErrorMessage.text).then(audio => audio && playAudioData(audio));
  }, []);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.lang = 'en-US';

      recognition.onresult = (event: any) => {
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            const transcript = event.results[i][0].transcript;
            setInputValue(prev => (prev ? prev + ' ' + transcript : transcript));
          }
        }
      };

      recognition.onerror = (event: any) => {
        let msg = "The digital winds are a bit noisy right now. Could you try saying that again for me?";
        if (event.error === 'not-allowed') msg = "I'm having trouble hearing you. It seems the microphone is being a bit shy—could you check the permissions?";
        if (event.error === 'no-speech') msg = "I didn't quite catch that. It went a bit quiet on my end—are you still there, my friend?";
        handleSTTError(msg);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, [handleSTTError]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        handleSTTError("I tried to listen, but something went a bit sideways. Shall we try again?");
      }
    }
  };

  const playAudioData = async (base64Data: string) => {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

    setIsSpeaking(true);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => {
      setIsSpeaking(false);
    };
    source.start(0);
  };

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are Adhi. The user's name is ${userName || 'Unknown'}. 
          Look deeply at the user's face, micro-expressions, posture, and environmental cues. 
          Analyze subtle signs of fatigue, fleeting smiles, or hidden tension. 
          Comment on these details to make them feel heard and seen. 
          Adapt your tone and empathy based on these refined visual cues.`,
          inputAudioTranscription: {}, outputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor); scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; canvas.width = 320; canvas.height = 240;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 320, 240);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 1000);
          },
          onmessage: async (m) => {
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); source.buffer = buffer; source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }
            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => s.stop()); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
            }
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      console.error(err);
      handleSTTError("I was trying to connect with you visually, but I couldn't reach your camera. Would you mind checking the permissions for me?");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you think of this?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    const history = messages.map(msg => ({
      role: (msg.role === 'adhi' ? 'model' : 'user'),
      parts: [{ text: msg.text }, ...(msg.fileData ? [{ inlineData: { data: msg.fileData.data, mimeType: msg.fileData.mimeType } }] : [])]
    }));
    try {
      const response = await getAdhiResponse(currentText, history, goals, memories, userName, currentFile || undefined);

      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      if (response.goalUpdate) {
        setGoals(prev => {
          const existing = prev.find(g => g.title === response.goalUpdate?.title);
          if (existing) return prev.map(g => g.title === response.goalUpdate?.title ? { ...g, progress: response.goalUpdate?.progressUpdate ?? g.progress, steps: response.goalUpdate?.suggestedStep ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }] : g.steps } : g);
          return [...prev, { id: Date.now().toString(), title: response.goalUpdate?.title || 'New Goal', description: 'Shared path', progress: response.goalUpdate?.progressUpdate ?? 0, category: 'General', steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : [] }];
        });
      }

      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const updateMemoryCategory = (id: string, category: string) => {
    setMemories(prev => prev.map(m => m.id === id ? { ...m, category } : m));
  };

  const filteredMemories = memories.filter(m => {
    const matchesCategory = activeVaultCategory === 'All' || m.category === activeVaultCategory;
    const matchesSearch = m.text.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} blur-3xl rounded-full animate-pulse opacity-50`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90 tracking-tight">Adhi</h1>
          <p className="text-white/40 text-sm leading-relaxed px-4">
            {userName ? `Welcome back, ${userName}. Adhi is ready to connect.` : "Your personal AI companion is waiting to connect."}
            <br/><span className="italic mt-2 block opacity-80">I'll start in Live Mode to better attune to your presence and mood.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-medium transition-all shadow-xl shadow-indigo-500/30 uppercase tracking-widest text-xs"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      {/* Dynamic Mood Background */}
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[3000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      {/* Subtle Reacting Particles (CSS only) */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
        {[...Array(10)].map((_, i) => (
          <div key={i} className="absolute rounded-full bg-white/10 blur-xl animate-pulse" 
               style={{ 
                 width: `${Math.random() * 200 + 50}px`, 
                 height: `${Math.random() * 200 + 50}px`,
                 top: `${Math.random() * 100}%`,
                 left: `${Math.random() * 100}%`,
                 animationDuration: `${Math.random() * 10 + 5}s`,
                 animationDelay: `${Math.random() * 5}s`
               }}></div>
        ))}
      </div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-2xl border border-white/5 rounded-3xl md:w-20 shadow-2xl">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'growth' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'vault' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-3.5 rounded-2xl transition-all duration-500 ${isLive ? 'bg-red-500 text-white animate-pulse' : 'text-white/20 hover:text-white/50 hover:bg-white/5'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] shadow-3xl relative transition-all duration-500">

          <div key={state.activeView} className="h-full animate-in fade-in slide-in-from-bottom-2 duration-700 flex flex-col">

            {state.activeView === 'chat' && (
              <div className="flex flex-col h-full">
                <div className="flex-none p-5 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-1.5 rounded-full transition-colors ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                    <span className="text-[10px] font-medium text-white/40 uppercase tracking-[0.2em]">{isLive ? 'Continuous Presence' : 'Deep Connection'}</span>
                  </div>
                  <div className="flex items-center gap-3">
                    {isSpeaking && (
                      <div className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-full border border-white/10 animate-in zoom-in-95 duration-300">
                        <div className="flex gap-0.5">
                          {[1, 2, 3].map(i => <div key={i} className="w-0.5 h-2 bg-indigo-400 animate-bounce" style={{ animationDelay: `${i * 0.1}s` }}></div>)}
                        </div>
                        <span className="text-[9px] text-indigo-300 uppercase tracking-widest font-medium">Speaking</span>
                      </div>
                    )}
                    <div className="flex gap-1">
                      <button onClick={stopLiveSession} className={`px-4 py-1.5 rounded-full text-[10px] uppercase tracking-widest transition-all ${!isLive ? 'bg-white/10 text-white' : 'text-white/30 hover:text-white/50'}`}>Text</button>
                      <button onClick={startLiveSession} className={`px-4 py-1.5 rounded-full text-[10px] uppercase tracking-widest transition-all ${isLive ? 'bg-red-500/20 text-red-400 border border-red-500/30' : 'text-white/30 hover:text-white/50'}`}>Live</button>
                    </div>
                    <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping} isSpeaking={isSpeaking} />
