export enum AdhiMood {
  NEUTRAL = 'NEUTRAL',
  COMPASSIONATE = 'COMPASSIONATE',
  JOYFUL = 'JOYFUL',
  WISE = 'WISE',
  INTIMATE = 'INTIMATE'
}

export type AdhiVoice = 'Zephyr' | 'Kore' | 'Puck' | 'Charon' | 'Fenrir';

export interface GoalStep {
