                .avatar-container-mood-slow-sway { animation: mood-slow-sway 8s ease-in-out infinite; }
                .avatar-container-mood-bounce { animation: mood-bounce 1s ease-in-out infinite; }
                .avatar-container-mood-pulse { animation: mood-pulse 5s ease-in-out infinite; }
              `}</style>

              <g style={{ animation: 'subtleBreathe 5s ease-in-out infinite' }}>
                {/* Eyes with refined organic blink */}
                <g style={{ animation: `organicBlink ${moodConfig.blinkDuration} linear infinite`, transformOrigin: 'center 18px' }}>
