                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-5 border-t border-white/5 bg-slate-900/60 backdrop-blur-xl">
                    {pendingFile && <div className="mb-4 flex items-center gap-3 animate-in slide-in-from-bottom-2 duration-300">
                      <div className="relative group">
                        {pendingFile.mimeType.startsWith('image/') ? (
