                      <button onClick={startLiveSession} className={`px-4 py-1.5 rounded-full text-[10px] uppercase tracking-widest transition-all ${isLive ? 'bg-red-500/20 text-red-400 border border-red-500/30' : 'text-white/30 hover:text-white/50'}`}>Live</button>
                    </div>
                    <AdhiAvatar mood={state.currentMood} isTyping={state.isTyping} isSpeaking={isSpeaking} />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-10 relative">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-12 animate-in zoom-in-95 duration-1000">
                      <div className="relative">
                        <div className={`absolute -inset-8 rounded-full bg-gradient-to-br ${moodBgClass} opacity-20 blur-3xl animate-pulse`}></div>
                        <video ref={videoRef} autoPlay playsInline muted className="w-64 h-64 md:w-80 md:h-80 rounded-[3.5rem] object-cover border-4 border-white/10 shadow-3xl grayscale hover:grayscale-0 transition-all duration-[2000ms] relative z-10" />
                        <div className="absolute inset-0 bg-indigo-500/5 rounded-[3.5rem] pointer-events-none ring-1 ring-white/20 z-20"></div>
                        <canvas ref={canvasRef} className="hidden" />
                      </div>
                      <div className="text-center space-y-3 z-30">
                        <p className="text-2xl font-serif italic text-white/90 tracking-tight">
                          {isSpeaking ? "Listening with intent..." : "Sensing your presence..."}
                        </p>
                        <div className="flex justify-center gap-1 h-1">
                           {[...Array(5)].map((_, i) => (
                             <div key={i} className={`w-8 h-full bg-white/20 rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400/50 scale-x-110' : ''}`} style={{ transitionDelay: `${i * 100}ms` }}></div>
                           ))}
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-3 ml-4 animate-pulse">
                          <div className="w-1 h-1 bg-white/20 rounded-full"></div>
                          <span className="text-white/30 text-[10px] uppercase tracking-[0.2em] italic">Adhi is reflecting deeply...</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-5 border-t border-white/5 bg-slate-900/60 backdrop-blur-xl">
                    {pendingFile && <div className="mb-4 flex items-center gap-3 animate-in slide-in-from-bottom-2 duration-300">
                      <div className="relative group">
                        {pendingFile.mimeType.startsWith('image/') ? (
                          <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-14 h-14 rounded-xl object-cover border border-white/20 ring-4 ring-white/5 shadow-xl" />
                        ) : (
                          <div className="w-14 h-14 bg-white/5 rounded-xl flex items-center justify-center border border-white/20 text-[10px] text-white/50 uppercase font-bold tracking-tighter">FILE</div>
                        )}
                        <button onClick={() => setPendingFile(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs shadow-lg hover:scale-110 transition-transform">×</button>
                      </div>
                      <span className="text-[10px] text-white/30 uppercase tracking-widest font-medium">Ready to share this insight</span>
                    </div>}
                    <div className="flex gap-4 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all duration-300 text-white/40 hover:text-white/70 ring-1 ring-white/5"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                      <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all duration-500 shadow-xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder={isListening ? "Listening with full attention..." : "Share a thought or a whisper..."} className="w-full bg-white/5 border border-white/10 rounded-3xl py-4.5 px-7 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-500 text-slate-100 placeholder:text-white/20 text-base shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2 top-2 p-2.5 bg-indigo-600 hover:bg-indigo-500 rounded-2xl transition-all duration-300 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {state.activeView === 'growth' && (
              <div className="p-10 h-full overflow-y-auto">
                <header className="mb-12">
                   <h2 className="text-4xl font-serif italic text-white/90 mb-2 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-xs uppercase tracking-[0.3em]">Our shared journey towards expansion</p>
                </header>
                {goals.length === 0 ? <div className="text-white/20 text-center py-32 italic text-lg font-light tracking-wide animate-pulse">Speak of your dreams, and we shall map the path together.</div> : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {goals.map(goal => (
                      <div key={goal.id} className="p-8 bg-white/5 border border-white/10 rounded-[2rem] hover:bg-white/10 transition-all duration-500 group relative overflow-hidden">
                        <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${moodBgClass} opacity-10 blur-3xl group-hover:opacity-30 transition-opacity`}></div>
                        <div className="flex justify-between items-start mb-6">
                          <div>
                            <h3 className="text-2xl font-medium text-white/90 group-hover:text-white transition-colors">{goal.title}</h3>
                            <p className="text-[10px] text-white/30 uppercase tracking-widest mt-1">{goal.category}</p>
                          </div>
                          <span className="text-lg font-serif italic text-indigo-300/80 bg-indigo-500/10 px-4 py-1.5 rounded-2xl border border-indigo-500/20">{goal.progress}%</span>
                        </div>
                        <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden mb-8 ring-1 ring-white/5">
                          <div className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 transition-all duration-[2000ms] ease-out shadow-[0_0_15px_rgba(99,102,241,0.5)]" style={{ width: `${goal.progress}%` }}></div>
                        </div>
