                            <div key={idx} className={`flex items-start gap-4 text-sm transition-all duration-500 ${step.completed ? 'text-white/30' : 'text-white/70'}`}>
                              <div className={`w-5 h-5 rounded-lg border-2 transition-all flex items-center justify-center mt-0.5 ${step.completed ? 'border-indigo-500 bg-indigo-500/20' : 'border-white/10 group-hover:border-white/20'}`}>
                                {step.completed && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
                              </div>
                              <span className={step.completed ? 'line-through decoration-indigo-500/50' : ''}>{step.text}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
