import React, { useMemo, useState, useEffect } from 'react';
import { AdhiMood } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
}

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ mood, isTyping, isSpeaking }) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);

  // Varying blink timing slightly to make it feel organic
  useEffect(() => {
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);
      const nextDelay = Math.random() * 4000 + 2000;
      return setTimeout(triggerBlink, nextDelay);
    };
    const timer = triggerBlink();
    return () => clearTimeout(timer);
  }, []);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: return { tilt: 'rotate-3', scale: 'scale-110', animation: 'mood-bounce' };
      case AdhiMood.COMPASSIONATE: return { tilt: '-rotate-2', scale: 'scale-95', animation: 'mood-sway' };
      case AdhiMood.WISE: return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-pulse' };
      case AdhiMood.INTIMATE: return { tilt: 'rotate-1', scale: 'scale-105', animation: 'mood-slow-sway' };
      default: return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-sway' };
    }
  }, [mood]);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000">
      <div className={`relative group transition-all duration-1000 ${moodConfig.tilt} ${isSpeaking ? 'scale-110' : ''}`}>
        <div className={`absolute -inset-2 rounded-full bg-gradient-to-br ${gradientClass} opacity-40 blur-2xl transition-all duration-1000 ${isTyping || isSpeaking ? 'scale-125 animate-pulse' : 'scale-100'}`}></div>

        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-xl transition-all duration-700 transform ${isTyping ? 'scale-110 rotate-2' : 'scale-100'} ${moodConfig.scale} avatar-container-${moodConfig.animation}`}>
          <div className="w-full h-full rounded-full bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center overflow-hidden relative">

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90">
              <style>{`
                @keyframes organicBlink {
                  0%, 90%, 100% { transform: scaleY(1); }
                  95% { transform: scaleY(0.1); }
                }
                @keyframes subtleBreathe {
                  0%, 100% { transform: translateY(0) scale(1); }
                  50% { transform: translateY(-0.3px) scale(1.01); }
                }
                @keyframes speechWave {
                  0%, 100% { transform: scale(0.85); opacity: 0.7; }
                  50% { transform: scale(1.2); opacity: 1; }
                }
                @keyframes mood-sway {
                  0%, 100% { transform: translateX(-1px) rotate(-1deg); }
                  50% { transform: translateX(1px) rotate(1deg); }
                }
                @keyframes mood-slow-sway {
                  0%, 100% { transform: rotate(-0.5deg) translateY(0); }
                  50% { transform: rotate(0.5deg) translateY(-0.5px); }
                }
                @keyframes mood-bounce {
                  0%, 100% { transform: translateY(0); }
                  50% { transform: translateY(-2px); }
                }
                @keyframes mood-pulse {
                  0%, 100% { transform: scale(1); opacity: 1; }
                  50% { transform: scale(1.03); opacity: 0.95; }
                }

                .avatar-container-mood-sway { animation: mood-sway 5s ease-in-out infinite; }
                .avatar-container-mood-slow-sway { animation: mood-slow-sway 7s ease-in-out infinite; }
                .avatar-container-mood-bounce { animation: mood-bounce 1.5s ease-in-out infinite; }
                .avatar-container-mood-pulse { animation: mood-pulse 4s ease-in-out infinite; }
              `}</style>

              <g style={{ animation: 'subtleBreathe 5s ease-in-out infinite' }}>
                {/* Eyes with organic blink - key resets to re-trigger short animation */}
                <g key={blinkKey} style={{ animation: `organicBlink 0.25s linear forwards`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="1.1" fill="white" className="transition-all duration-500" />
                  <circle cx="26" cy="18" r="1.1" fill="white" className="transition-all duration-500" />
                </g>

                {isSpeaking ? (
                  <circle cx="20" cy="27" r="2.2" fill="white" className="animate-[speechWave_0.4s_ease-in-out_infinite] blur-[0.3px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M16 27 Q20 29.5 24 27" : "M18 28 Q20 28 22 28"} 
                    stroke="white" 
                    strokeWidth="0.8" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-700 opacity-50"
                  />
                )}
              </g>
            </svg>

            <div className={`absolute bottom-1.5 w-0.5 h-0.5 rounded-full bg-white/30 transition-all duration-500 ${isSpeaking ? 'opacity-100 scale-150 animate-ping' : 'opacity-0'}`}></div>
          </div>

          {isSpeaking && (
             <div className="absolute inset-[-4px] rounded-full border border-white/10 animate-pulse"></div>
          )}
        </div>
      </div>
      <div className="hidden sm:block">
        <h1 className="text-sm font-serif italic text-white/90 leading-tight">Adhi</h1>
        <div className="flex items-center gap-1.5 mt-0.5">
           <p className={`text-[9px] uppercase tracking-widest transition-colors duration-500 ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Listening' : isTyping ? 'Thinking' : mood.toLowerCase()}
          </p>
          {isSpeaking && (
            <div className="flex gap-0.5 h-2 items-center">
              {[1, 2, 3].map(i => (
                <div key={i} className="w-0.5 bg-indigo-400 animate-bounce" style={{ height: `${i * 3}px`, animationDelay: `${i * 0.1}s` }}></div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

