                             <div key={i} className={`w-8 h-full bg-white/20 rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400/50 scale-x-110' : ''}`} style={{ transitionDelay: `${i * 100}ms` }}></div>
