                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-5 border-t border-white/5 bg-slate-900/60 backdrop-blur-xl">
                    {pendingFile && <div className="mb-4 flex items-center gap-3 animate-in slide-in-from-bottom-2 duration-300">
                      <div className="relative group">
                        {pendingFile.mimeType.startsWith('image/') ? (
                          <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-14 h-14 rounded-xl object-cover border border-white/20 ring-4 ring-white/5 shadow-xl" />
                        ) : (
                          <div className="w-14 h-14 bg-white/5 rounded-xl flex items-center justify-center border border-white/20 text-[10px] text-white/50 uppercase font-bold tracking-tighter">FILE</div>
                        )}
                        <button onClick={() => setPendingFile(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs shadow-lg hover:scale-110 transition-transform">×</button>
                      </div>
                      <span className="text-[10px] text-white/30 uppercase tracking-widest font-medium">Ready to share this insight</span>
                    </div>}
                    <div className="flex gap-4 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all duration-300 text-white/40 hover:text-white/70 ring-1 ring-white/5"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                      <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all duration-500 shadow-xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
