      case AdhiMood.WISE: return { speed: '15s', opacity: 'opacity-10', scale: 'scale-90', count: 8, color: 'bg-indigo-400' };
      case AdhiMood.COMPASSIONATE: return { speed: '12s', opacity: 'opacity-20', scale: 'scale-100', count: 10, color: 'bg-teal-400' };
      default: return { speed: '10s', opacity: 'opacity-20', scale: 'scale-100', count: 10, color: 'bg-white' };
    }
  }, [state.currentMood]);

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} blur-3xl rounded-full animate-pulse opacity-50`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90 tracking-tight">Adhi</h1>
