                        <button onClick={() => setPendingFile(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs shadow-lg hover:scale-110 transition-transform">×</button>
                      </div>
                      <span className="text-[10px] text-white/30 uppercase tracking-widest font-medium">Ready to share this insight</span>
