                )}
              </div>
            )}

            {state.activeView === 'growth' && (
              <div className="p-10 h-full overflow-y-auto">
                <header className="mb-12">
                   <h2 className="text-4xl font-serif italic text-white/90 mb-2 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-xs uppercase tracking-[0.3em]">Our shared journey towards expansion</p>
                </header>
                {goals.length === 0 ? <div className="text-white/20 text-center py-32 italic text-lg font-light tracking-wide animate-pulse">Speak of your dreams, and we shall map the path together.</div> : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {goals.map(goal => (
                      <div key={goal.id} className="p-8 bg-white/5 border border-white/10 rounded-[2rem] hover:bg-white/10 transition-all duration-500 group relative overflow-hidden">
                        <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${moodBgClass} opacity-10 blur-3xl group-hover:opacity-30 transition-opacity`}></div>
                        <div className="flex justify-between items-start mb-6">
                          <div>
                            <h3 className="text-2xl font-medium text-white/90 group-hover:text-white transition-colors">{goal.title}</h3>
                            <p className="text-[10px] text-white/30 uppercase tracking-widest mt-1">{goal.category}</p>
