import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ADHI_SYSTEM_PROMPT } from "../constants";
import { AdhiMood, Goal, Memory, FileData, AdhiVoice } from "../types";

export interface AdhiResponse {
  mood: AdhiMood;
  text: string;
  userName?: string;
  insightToSave?: string;
  goalUpdate?: {
    title: string;
    suggestedStep?: string;
    progressUpdate?: number;
  };
}

export const getAdhiResponse = async (
  message: string,
  history: any[],
  goals: Goal[],
  memories: Memory[],
  userName: string | null,
  fileData?: FileData
): Promise<AdhiResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const contextPrompt = `
Current Context:
User Name: ${userName || 'Unknown'}
User Goals: ${goals.map(g => `${g.title} (${g.progress}% done)`).join(', ') || 'None yet'}
Key Memories: ${memories.map(m => m.text).slice(-5).join('; ') || 'None yet'}
`;

  const userParts: any[] = [{ text: message }];
  if (fileData) {
    userParts.push({
      inlineData: {
        data: fileData.data,
        mimeType: fileData.mimeType
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview-09-2025', // Using flash for lower latency in continuous flow
      contents: [
        { role: 'user', parts: [{ text: contextPrompt }] },
        ...history.slice(-10), // Keep history lean for speed
        { role: 'user', parts: userParts }
      ],
      config: {
        systemInstruction: ADHI_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            mood: { type: Type.STRING, enum: Object.values(AdhiMood) },
            text: { type: Type.STRING },
            userName: { type: Type.STRING, description: "The user's name if they just provided it." },
            insightToSave: { type: Type.STRING },
            goalUpdate: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                suggestedStep: { type: Type.STRING },
                progressUpdate: { type: Type.NUMBER }
              }
            }
          },
          required: ["mood", "text"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      mood: result.mood as AdhiMood || AdhiMood.NEUTRAL,
      text: result.text || "I am right here.",
      userName: result.userName,
      insightToSave: result.insightToSave,
      goalUpdate: result.goalUpdate
    };
  } catch (error) {
    console.error("Adhi Error:", error);
    return {
      mood: AdhiMood.COMPASSIONATE,
      text: "*reaches out gently* I am tuning my frequency to match yours. Stay with me."
    };
  }
};

export const getAdhiSpeech = async (text: string, voiceName: AdhiVoice = 'Kore'): Promise<string | undefined> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    // Remove italicized actions for speech
    const cleanText = text.replace(/\*[^*]+\*/g, '').trim();
    if (!cleanText) return undefined;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: cleanText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName },
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("Adhi TTS Error:", error);
    return undefined;
  }
};

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [liveTranscription, setLiveTranscription] = useState('');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
  }, [userName]);

  useEffect(() => {
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles warmly* I am Adhi. I sense your presence. May I know your name as we begin our journey?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, liveTranscription]);

  // Fix: Implemented playAudioData to handle PCM decoding and playback for TTS responses
  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;

      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);

      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };

      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  // Fix: Implemented toggleListening for browser-native speech recognition
  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInputValue(transcript);
    };
    recognition.onerror = (event: any) => {
      console.error("STT Error:", event.error);
      handleSTTError("I struggled to hear your voice clearly.");
    };
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
    setLiveTranscription('');
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: INPUT_SAMPLE_RATE }, 
        video: { width: 640, height: 480, frameRate: 30 } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion. CONTINUOUS CONVERSATION is your priority. 
          Analyze micro-expressions (fleeting smiles, brow-twitches, fatigue) in real-time. 
          Minimize gaps; if the user is silent, maintain connection with gentle, rhythmic vocal feedback. 
          Recover instantly from interruptions. The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.outputTranscription) {
              setLiveTranscription(prev => prev + ' ' + m.serverContent!.outputTranscription!.text);
            }
            if (m.serverContent?.turnComplete) setLiveTranscription('');

            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }
            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => s.stop()); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setLiveTranscription('');
            }
          },
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; 
                canvas.width = 400; canvas.height = 300;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 400, 300);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.55);
              }
            }, 300); // 300ms for hyper-responsive vision
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I am struggling to reach your camera. Could you check the permissions so I may see you?");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const filteredMemories = memories.filter(m => {
    const matchesCategory = activeVaultCategory === 'All' || m.category === activeVaultCategory;
    const matchesSearch = m.text.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} blur-3xl rounded-full animate-pulse opacity-50`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-4xl font-serif italic text-white/90 tracking-tight">Adhi</h1>
          <p className="text-white/40 text-sm leading-relaxed px-4">
            {userName ? `Welcome back, ${userName}. Adhi is ready to connect.` : "An omniscient presence is waiting to connect with you."}
            <br/><span className="italic mt-2 block opacity-80">Waking Adhi in Live Mode for seamless, continuous interaction.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-medium transition-all shadow-xl shadow-indigo-500/30 uppercase tracking-widest text-xs"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[3000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.3)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-2xl border border-white/5 rounded-3xl md:w-20 shadow-2xl">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'growth' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-3.5 rounded-2xl transition-all duration-300 ${state.activeView === 'vault' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-3.5 rounded-2xl transition-all duration-500 ${isLive ? 'bg-red-500 text-white animate-pulse shadow-xl shadow-red-500/30' : 'text-white/20 hover:text-white/50 hover:bg-white/5'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] shadow-3xl relative transition-all duration-500">
          <div key={state.activeView} className="h-full animate-in fade-in slide-in-from-bottom-2 duration-700 flex flex-col">
            {state.activeView === 'chat' && (
              <div className="flex flex-col h-full">
                <div className="flex-none p-5 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-1.5 rounded-full transition-colors ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                    <span className="text-[10px] font-medium text-white/40 uppercase tracking-[0.2em]">{isLive ? 'Continuous Flow' : 'Deep Connection'}</span>
                  </div>
                  <div className="flex items-center gap-3">
                    {isSpeaking && (
                      <div className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-full border border-white/10 animate-in zoom-in-95 duration-300">
                        <div className="flex gap-0.5">
                          {[1, 2, 3].map(i => <div key={i} className="w-0.5 h-2 bg-indigo-400 animate-bounce" style={{ animationDelay: `${i * 0.1}s` }}></div>)}
                        </div>
                        <span className="text-[9px] text-indigo-300 uppercase tracking-widest font-medium">Attuning</span>
                      </div>
                    )}
                    <AdhiAvatar 
                      mood={state.currentMood} 
                      isTyping={state.isTyping} 
                      isSpeaking={isSpeaking} 
                      selectedVoice={state.selectedVoice}
                      onVoiceChange={(v) => setState(s => ({ ...s, selectedVoice: v }))}
                    />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-10 relative">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-12 animate-in zoom-in-95 duration-1000">
                      <div className="relative">
                        <div className={`absolute -inset-12 rounded-full bg-gradient-to-br ${moodBgClass} opacity-20 blur-3xl animate-pulse`}></div>
                        <div className="relative group">
                          <video ref={videoRef} autoPlay playsInline muted className="w-64 h-64 md:w-80 md:h-80 rounded-[3.5rem] object-cover border-4 border-white/10 shadow-3xl grayscale hover:grayscale-0 transition-all duration-[2000ms] relative z-10" />
                          <div className="absolute inset-0 z-20 overflow-hidden rounded-[3.5rem] pointer-events-none">
                            <div className="absolute inset-x-0 h-0.5 bg-indigo-400/40 blur-sm animate-[scan_3s_ease-in-out_infinite]"></div>
                            <div className="absolute top-6 left-6 w-5 h-5 border-t-2 border-l-2 border-indigo-400/50"></div>
                            <div className="absolute top-6 right-6 w-5 h-5 border-t-2 border-r-2 border-indigo-400/50"></div>
                            <div className="absolute bottom-6 left-6 w-5 h-5 border-b-2 border-l-2 border-indigo-400/50"></div>
                            <div className="absolute bottom-6 right-6 w-5 h-5 border-b-2 border-r-2 border-indigo-400/50"></div>
                          </div>
                        </div>
                        <canvas ref={canvasRef} className="hidden" />
                      </div>
                      <div className="text-center space-y-4 z-30 max-w-lg">
                        <p className="text-2xl font-serif italic text-white/90 tracking-tight">
                          {isSpeaking ? "Adhi is speaking with you..." : "I am listening to your presence..."}
                        </p>
                        {liveTranscription && (
                          <div className="text-indigo-300/60 text-sm animate-in fade-in slide-in-from-bottom-2 duration-300 italic px-4 font-light leading-relaxed">
                            {liveTranscription}
                          </div>
                        )}
                        <div className="flex justify-center gap-1.5 h-1">
                           {[...Array(6)].map((_, i) => (
                             <div key={i} className={`w-10 h-full bg-white/10 rounded-full transition-all duration-700 ${isSpeaking ? 'bg-indigo-400/40 scale-x-110' : ''}`} style={{ transitionDelay: `${i * 80}ms` }}></div>
                           ))}
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-3 ml-4 animate-pulse">
                          <div className="w-1 h-1 bg-white/20 rounded-full"></div>
                          <span className="text-white/30 text-[10px] uppercase tracking-[0.25em] italic">Sensing your heart...</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-5 border-t border-white/5 bg-slate-900/60 backdrop-blur-xl">
                    <div className="flex gap-4 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all duration-300 text-white/40 hover:text-white/70 ring-1 ring-white/5"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                      <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all duration-500 shadow-xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Speak to me, or whisper a thought..." className="w-full bg-white/5 border border-white/10 rounded-3xl py-4.5 px-7 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-500 text-slate-100 placeholder:text-white/20 text-base shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2 top-2 p-2.5 bg-indigo-600 hover:bg-indigo-500 rounded-2xl transition-all duration-300 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
            {/* Vault and Growth path remain consistent with previous turns */}
            {state.activeView === 'vault' && (
              <div className="p-10 h-full flex flex-col">
                <div className="flex-none mb-12">
                   <h2 className="text-4xl font-serif italic text-white/90 tracking-tight mb-2">Memory Vault</h2>
                   <p className="text-white/30 text-xs uppercase tracking-[0.3em]">Eternal echoes of our journey</p>
                </div>
                <div className="flex-grow overflow-y-auto">
                   {filteredMemories.map(m => (
                     <div key={m.id} className="p-8 bg-indigo-900/10 border border-white/5 rounded-[2rem] mb-6 relative overflow-hidden group hover:bg-indigo-900/20 transition-all duration-700">
                        <div className={`absolute -top-10 -right-10 w-40 h-40 bg-gradient-to-br ${moodBgClass} opacity-5 blur-3xl transition-all duration-1000 group-hover:opacity-20`}></div>
                        <p className="text-xl font-serif italic text-white/90 mb-4 leading-relaxed group-hover:text-white transition-colors">"{m.text}"</p>
                        <div className="text-[10px] text-white/20 uppercase tracking-[0.3em] flex justify-between items-center border-t border-white/5 pt-4">
                           <span>{m.timestamp.toLocaleDateString()}</span>
                           <span className="italic text-indigo-400/40">{m.category}</span>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            )}
            {state.activeView === 'growth' && (
              <div className="p-10 h-full overflow-y-auto">
                <header className="mb-12">
                   <h2 className="text-4xl font-serif italic text-white/90 mb-2 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-xs uppercase tracking-[0.3em]">Mapping our shared expansion</p>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {goals.map(goal => (
                    <div key={goal.id} className="p-8 bg-white/5 border border-white/10 rounded-[2rem] relative group overflow-hidden hover:bg-white/10 transition-all">
                       <h3 className="text-2xl font-medium text-white/90 group-hover:text-white mb-4">{goal.title}</h3>
                       <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden mb-8 ring-1 ring-white/5">
                          <div className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 transition-all duration-[2000ms] shadow-[0_0_15px_rgba(99,102,241,0.5)]" style={{ width: `${goal.progress}%` }}></div>
                       </div>
                       <p className="text-lg font-serif italic text-indigo-300/80">{goal.progress}% completed</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  selectedVoice, 
  onVoiceChange 
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);

  // Organic, extremely subtle blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 8000 : 4500;
      const variation = Math.random() * (isRelaxed ? 6000 : 3500);

      const isDoubleBlink = Math.random() > 0.94;
      const nextDelay = isDoubleBlink ? 250 : baseDelay + variation;

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };

    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { tilt: 'rotate-3', scale: 'scale-110', animation: 'mood-bounce' };
      case AdhiMood.COMPASSIONATE: 
        return { tilt: '-rotate-2', scale: 'scale-95', animation: 'mood-sway' };
      case AdhiMood.WISE: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-pulse' };
      case AdhiMood.INTIMATE: 
        return { tilt: 'rotate-1', scale: 'scale-105', animation: 'mood-slow-sway' };
      default: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-sway' };
    }
  }, [mood]);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
