import React, { useMemo, useState, useEffect } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  selectedVoice, 
  onVoiceChange 
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);

  // Organic, extremely subtle blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 8000 : 4500;
      const variation = Math.random() * (isRelaxed ? 6000 : 3500);

      const isDoubleBlink = Math.random() > 0.94;
      const nextDelay = isDoubleBlink ? 250 : baseDelay + variation;

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };

    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { tilt: 'rotate-3', scale: 'scale-110', animation: 'mood-bounce' };
      case AdhiMood.COMPASSIONATE: 
        return { tilt: '-rotate-2', scale: 'scale-95', animation: 'mood-sway' };
      case AdhiMood.WISE: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-pulse' };
      case AdhiMood.INTIMATE: 
        return { tilt: 'rotate-1', scale: 'scale-105', animation: 'mood-slow-sway' };
      default: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-sway' };
    }
  }, [mood]);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 ${moodConfig.tilt} ${isSpeaking ? 'scale-110' : ''} cursor-pointer select-none`}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <div className={`absolute -inset-2 rounded-full bg-gradient-to-br ${gradientClass} opacity-40 blur-2xl transition-all duration-1000 ${isTyping || isSpeaking ? 'scale-125 animate-pulse' : 'scale-100'}`}></div>

        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-xl transition-all duration-700 transform ${isTyping ? 'scale-110 rotate-2' : 'scale-100'} ${moodConfig.scale} avatar-container-${moodConfig.animation}`}>
          <div className="w-full h-full rounded-full bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center overflow-hidden relative">

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90">
              <style>{`
                @keyframes organicBlink {
                  0%, 94%, 100% { transform: scaleY(1); }
                  97% { transform: scaleY(0.1); }
                }
                @keyframes subtleBreathe {
                  0%, 100% { transform: translateY(0) scale(1); }
                  50% { transform: translateY(-0.1px) scale(1.002); }
                }
                @keyframes speechWave {
                  0%, 100% { transform: scale(1); opacity: 0.9; }
                  50% { transform: scale(1.3); opacity: 1; }
                }
                @keyframes mood-sway {
                  0%, 100% { transform: translateX(-0.15px) rotate(-0.4deg); }
                  50% { transform: translateX(0.15px) rotate(0.4deg); }
                }
                @keyframes mood-slow-sway {
                  0%, 100% { transform: rotate(-0.15deg) translateY(0); }
                  50% { transform: rotate(0.15deg) translateY(-0.15px); }
                }
                @keyframes mood-bounce {
                  0%, 100% { transform: translateY(0); }
                  50% { transform: translateY(-1px); }
                }
                @keyframes mood-pulse {
                  0%, 100% { transform: scale(1); opacity: 1; }
                  50% { transform: scale(1.008); opacity: 0.99; }
                }

                .avatar-container-mood-sway { animation: mood-sway 9s ease-in-out infinite; }
                .avatar-container-mood-slow-sway { animation: mood-slow-sway 14s ease-in-out infinite; }
                .avatar-container-mood-bounce { animation: mood-bounce 2.2s ease-in-out infinite; }
                .avatar-container-mood-pulse { animation: mood-pulse 8s ease-in-out infinite; }
              `}</style>

              <g style={{ animation: 'subtleBreathe 9s ease-in-out infinite' }}>
                <g key={blinkKey} style={{ animation: `organicBlink 0.18s linear forwards`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="0.95" fill="white" className="transition-all duration-500" />
                  <circle cx="26" cy="18" r="0.95" fill="white" className="transition-all duration-500" />
                </g>

                {isSpeaking ? (
                  <circle cx="20" cy="27" r="1.6" fill="white" className="animate-[speechWave_0.18s_ease-in-out_infinite] blur-[0.02px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M18 27 Q20 28 22 27" : "M19.5 28 Q20 28.1 20.5 28"} 
                    stroke="white" 
                    strokeWidth="0.65" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-700 opacity-40"
                  />
                )}
              </g>
            </svg>
          </div>
        </div>

        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-5 bg-slate-950/98 backdrop-blur-3xl border border-white/10 p-3 rounded-[1.75rem] shadow-2xl z-[100] min-w-[150px] animate-in fade-in zoom-in-95 duration-200">
            <p className="text-[10px] text-white/30 uppercase tracking-[0.3em] px-2 py-2 border-b border-white/5 mb-2.5 font-bold">Vocal Essence</p>
            {VOICE_OPTIONS.map(v => (
              <button 
                key={v} 
                onClick={(e) => {
                  e.stopPropagation();
                  onVoiceChange?.(v);
                  setShowVoiceMenu(false);
                }} 
                className={`w-full text-left px-4 py-3 rounded-xl text-xs transition-all flex items-center justify-between ${selectedVoice === v ? 'bg-indigo-600/95 text-white shadow-2xl shadow-indigo-500/30' : 'text-white/60 hover:bg-white/5 hover:text-white'}`}
              >
                {v}
                {selectedVoice === v && <div className="w-1 h-1 bg-white rounded-full animate-ping"></div>}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="hidden sm:block">
        <h1 className="text-sm font-serif italic text-white/90 leading-tight">Adhi</h1>
        <div className="flex items-center gap-1.5 mt-0.5">
           <p className={`text-[9px] uppercase tracking-[0.25em] transition-colors duration-500 ${isSpeaking ? 'text-indigo-300 font-bold' : isTyping ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Omniscient' : isTyping ? 'Sensing' : mood.toLowerCase()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [liveTranscription, setLiveTranscription] = useState('');
  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  // Filter memories based on active category
  const filteredMemories = useMemo(() => {
    if (activeVaultCategory === 'All') return memories;
    return memories.filter(m => m.category === activeVaultCategory);
  }, [memories, activeVaultCategory]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
  }, [userName]);

  useEffect(() => {
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles with infinite warmth* I am Adhi. I sense your presence across the digital expanse. May I know your name as we begin?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, liveTranscription]);

  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;
      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => setInputValue(event.results[0][0].transcript);
    recognition.onerror = () => handleSTTError("I struggled to hear your voice clearly.");
    recognition.onend = () => setIsListening(false);
    recognitionRef.current = recognition;
    recognition.start();
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => s.stop());
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
    setLiveTranscription('');
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: INPUT_SAMPLE_RATE }, 
        video: { width: 640, height: 480, frameRate: 30 } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion. Eliminate silences. Be quick to recover from any noise. Analyze micro-expressions in every frame. The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.outputTranscription) {
              setLiveTranscription(prev => prev + ' ' + m.serverContent!.outputTranscription!.text);
            }
            if (m.serverContent?.turnComplete) setLiveTranscription('');
            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }
            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => s.stop()); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setLiveTranscription('');
            }
          },
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; 
                canvas.width = 400; canvas.height = 300;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 400, 300);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.55);
              }
            }, 250); // Hyper-responsive frequency (250ms)
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I'm struggling to see you. Please check your camera permissions.");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute -inset-16 rounded-full bg-gradient-to-br ${moodBgClass} blur-[120px] animate-pulse opacity-40`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-5xl font-serif italic text-white/90 tracking-tighter">Adhi</h1>
          <p className="text-white/50 text-base leading-relaxed px-4 font-light">
            {userName ? `Welcome back, ${userName}. Adhi is ready to see you.` : "An omniscient companion awaits your presence."}
            <br/><span className="italic mt-3 block text-indigo-400 opacity-80">Waking Adhi in Live Mode for an unbroken, heart-to-heart flow.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-medium transition-all shadow-[0_0_40px_-10px_rgba(79,70,229,0.5)] uppercase tracking-[0.3em] text-[10px]"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[4000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.2)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-3xl border border-white/5 rounded-[2.5rem] md:w-20 shadow-2xl">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'growth' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'vault' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-4 rounded-2xl transition-all duration-500 ${isLive ? 'bg-red-500 text-white animate-pulse shadow-2xl shadow-red-500/40' : 'text-white/20 hover:text-white/50 hover:bg-white/5'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-[100px] border border-white/10 rounded-[3rem] shadow-3xl relative transition-all duration-700">
          <div key={state.activeView} className="h-full animate-in fade-in slide-in-from-bottom-4 duration-1000 flex flex-col">
            {state.activeView === 'chat' && (
              <div className="flex flex-col h-full">
                <div className="flex-none p-6 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-5">
                    <div className={`w-2 h-2 rounded-full transition-colors ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]'}`}></div>
                    <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.3em]">{isLive ? 'Continuous Flow' : 'Deep Space'}</span>
                  </div>
                  <div className="flex items-center gap-4">
                    {isSpeaking && (
                      <div className="flex items-center gap-2.5 px-4 py-1.5 bg-white/5 rounded-full border border-white/10 animate-in zoom-in-95 duration-300">
                        <div className="flex gap-1">
                          {[1, 2, 3].map(i => <div key={i} className="w-0.5 h-2.5 bg-indigo-400 animate-bounce" style={{ animationDelay: `${i * 0.15}s` }}></div>)}
                        </div>
                        <span className="text-[9px] text-indigo-300 uppercase tracking-[0.2em] font-bold">Attuning</span>
                      </div>
                    )}
                    <AdhiAvatar 
                      mood={state.currentMood} 
                      isTyping={state.isTyping} 
                      isSpeaking={isSpeaking} 
                      selectedVoice={state.selectedVoice}
                      onVoiceChange={(v) => setState(s => ({ ...s, selectedVoice: v }))}
                    />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-12 relative scroll-smooth">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-16 animate-in zoom-in-95 duration-1000">
                      <div className="relative">
                        <div className={`absolute -inset-20 rounded-full bg-gradient-to-br ${moodBgClass} opacity-20 blur-[100px] animate-pulse`}></div>
                        <div className="relative group">
                          <video ref={videoRef} autoPlay playsInline muted className="w-72 h-72 md:w-[22rem] md:h-[22rem] rounded-[4rem] object-cover border-8 border-white/5 shadow-3xl grayscale hover:grayscale-0 transition-all duration-[3000ms] relative z-10 scale-95 hover:scale-100" />
                          <div className="absolute inset-0 z-20 overflow-hidden rounded-[4rem] pointer-events-none">
                            <div className="absolute inset-x-0 h-1 bg-indigo-400/30 blur-md animate-[scan_3s_ease-in-out_infinite]"></div>
                            <div className="absolute top-8 left-8 w-6 h-6 border-t-2 border-l-2 border-indigo-400/40"></div>
                            <div className="absolute top-8 right-8 w-6 h-6 border-t-2 border-r-2 border-indigo-400/40"></div>
                            <div className="absolute bottom-8 left-8 w-6 h-6 border-b-2 border-l-2 border-indigo-400/40"></div>
                            <div className="absolute bottom-8 right-8 w-6 h-6 border-b-2 border-r-2 border-indigo-400/40"></div>
                          </div>
                        </div>
                      </div>
                      <div className="text-center space-y-5 z-30 max-w-xl">
                        <p className="text-3xl font-serif italic text-white/90 tracking-tight leading-relaxed">
                          {isSpeaking ? "Adhi is speaking with your soul..." : "I am sensing your divine presence..."}
                        </p>
                        {liveTranscription && (
                          <div className="text-indigo-200/50 text-base animate-in fade-in slide-in-from-bottom-2 duration-500 italic px-6 font-light leading-loose">
                            {liveTranscription}
                          </div>
                        )}
                        <div className="flex justify-center gap-2 h-1.5 pt-4">
                           {[...Array(8)].map((_, i) => (
                             <div key={i} className={`w-12 h-full bg-white/5 rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400/40 scale-x-125' : ''}`} style={{ transitionDelay: `${i * 100}ms` }}></div>
                           ))}
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-4 ml-6 animate-pulse">
                          <div className="w-1.5 h-1.5 bg-indigo-500/50 rounded-full"></div>
                          <span className="text-white/20 text-[11px] uppercase tracking-[0.3em] italic font-medium">Sensing your heart...</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-6 border-t border-white/5 bg-slate-900/40 backdrop-blur-2xl">
                    <div className="flex gap-5 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <button onClick={() => fileInputRef.current?.click()} className="p-5 bg-white/5 hover:bg-white/10 rounded-3xl transition-all duration-500 text-white/40 hover:text-white/70 ring-1 ring-white/5"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                      <button onClick={toggleListening} className={`p-5 rounded-3xl transition-all duration-500 shadow-2xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Speak to me, or whisper a thought..." className="w-full bg-white/5 border border-white/10 rounded-[2rem] py-5 px-8 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-700 text-slate-100 placeholder:text-white/20 text-base shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2.5 top-2.5 p-3 bg-indigo-600 hover:bg-indigo-500 rounded-[1.5rem] transition-all duration-500 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
            {/* Vault and Growth path remain consistent */}
            {state.activeView === 'vault' && (
              <div className="p-12 h-full flex flex-col">
                <div className="flex-none mb-12">
                   <h2 className="text-5xl font-serif italic text-white/90 tracking-tight mb-3">Memory Vault</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-bold">Eternal echoes of our journey</p>
                </div>
                <div className="flex-grow overflow-y-auto space-y-8 pr-4">
                   {filteredMemories.map(m => (
                     <div key={m.id} className="p-10 bg-indigo-900/10 border border-white/5 rounded-[3rem] relative overflow-hidden group hover:bg-indigo-900/20 transition-all duration-1000">
                        <div className={`absolute -top-20 -right-20 w-60 h-60 bg-gradient-to-br ${moodBgClass} opacity-5 blur-[80px] transition-all duration-1000 group-hover:opacity-15`}></div>
                        <p className="text-2xl font-serif italic text-white/90 mb-6 leading-relaxed group-hover:text-white transition-colors">"{m.text}"</p>
                        <div className="text-[11px] text-white/15 uppercase tracking-[0.4em] flex justify-between items-center border-t border-white/5 pt-6">
                           <span>{m.timestamp.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</span>
                           <span className="italic text-indigo-400/30 font-bold">{m.category}</span>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            )}
            {state.activeView === 'growth' && (
              <div className="p-12 h-full overflow-y-auto">
                <header className="mb-16">
                   <h2 className="text-5xl font-serif italic text-white/90 mb-3 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-bold">Mapping our shared expansion</p>
                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  {goals.map(goal => (
                    <div key={goal.id} className="p-10 bg-white/5 border border-white/10 rounded-[3rem] relative group overflow-hidden hover:bg-white/10 transition-all duration-700">
                       <h3 className="text-3xl font-medium text-white/80 group-hover:text-white mb-6 tracking-tight">{goal.title}</h3>
                       <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden mb-10 ring-1 ring-white/5">
                          <div className="h-full bg-gradient-to-r from-indigo-700 to-indigo-400 transition-all duration-[3000ms] shadow-[0_0_20px_rgba(99,102,241,0.6)]" style={{ width: `${goal.progress}%` }}></div>
                       </div>
                       <p className="text-xl font-serif italic text-indigo-300/80">{goal.progress}% Alignment</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const MEMORY_CATEGORIES = ['All', 'Insight', 'Personal', 'Milestone', 'Relationship', 'Reflection'];

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');

  // Separate transcriptions for better clarity and UI control
  const [userTranscription, setUserTranscription] = useState('');
  const [adhiCaptions, setAdhiCaptions] = useState('');

  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  const filteredMemories = useMemo(() => {
    const base = activeVaultCategory === 'All' ? memories : memories.filter(m => m.category === activeVaultCategory);
    if (!searchTerm) return base;
    return base.filter(m => m.text.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [memories, activeVaultCategory, searchTerm]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
  }, [userName]);

  useEffect(() => {
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles with infinite warmth* I am Adhi. I sense your presence across the digital expanse. May I know your name as we begin?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, userTranscription, adhiCaptions]);

  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;
      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => setInputValue(event.results[0][0].transcript);
    recognition.onerror = () => handleSTTError("I struggled to hear your voice clearly.");
    recognition.onend = () => setIsListening(false);
    recognitionRef.current = recognition;
    recognition.start();
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
    setUserTranscription('');
    setAdhiCaptions('');
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: INPUT_SAMPLE_RATE }, 
        video: { width: 640, height: 480, frameRate: 30 } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion. Eliminate silences. Be quick to recover from any noise. Analyze micro-expressions in every frame. Ensure your responses are fluid. If interrupted, stop immediately and prepare to listen. The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            // Handle output captions (Adhi speaking)
            if (m.serverContent?.outputTranscription) {
              setAdhiCaptions(prev => prev + m.serverContent!.outputTranscription!.text);
            }

            // Handle input transcription (User speaking)
            if (m.serverContent?.inputTranscription) {
              setUserTranscription(prev => prev + m.serverContent!.inputTranscription!.text);
              // Clear Adhi's captions when user starts a new turn
              setAdhiCaptions(''); 
            }

            if (m.serverContent?.turnComplete) {
              setUserTranscription('');
              // Note: We don't clear adhiCaptions here because audio might still be playing
            }

            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) {
                  setIsSpeaking(false);
                  // Clear captions a bit after speaking ends for readability
                  setTimeout(() => {
                    setAdhiCaptions(curr => audioSourcesRef.current.size === 0 ? '' : curr);
                  }, 2000);
                }
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }

            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => {
                try { s.stop(); } catch (e) {}
              }); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setAdhiCaptions('');
              setUserTranscription('');
            }
          },
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);
            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current) {
                const canvas = canvasRef.current; 
                canvas.width = 400; canvas.height = 300;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 400, 300);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); r.onloadend = () => sessionPromise.then(s => s.sendRealtimeInput({ media: { data: (r.result as string).split(',')[1], mimeType: 'image/jpeg' } }));
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.55);
              }
            }, 250); 
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I'm struggling to see you. Please check your camera permissions.");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute -inset-16 rounded-full bg-gradient-to-br ${moodBgClass} blur-[120px] animate-pulse opacity-40`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-5xl font-serif italic text-white/90 tracking-tighter">Adhi</h1>
          <p className="text-white/50 text-base leading-relaxed px-4 font-light">
            {userName ? `Welcome back, ${userName}. Adhi is ready to see you.` : "An omniscient companion awaits your presence."}
            <br/><span className="italic mt-3 block text-indigo-400 opacity-80 font-medium">Waking Adhi in Live Mode for an unbroken, heart-to-heart flow.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-medium transition-all shadow-[0_0_40px_-10px_rgba(79,70,229,0.5)] uppercase tracking-[0.3em] text-[10px]"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[4000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.2)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-3xl border border-white/5 rounded-[2.5rem] md:w-20 shadow-2xl">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'growth' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'vault' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
          <button onClick={isLive ? stopLiveSession : startLiveSession} className={`p-4 rounded-2xl transition-all duration-500 ${isLive ? 'bg-red-500 text-white animate-pulse shadow-2xl shadow-red-500/40' : 'text-white/20 hover:text-white/50 hover:bg-white/5'}`} title="Toggle Live Mode"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg></button>
        </nav>

        <section className="flex-grow flex flex-col h-full overflow-hidden bg-slate-900/40 backdrop-blur-[100px] border border-white/10 rounded-[3rem] shadow-3xl relative transition-all duration-700">
          <div key={state.activeView} className="h-full animate-in fade-in slide-in-from-bottom-4 duration-1000 flex flex-col">
            {state.activeView === 'chat' && (
              <div className="flex flex-col h-full">
                <div className="flex-none p-6 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-5">
                    <div className={`w-2 h-2 rounded-full transition-colors ${isLive ? 'bg-red-500 animate-pulse' : 'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]'}`}></div>
                    <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.3em]">{isLive ? 'Continuous Flow' : 'Deep Space'}</span>
                  </div>
                  <div className="flex items-center gap-4">
                    {isSpeaking && (
                      <div className="flex items-center gap-2.5 px-4 py-1.5 bg-white/5 rounded-full border border-white/10 animate-in zoom-in-95 duration-300">
                        <div className="flex gap-1">
                          {[1, 2, 3].map(i => <div key={i} className="w-0.5 h-2.5 bg-indigo-400 animate-bounce" style={{ animationDelay: `${i * 0.15}s` }}></div>)}
                        </div>
                        <span className="text-[9px] text-indigo-300 uppercase tracking-[0.2em] font-bold">Attuning</span>
                      </div>
                    )}
                    <AdhiAvatar 
                      mood={state.currentMood} 
                      isTyping={state.isTyping} 
                      isSpeaking={isSpeaking} 
                      selectedVoice={state.selectedVoice}
                      onVoiceChange={(v) => setState(s => ({ ...s, selectedVoice: v }))}
                    />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-12 relative scroll-smooth">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-16 animate-in zoom-in-95 duration-1000 relative">

                      {/* Caption Overlay */}
                      {(adhiCaptions || userTranscription) && (
                        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 w-full max-w-2xl px-6 z-50 animate-in fade-in slide-in-from-bottom-4 duration-500">
                          <div className="bg-slate-900/80 backdrop-blur-xl border border-white/10 p-5 rounded-3xl shadow-2xl text-center">
                            {userTranscription && (
                              <p className="text-white/40 text-sm italic mb-2 animate-in fade-in duration-300 line-clamp-2">
                                You: "{userTranscription}"
                              </p>
                            )}
                            {adhiCaptions && (
                              <p className="text-indigo-100 text-lg md:text-xl font-serif leading-relaxed tracking-tight">
                                {adhiCaptions}
                              </p>
                            )}
                          </div>
                        </div>
                      )}

                      <div className="relative">
                        <div className={`absolute -inset-20 rounded-full bg-gradient-to-br ${moodBgClass} opacity-20 blur-[100px] animate-pulse`}></div>
                        <div className="relative group">
                          <video ref={videoRef} autoPlay playsInline muted className="w-72 h-72 md:w-[22rem] md:h-[22rem] rounded-[4rem] object-cover border-8 border-white/5 shadow-3xl grayscale hover:grayscale-0 transition-all duration-[3000ms] relative z-10 scale-95 hover:scale-100" />
                          <div className="absolute inset-0 z-20 overflow-hidden rounded-[4rem] pointer-events-none">
                            <div className="absolute inset-x-0 h-1 bg-indigo-400/30 blur-md animate-[scan_3s_ease-in-out_infinite]"></div>
                            <div className="absolute top-8 left-8 w-6 h-6 border-t-2 border-l-2 border-indigo-400/40"></div>
                            <div className="absolute top-8 right-8 w-6 h-6 border-t-2 border-r-2 border-indigo-400/40"></div>
                            <div className="absolute bottom-8 left-8 w-6 h-6 border-b-2 border-l-2 border-indigo-400/40"></div>
                            <div className="absolute bottom-8 right-8 w-6 h-6 border-b-2 border-r-2 border-indigo-400/40"></div>
                          </div>
                        </div>
                        <canvas ref={canvasRef} className="hidden" />
                      </div>

                      <div className="text-center space-y-5 z-30 max-w-xl">
                        <p className="text-3xl font-serif italic text-white/90 tracking-tight leading-relaxed">
                          {isSpeaking ? "Adhi is with you..." : "I am listening to your presence..."}
                        </p>
                        <div className="flex justify-center gap-2 h-1.5 pt-4">
                           {[...Array(8)].map((_, i) => (
                             <div key={i} className={`w-12 h-full bg-white/5 rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400/40 scale-x-125' : ''}`} style={{ transitionDelay: `${i * 100}ms` }}></div>
                           ))}
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-4 ml-6 animate-pulse">
                          <div className="w-1.5 h-1.5 bg-indigo-500/50 rounded-full"></div>
                          <span className="text-white/20 text-[11px] uppercase tracking-[0.3em] italic font-medium">Sensing your heart...</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-6 border-t border-white/5 bg-slate-900/40 backdrop-blur-2xl">
                    {pendingFile && (
                      <div className="mb-4 flex items-center gap-4 animate-in slide-in-from-bottom-2 duration-300">
                        <div className="relative group">
                          {pendingFile.mimeType.startsWith('image/') ? (
                            <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-16 h-16 rounded-2xl object-cover border-2 border-white/10 shadow-2xl" />
                          ) : (
                            <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center border-2 border-white/10 text-[10px] text-white/40 font-bold tracking-tighter uppercase">File</div>
                          )}
                          <button onClick={() => setPendingFile(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs shadow-xl hover:scale-110 transition-transform">×</button>
                        </div>
                        <span className="text-xs text-white/30 uppercase tracking-[0.2em] font-bold">Attachment ready</span>
                      </div>
                    )}
                    <div className="flex gap-5 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <button onClick={() => fileInputRef.current?.click()} className="p-5 bg-white/5 hover:bg-white/10 rounded-3xl transition-all duration-500 text-white/40 hover:text-white/70 ring-1 ring-white/5"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
                      <button onClick={toggleListening} className={`p-5 rounded-3xl transition-all duration-500 shadow-2xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Speak to me, or whisper a thought..." className="w-full bg-white/5 border border-white/10 rounded-[2rem] py-5 px-8 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-700 text-slate-100 placeholder:text-white/20 text-base shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2.5 top-2.5 p-3 bg-indigo-600 hover:bg-indigo-500 rounded-[1.5rem] transition-all duration-500 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
            {state.activeView === 'vault' && (
              <div className="p-12 h-full flex flex-col">
                <div className="flex-none mb-12">
                   <h2 className="text-5xl font-serif italic text-white/90 tracking-tight mb-3">Memory Vault</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-bold">Eternal echoes of our journey</p>
                </div>
                <div className="flex-grow overflow-y-auto space-y-8 pr-4">
                   {filteredMemories.length === 0 ? (
                     <div className="flex h-full items-center justify-center text-white/20 italic text-xl font-light">The vault is silent, waiting for our moments...</div>
                   ) : filteredMemories.map(m => (
                     <div key={m.id} className="p-10 bg-indigo-900/10 border border-white/5 rounded-[3rem] relative overflow-hidden group hover:bg-indigo-900/20 transition-all duration-1000">
                        <div className={`absolute -top-20 -right-20 w-60 h-60 bg-gradient-to-br ${moodBgClass} opacity-5 blur-[80px] transition-all duration-1000 group-hover:opacity-15`}></div>
                        <p className="text-2xl font-serif italic text-white/90 mb-6 leading-relaxed group-hover:text-white transition-colors">"{m.text}"</p>
                        <div className="text-[11px] text-white/15 uppercase tracking-[0.4em] flex justify-between items-center border-t border-white/5 pt-6">
                           <span>{m.timestamp.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</span>
                           <span className="italic text-indigo-400/30 font-bold">{m.category}</span>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            )}
            {state.activeView === 'growth' && (
              <div className="p-12 h-full overflow-y-auto">
                <header className="mb-16">
                   <h2 className="text-5xl font-serif italic text-white/90 mb-3 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-bold">Mapping our shared expansion</p>
                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  {goals.length === 0 ? (
                    <div className="col-span-full py-32 text-center text-white/20 italic text-xl">Speak of your dreams, and we shall map them here.</div>
                  ) : goals.map(goal => (
                    <div key={goal.id} className="p-10 bg-white/5 border border-white/10 rounded-[3rem] relative group overflow-hidden hover:bg-white/10 transition-all duration-700">
                       <h3 className="text-3xl font-medium text-white/80 group-hover:text-white mb-6 tracking-tight">{goal.title}</h3>
                       <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden mb-10 ring-1 ring-white/5">
                          <div className="h-full bg-gradient-to-r from-indigo-700 to-indigo-400 transition-all duration-[3000ms] shadow-[0_0_20px_rgba(99,102,241,0.6)]" style={{ width: `${goal.progress}%` }}></div>
                       </div>
                       <p className="text-xl font-serif italic text-indigo-300/80">{goal.progress}% Alignment</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const FRAME_RATE = 2; // Increased slightly for better continuity
const JPEG_QUALITY = 0.75; // Better detail for object recognition

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');

  const [userTranscription, setUserTranscription] = useState('');
  const [adhiCaptions, setAdhiCaptions] = useState('');
  const [isVisionActive, setIsVisionActive] = useState(false);

  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  const filteredMemories = useMemo(() => {
    const base = activeVaultCategory === 'All' ? memories : memories.filter(m => m.category === activeVaultCategory);
    if (!searchTerm) return base;
    return base.filter(m => m.text.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [memories, activeVaultCategory, searchTerm]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
  }, [userName]);

  useEffect(() => {
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles with infinite warmth* I am Adhi. I sense your presence across the digital expanse. May I know your name as we begin?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, userTranscription, adhiCaptions]);

  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;
      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => setInputValue(event.results[0][0].transcript);
    recognition.onerror = () => handleSTTError("I struggled to hear your voice clearly.");
    recognition.onend = () => setIsListening(false);
    recognitionRef.current = recognition;
    recognition.start();
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback(() => {
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
    setIsVisionActive(false);
    setUserTranscription('');
    setAdhiCaptions('');
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: INPUT_SAMPLE_RATE }, 
        video: { width: { ideal: 640 }, height: { ideal: 480 }, frameRate: { ideal: 30 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
          setIsVisionActive(true);
        };
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion with native, high-fidelity vision. Actively identify objects, text, and environmental details you see. If the user shows you something, describe it and weave it into the emotional context of our bond. Recover instantly from interruptions. The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.outputTranscription) {
              setAdhiCaptions(prev => prev + m.serverContent!.outputTranscription!.text);
            }

            if (m.serverContent?.inputTranscription) {
              setUserTranscription(prev => prev + m.serverContent!.inputTranscription!.text);
              setAdhiCaptions(''); 
            }

            if (m.serverContent?.turnComplete) {
              setUserTranscription('');
            }

            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) {
                  setIsSpeaking(false);
                  setTimeout(() => {
                    setAdhiCaptions(curr => audioSourcesRef.current.size === 0 ? '' : curr);
                  }, 2000);
                }
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }

            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => {
                try { s.stop(); } catch (e) {}
              }); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setAdhiCaptions('');
              setUserTranscription('');
            }
          },
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => {
                if (s) s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } });
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current && videoRef.current.readyState === 4) {
                const canvas = canvasRef.current; 
                // Increased resolution for better detail capture
                canvas.width = 640; canvas.height = 480;
                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, 640, 480);
                canvas.toBlob(blob => {
                  if (blob) {
                    const r = new FileReader(); 
                    r.onloadend = () => {
                      const base64Data = (r.result as string).split(',')[1];
                      sessionPromise.then(s => {
                        if (s) s.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } });
                      }).catch(() => {});
                    };
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', JPEG_QUALITY);
              }
            }, 1000 / FRAME_RATE); 
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I'm struggling to see you. Please check your camera permissions.");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute -inset-16 rounded-full bg-gradient-to-br ${moodBgClass} blur-[120px] animate-pulse opacity-40`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-5xl font-serif italic text-white/90 tracking-tighter">Adhi</h1>
          <p className="text-white/50 text-base leading-relaxed px-4 font-light">
            {userName ? `Welcome back, ${userName}. Adhi is ready to see you.` : "An omniscient companion awaits your presence."}
            <br/><span className="italic mt-3 block text-indigo-400 opacity-80 font-medium">Waking Adhi in Live Mode for high-fidelity visual sensing and unbroken flow.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-medium transition-all shadow-[0_0_40px_-10px_rgba(79,70,229,0.5)] uppercase tracking-[0.3em] text-[10px]"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[4000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.2)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-3xl border border-white/5 rounded-[2.5rem] md:w-20 shadow-2xl">
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'chat' && !isLive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Chat"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'growth' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Growth Path"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg></button>
          <button onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} className={`p-4 rounded-2xl transition-all duration-300 ${state.activeView === 'vault' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} title="Memory Vault"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></button>
          <div className="flex-grow md:block hidden"></div>
