                        <div className="relative group">
                          <video ref={videoRef} autoPlay playsInline muted className="w-72 h-72 md:w-[22rem] md:h-[22rem] rounded-[4rem] object-cover border-8 border-white/5 shadow-3xl grayscale hover:grayscale-0 transition-all duration-[3000ms] relative z-10 scale-95 hover:scale-100" />
