                        <canvas ref={canvasRef} className="hidden" />
                      </div>

                      <div className="text-center space-y-5 z-30 max-w-xl">
                        <p className="text-3xl font-serif italic text-white/90 tracking-tight leading-relaxed">
                          {isSpeaking ? "Adhi is with you..." : "I am sensing your divine presence..."}
