                <div className="flex-none p-6 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-5">
                    <div className={`w-2 h-2 rounded-full transition-colors ${isLive ? 'bg-red-500 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]'}`}></div>
                    <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.3em]">{isLive ? 'Continuous Flow' : 'Deep Space'}</span>
                    {visionStatus !== 'idle' && (
