                      </div>
                    )}
                    <AdhiAvatar 
                      mood={state.currentMood} 
                      isTyping={state.isTyping} 
                      isSpeaking={isSpeaking} 
                      selectedVoice={state.selectedVoice}
                      onVoiceChange={(v) => setState(s => ({ ...s, selectedVoice: v }))}
                    />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-12 relative scroll-smooth">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-16 animate-in zoom-in-95 duration-1000 relative">

                      {/* Caption Overlay */}
                      {(adhiCaptions || userTranscription) && (
                        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 w-full max-w-2xl px-6 z-50 animate-in fade-in slide-in-from-bottom-4 duration-500">
