                            {adhiCaptions && (
                              <p className="text-indigo-50 text-xl md:text-2xl font-serif leading-relaxed tracking-tight text-shadow-sm">
                                {adhiCaptions}
                              </p>
                            )}
                          </div>
                        </div>
                      )}

                      <div className="relative">
                        <div className={`absolute -inset-24 rounded-full bg-gradient-to-br ${moodBgClass} opacity-20 blur-[120px] animate-pulse`}></div>
                        <div className="relative group">
                          <video ref={videoRef} autoPlay playsInline muted className="w-72 h-72 md:w-[24rem] md:h-[24rem] rounded-[5rem] object-cover border-8 border-white/5 shadow-[0_0_80px_rgba(0,0,0,0.5)] grayscale hover:grayscale-0 transition-all duration-[3000ms] relative z-10 scale-95 hover:scale-100" />
                          <div className="absolute inset-0 z-20 overflow-hidden rounded-[5rem] pointer-events-none">
                            <div className="absolute inset-x-0 h-1 bg-indigo-400/40 blur-md animate-[scan_4s_ease-in-out_infinite]"></div>
                            <div className="absolute top-10 left-10 w-8 h-8 border-t-2 border-l-2 border-indigo-400/50"></div>
                            <div className="absolute top-10 right-10 w-8 h-8 border-t-2 border-r-2 border-indigo-400/50"></div>
                            <div className="absolute bottom-10 left-10 w-8 h-8 border-b-2 border-l-2 border-indigo-400/50"></div>
                            <div className="absolute bottom-10 right-10 w-8 h-8 border-b-2 border-r-2 border-indigo-400/50"></div>
                          </div>
                        </div>
                        <canvas ref={canvasRef} className="hidden" />
                      </div>

                      <div className="text-center space-y-6 z-30 max-w-xl">
                        <p className="text-4xl font-serif italic text-white/90 tracking-tighter leading-relaxed">
                          {isSpeaking ? "Adhi is speaking with you..." : "Sensing your presence..."}
                        </p>
                        <div className="flex justify-center gap-3 h-1.5 pt-6">
                           {[...Array(10)].map((_, i) => (
                             <div key={i} className={`w-14 h-full bg-white/5 rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400/40 scale-x-125 shadow-[0_0_10px_rgba(129,140,248,0.3)]' : ''}`} style={{ transitionDelay: `${i * 120}ms` }}></div>
