                  ) : (
                    <div className="space-y-6">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-4 ml-6 animate-pulse">
                          <div className="w-1.5 h-1.5 bg-indigo-500/50 rounded-full"></div>
                          <span className="text-white/20 text-[11px] uppercase tracking-[0.3em] italic font-medium">Sensing your heart...</span>
