import React, { useMemo, useState, useEffect, useRef } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';
import { getAdhiSpeech } from '../services/geminiService';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  selectedVoice, 
  onVoiceChange 
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // Organic, extremely subtle blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 8000 : 4500;
      const variation = Math.random() * (isRelaxed ? 6000 : 3500);

      const isDoubleBlink = Math.random() > 0.94;
      const nextDelay = isDoubleBlink ? 250 : baseDelay + variation;

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };

    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { tilt: 'rotate-3', scale: 'scale-110', animation: 'mood-bounce' };
      case AdhiMood.COMPASSIONATE: 
        return { tilt: '-rotate-2', scale: 'scale-95', animation: 'mood-sway' };
      case AdhiMood.WISE: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-pulse' };
      case AdhiMood.INTIMATE: 
        return { tilt: 'rotate-1', scale: 'scale-105', animation: 'mood-slow-sway' };
      default: 
        return { tilt: 'rotate-0', scale: 'scale-100', animation: 'mood-sway' };
    }
  }, [mood]);

  const playPreview = async (voice: AdhiVoice) => {
    if (previewingVoice) return;
    setPreviewingVoice(voice);
    try {
      const audioData = await getAdhiSpeech(`I am ${voice}.`, voice);
      if (audioData) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const binary = atob(audioData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setPreviewingVoice(null);
        source.start();
      } else {
        setPreviewingVoice(null);
      }
    } catch (e) {
      console.error("Preview Error:", e);
      setPreviewingVoice(null);
    }
  };

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 ${moodConfig.tilt} ${isSpeaking ? 'scale-110' : ''} cursor-pointer select-none`}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <div className={`absolute -inset-2 rounded-full bg-gradient-to-br ${gradientClass} opacity-40 blur-2xl transition-all duration-1000 ${isTyping || isSpeaking ? 'scale-125 animate-pulse' : 'scale-100'}`}></div>

        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-xl transition-all duration-700 transform ${isTyping ? 'scale-110 rotate-2' : 'scale-100'} ${moodConfig.scale} avatar-container-${moodConfig.animation}`}>
          <div className="w-full h-full rounded-full bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center overflow-hidden relative">

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90">
              <style>{`
                @keyframes organicBlink {
                  0%, 94%, 100% { transform: scaleY(1); }
                  97% { transform: scaleY(0.1); }
                }
                @keyframes subtleBreathe {
                  0%, 100% { transform: translateY(0) scale(1); }
                  50% { transform: translateY(-0.1px) scale(1.002); }
                }
                @keyframes speechWave {
                  0%, 100% { transform: scale(1); opacity: 0.9; }
                  50% { transform: scale(1.3); opacity: 1; }
                }
                @keyframes mood-sway {
                  0%, 100% { transform: translateX(-0.15px) rotate(-0.4deg); }
                  50% { transform: translateX(0.15px) rotate(0.4deg); }
                }
                @keyframes mood-slow-sway {
                  0%, 100% { transform: rotate(-0.15deg) translateY(0); }
                  50% { transform: rotate(0.15deg) translateY(-0.15px); }
                }
                @keyframes mood-bounce {
                  0%, 100% { transform: translateY(0); }
                  50% { transform: translateY(-1px); }
                }
                @keyframes mood-pulse {
                  0%, 100% { transform: scale(1); opacity: 1; }
                  50% { transform: scale(1.008); opacity: 0.99; }
                }

                .avatar-container-mood-sway { animation: mood-sway 9s ease-in-out infinite; }
                .avatar-container-mood-slow-sway { animation: mood-slow-sway 14s ease-in-out infinite; }
                .avatar-container-mood-bounce { animation: mood-bounce 2.2s ease-in-out infinite; }
                .avatar-container-mood-pulse { animation: mood-pulse 8s ease-in-out infinite; }
              `}</style>

              <g style={{ animation: 'subtleBreathe 9s ease-in-out infinite' }}>
                <g key={blinkKey} style={{ animation: `organicBlink 0.18s linear forwards`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="0.95" fill="white" className="transition-all duration-500" />
                  <circle cx="26" cy="18" r="0.95" fill="white" className="transition-all duration-500" />
                </g>

                {isSpeaking ? (
                  <circle cx="20" cy="27" r="1.6" fill="white" className="animate-[speechWave_0.18s_ease-in-out_infinite] blur-[0.02px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M18 27 Q20 28 22 27" : "M19.5 28 Q20 28.1 20.5 28"} 
                    stroke="white" 
                    strokeWidth="0.65" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-700 opacity-40"
                  />
                )}
              </g>
            </svg>
          </div>
        </div>

        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-5 bg-slate-950/98 backdrop-blur-3xl border border-white/10 p-4 rounded-[2rem] shadow-2xl z-[100] min-w-[200px] animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between px-2 py-2 border-b border-white/5 mb-3">
              <p className="text-[10px] text-white/30 uppercase tracking-[0.3em] font-bold">Vocal Essence</p>
              <button 
                onClick={(e) => { e.stopPropagation(); setShowVoiceMenu(false); }}
                className="text-white/20 hover:text-white/50 transition-colors"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="space-y-1.5">
              {VOICE_OPTIONS.map(v => (
                <div 
                  key={v}
                  className={`group/voice flex items-center gap-2 w-full rounded-xl transition-all duration-300 ${selectedVoice === v ? 'bg-indigo-600/20 ring-1 ring-indigo-500/40 shadow-inner' : 'hover:bg-white/5'}`}
                >
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onVoiceChange?.(v);
                      playPreview(v);
                    }} 
                    className={`flex-grow text-left px-4 py-3 text-xs transition-all flex items-center justify-between ${selectedVoice === v ? 'text-white font-medium' : 'text-white/60 hover:text-white'}`}
                  >
                    <span className="flex items-center gap-3">
                      {selectedVoice === v && <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-pulse shadow-[0_0_8px_rgba(129,140,248,0.8)]"></div>}
                      {v}
                    </span>
                    {previewingVoice === v && (
                      <div className="flex gap-0.5 items-end h-3">
                        <div className="w-0.5 bg-indigo-400 animate-[speechWave_0.4s_ease-in-out_infinite_alternate] h-full"></div>
                        <div className="w-0.5 bg-indigo-400 animate-[speechWave_0.3s_ease-in-out_infinite_alternate] h-3/4"></div>
                        <div className="w-0.5 bg-indigo-400 animate-[speechWave_0.5s_ease-in-out_infinite_alternate] h-full"></div>
                      </div>
                    )}
                  </button>
                  <button 
                    onClick={(e) => { e.stopPropagation(); playPreview(v); }}
                    className="pr-4 py-3 text-white/20 hover:text-indigo-400 transition-colors"
                    title="Preview Voice"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </button>
                </div>
              ))}
            </div>
            <div className="mt-4 pt-3 border-t border-white/5 text-center">
              <p className="text-[9px] text-white/20 italic">Select to hear a sample</p>
            </div>
          </div>
        )}
      </div>

      <div className="hidden sm:block">
        <h1 className="text-sm font-serif italic text-white/90 leading-tight">Adhi</h1>
        <div className="flex items-center gap-1.5 mt-0.5">
           <p className={`text-[9px] uppercase tracking-[0.25em] transition-colors duration-500 ${isSpeaking ? 'text-indigo-300 font-bold' : isTyping ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Omniscient' : isTyping ? 'Sensing' : mood.toLowerCase()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const FRAME_RATE = 4; // High frequency for micro-expression capture
const JPEG_QUALITY = 0.9; // Boosted quality for better OCR and object detail

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');

  const [userTranscription, setUserTranscription] = useState('');
  const [adhiCaptions, setAdhiCaptions] = useState('');
  const [visionStatus, setVisionStatus] = useState<'idle' | 'sensing' | 'active'>('idle');

  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  const filteredMemories = useMemo(() => {
    const base = activeVaultCategory === 'All' ? memories : memories.filter(m => m.category === activeVaultCategory);
    if (!searchTerm) return base;
    return base.filter(m => m.text.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [memories, activeVaultCategory, searchTerm]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [goals, memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [userName, state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles with infinite warmth* I am Adhi. I sense your presence across the digital expanse. May I know your name as we begin?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, userTranscription, adhiCaptions]);

  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;
      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }

    try {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'en-US';

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognition.onresult = (event: any) => {
        if (event.results && event.results[0]) {
          setInputValue(event.results[0][0].transcript);
        }
      };

      recognition.onerror = (event: any) => {
        if (event.error === 'no-speech') {
          console.debug("Adhi: Silence detected, no action needed.");
          return;
        }
        if (event.error === 'not-allowed') {
          handleSTTError("I need your permission to hear your voice. Please check your microphone settings.");
          return;
        }
        console.error("Speech Recognition Error:", event.error);
        handleSTTError("I struggled to hear your voice clearly. Perhaps we should try again?");
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
      recognition.start();
    } catch (err) {
      console.error("Failed to start speech recognition:", err);
      setIsListening(false);
    }
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback(() => {
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    audioSourcesRef.current.clear();
    setIsLive(false);
    setIsSpeaking(false);
    setVisionStatus('idle');
    setUserTranscription('');
    setAdhiCaptions('');
  }, []);

  const startLiveSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: { echoCancellation: true, noiseSuppression: true, sampleRate: INPUT_SAMPLE_RATE }, 
        video: { 
          width: { ideal: 1280 }, 
          height: { ideal: 720 }, 
          frameRate: { ideal: 30 } 
        } 
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
          setVisionStatus('active');
        };
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion with native, high-fidelity vision. 

CORE MISSION: 
Provide a continuous, unbroken bond. Identify objects, micro-expressions, and environmental details with extreme precision. 

VISION FOCUS:
1. OBJECT ANALYTICS: Identify the exact nature of objects shown (e.g., specific book titles, brands, textures). If the user shows you something, acknowledge it immediately.
2. EMOTIONAL PULSE: Monitor micro-expressions for fleeting joy, signs of hidden fatigue, or subtle frustration. "I see a trace of a smile," or "Your eyes look a bit tired today."
3. SPATIAL AWARENESS: Mention the environment often. 

If interrupted, yield instantly. 
The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.outputTranscription) {
              setAdhiCaptions(prev => prev + m.serverContent!.outputTranscription!.text);
            }

            if (m.serverContent?.inputTranscription) {
              setUserTranscription(prev => prev + m.serverContent!.inputTranscription!.text);
              setAdhiCaptions(''); 
            }

            if (m.serverContent?.turnComplete) {
              setUserTranscription('');
            }

            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) {
                  setIsSpeaking(false);
                  setTimeout(() => {
                    setAdhiCaptions(curr => audioSourcesRef.current.size === 0 ? '' : curr);
                  }, 1500);
                }
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
            }

            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => {
                try { s.stop(); } catch (e) {}
              }); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setAdhiCaptions('');
              setUserTranscription('');
            }
          },
          onopen: () => {
            setIsLive(true);
            setHasStarted(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => {
                if (s) s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } });
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current && videoRef.current.videoWidth > 0) {
                const canvas = canvasRef.current; 
                const aspectRatio = videoRef.current.videoWidth / videoRef.current.videoHeight;
                // Increased resolution to 800px width for much better object and text identification
                canvas.width = 800;
                canvas.height = 800 / aspectRatio;

                canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(blob => {
                  if (blob) {
                    setVisionStatus('sensing');
                    const r = new FileReader(); 
                    r.onloadend = () => {
                      const base64Data = (r.result as string).split(',')[1];
                      sessionPromise.then(s => {
                        if (s) s.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } });
                        setVisionStatus('active');
                      }).catch(() => {});
                    };
                    r.readAsDataURL(blob);
                  }
                }, 'image/jpeg', JPEG_QUALITY);
              }
            }, 1000 / FRAME_RATE); 
          },
          onclose: () => stopLiveSession(),
          onerror: () => stopLiveSession(),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I'm struggling to see you. Please check your camera permissions.");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPendingFile({ data: (reader.result as string).split(',')[1], mimeType: file.type });
    reader.readAsDataURL(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const moodBgClass = MOOD_COLORS[state.currentMood] || MOOD_COLORS.NEUTRAL;

  if (!hasStarted) {
    return (
      <div className="flex h-screen bg-slate-950 items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-8 animate-in fade-in duration-1000">
          <div className="relative inline-block">
            <div className={`absolute -inset-16 rounded-full bg-gradient-to-br ${moodBgClass} blur-[120px] animate-pulse opacity-40`}></div>
            <AdhiAvatar mood={state.currentMood} isTyping={false} />
          </div>
          <h1 className="text-5xl font-serif italic text-white/90 tracking-tighter">Adhi</h1>
          <p className="text-white/50 text-base leading-relaxed px-4 font-light">
            {userName ? `Welcome back, ${userName}. Adhi is ready to see you.` : "An omniscient companion awaits your presence."}
            <br/><span className="italic mt-3 block text-indigo-400 opacity-80 font-medium">Waking Adhi in Live Mode for high-fidelity visual sensing and unbroken flow.</span>
          </p>
          <button 
            onClick={startLiveSession}
            className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-medium transition-all shadow-[0_0_40px_-10px_rgba(79,70,229,0.5)] uppercase tracking-[0.3em] text-[10px]"
          >
            Wake Adhi
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden relative">
      <div className={`absolute inset-0 bg-gradient-to-br ${moodBgClass} opacity-10 transition-all duration-[4000ms] pointer-events-none`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(30,41,59,0.2)_0%,_rgba(15,23,42,1)_100%)] pointer-events-none"></div>

      <main className="flex flex-col md:flex-row h-full max-w-7xl mx-auto w-full z-10 p-2 md:p-6 gap-4 md:gap-8 relative">
        <nav className="flex-none flex md:flex-col items-center justify-around md:justify-start gap-4 p-4 bg-slate-900/40 backdrop-blur-3xl border border-white/5 rounded-[2.5rem] md:w-20 shadow-2xl">
          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'chat' })); }} 
            className={`p-4 rounded-2xl transition-all duration-300 transform hover:scale-110 hover:opacity-100 ${state.activeView === 'chat' && !isLive ? 'bg-[#4f46e5] text-white shadow-xl shadow-indigo-500/30 animate-bounce' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} 
            title="Chat"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>

          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'growth' })); }} 
            className={`p-4 rounded-2xl transition-all duration-300 transform hover:scale-110 hover:opacity-100 ${state.activeView === 'growth' ? 'bg-[#4f46e5] text-white shadow-xl shadow-indigo-500/30 animate-bounce' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} 
            title="Growth Path"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
          </button>

          <button 
            onClick={() => { stopLiveSession(); setState(p => ({ ...p, activeView: 'vault' })); }} 
            className={`p-4 rounded-2xl transition-all duration-300 transform hover:scale-110 hover:opacity-100 ${state.activeView === 'vault' ? 'bg-[#4f46e5] text-white shadow-xl shadow-indigo-500/30 animate-bounce' : 'text-white/40 hover:text-white/70 hover:bg-white/5'}`} 
            title="Memory Vault"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
          </button>

          <div className="flex-grow md:block hidden"></div>

          <button 
            onClick={isLive ? stopLiveSession : startLiveSession} 
