                        <div className={`w-1 h-1 rounded-full ${visionStatus === 'active' ? 'bg-indigo-400' : 'bg-indigo-400 animate-ping'}`}></div>
                        <span className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">{visionStatus === 'active' ? 'Iris Analytical' : 'Sensing...'}</span>
