                    <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.3em]">{isLive ? 'Continuous Flow' : 'Deep Space'}</span>
                    {visionStatus !== 'idle' && (
                      <div className={`flex items-center gap-2 px-3 py-1 ${visionStatus === 'inhibited' ? 'bg-red-500/10 border-red-500/20' : 'bg-indigo-500/10 border-indigo-500/20'} rounded-full border animate-in zoom-in-95 duration-300`}>
                        <div className={`w-1 h-1 rounded-full ${visionStatus === 'inhibited' ? 'bg-red-400' : visionStatus === 'active' ? 'bg-indigo-400' : 'bg-indigo-400 animate-ping'}`}></div>
                        <span className={`text-[9px] font-bold uppercase tracking-widest ${visionStatus === 'inhibited' ? 'text-red-400' : 'text-indigo-400'}`}>{visionStatus === 'inhibited' ? 'Vision inhibited' : visionStatus === 'active' ? 'Iris Analytical' : 'Sensing...'}</span>
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-4">
                    {isSpeaking && (
                      <div className="flex items-center gap-2.5 px-4 py-1.5 bg-white/5 rounded-full border border-white/10 animate-in zoom-in-95 duration-300">
                        <div className="flex gap-1">
                          {[1, 2, 3].map(i => <div key={i} className="w-0.5 h-2.5 bg-indigo-400 animate-bounce" style={{ animationDelay: `${i * 0.15}s` }}></div>)}
                        </div>
                        <span className="text-[9px] text-indigo-300 uppercase tracking-[0.2em] font-bold">Attuning</span>
                      </div>
                    )}
                    <AdhiAvatar 
                      mood={state.currentMood} 
                      isTyping={state.isTyping} 
                      isSpeaking={isSpeaking} 
                      selectedVoice={state.selectedVoice}
                      onVoiceChange={(v) => setState(s => ({ ...s, selectedVoice: v }))}
                    />
                  </div>
                </div>

                <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 md:p-12 relative scroll-smooth">
                  {isLive ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-16 animate-in zoom-in-95 duration-1000 relative">

                      {(adhiCaptions || userTranscription) && (
                        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 w-full max-w-2xl px-6 z-50 animate-in fade-in slide-in-from-bottom-4 duration-500">
                          <div className="bg-slate-900/90 backdrop-blur-2xl border border-white/10 p-6 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] text-center">
