export default AdhiAvatar;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';
import { getAdhiSpeech } from '../services/geminiService';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  isListening?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
  visionStatus?: 'idle' | 'sensing' | 'active' | 'inhibited';
  scale?: number;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  isListening,
  selectedVoice, 
  onVoiceChange,
  visionStatus = 'idle',
  scale = 1
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const isAnalytical = visionStatus === 'active' || visionStatus === 'sensing';

  // Organic, extremely subtle blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 8000 : 4500;
      const variation = Math.random() * (isRelaxed ? 6000 : 3500);

      const isDoubleBlink = Math.random() > 0.94;
      const nextDelay = isDoubleBlink ? 250 : baseDelay + variation;

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };

    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { tilt: 'rotate-3', avatarScale: 'scale-110', animation: 'mood-bounce' };
      case AdhiMood.COMPASSIONATE: 
        return { tilt: '-rotate-2', avatarScale: 'scale-95', animation: 'mood-sway' };
      case AdhiMood.WISE: 
        return { tilt: 'rotate-0', avatarScale: 'scale-100', animation: 'mood-pulse' };
      case AdhiMood.INTIMATE: 
        return { tilt: 'rotate-1', avatarScale: 'scale-105', animation: 'mood-slow-sway' };
      default: 
        return { tilt: 'rotate-0', avatarScale: 'scale-100', animation: 'mood-sway' };
    }
  }, [mood]);

  const playPreview = async (voice: AdhiVoice) => {
    if (previewingVoice) return;
    setPreviewingVoice(voice);
    try {
      const audioData = await getAdhiSpeech(`I am ${voice}.`, voice);
      if (audioData) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const binary = atob(audioData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setPreviewingVoice(null);
        source.start();
      } else {
        setPreviewingVoice(null);
      }
    } catch (e) {
      console.error("Preview Error:", e);
      setPreviewingVoice(null);
    }
  };

  const finalScale = (isAnalytical || isSpeaking || isListening ? scale * 1.15 : scale);

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 ${moodConfig.tilt} cursor-pointer select-none`}
        style={{ transform: `scale(${finalScale})` }}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <style>{`
          @keyframes organicBlink {
            0%, 94%, 100% { transform: scaleY(1); }
            97% { transform: scaleY(0.1); }
          }
          @keyframes subtleBreathe {
            0%, 100% { transform: translateY(0) scale(1); }
            50% { transform: translateY(-0.1px) scale(1.002); }
          }
          @keyframes speechWave {
            0%, 100% { transform: scale(1); opacity: 0.9; }
            50% { transform: scale(1.3); opacity: 1; }
          }
          @keyframes listenWave {
            0%, 100% { transform: scale(1.05); opacity: 0.3; }
            50% { transform: scale(1.2); opacity: 0.6; }
          }
          @keyframes visionPulse {
            0%, 100% { stroke-opacity: 0.3; stroke-width: 0.5; transform: scale(1); }
            50% { stroke-opacity: 0.8; stroke-width: 1.5; transform: scale(1.05); }
          }
          @keyframes irisScan {
            0% { transform: translateY(-10px); opacity: 0; }
            50% { opacity: 0.6; }
            100% { transform: translateY(10px); opacity: 0; }
          }
          @keyframes mood-sway {
            0%, 100% { transform: translateX(-0.5px) rotate(-0.8deg); }
            50% { transform: translateX(0.5px) rotate(0.8deg); }
          }
          @keyframes mood-slow-sway {
            0%, 100% { transform: rotate(-0.3deg) translateY(0); }
            50% { transform: rotate(0.3deg) translateY(-0.5px); }
          }
          @keyframes mood-bounce {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-2.5px) scale(1.02); }
          }
          @keyframes mood-pulse {
            0%, 100% { transform: scale(1); opacity: 1; }
            50% { transform: scale(1.02); opacity: 0.95; }
          }

          .adhi-animate-sway { animation: mood-sway 6s ease-in-out infinite; }
          .adhi-animate-slow-sway { animation: mood-slow-sway 10s ease-in-out infinite; }
          .adhi-animate-bounce { animation: mood-bounce 1.5s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite; }
          .adhi-animate-pulse { animation: mood-pulse 5s ease-in-out infinite; }
        `}</style>

        {/* Outer Visual Aura */}
        <div className={`absolute -inset-4 rounded-full bg-cyan-400 transition-all duration-700 blur-2xl ${isListening ? 'opacity-30 scale-150 animate-pulse' : 'opacity-0 scale-100'}`}></div>
        <div className={`absolute -inset-3 rounded-full bg-gradient-to-br ${gradientClass} transition-all duration-1000 ${isTyping || isSpeaking || isAnalytical ? 'opacity-50 blur-3xl scale-150 animate-pulse' : 'opacity-30 blur-2xl scale-100'}`}></div>

        {/* Main Avatar Body */}
        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[1.5px] shadow-2xl transition-all duration-700 transform ${isTyping ? 'scale-110' : 'scale-100'} ${moodConfig.avatarScale} adhi-animate-${moodConfig.animation.replace('mood-', '')}`}>
          <div className="w-full h-full rounded-full bg-slate-900/95 backdrop-blur-2xl flex flex-col items-center justify-center overflow-hidden relative border border-white/5">

            {/* Analytical Visual Data Overlays */}
            {isAnalytical && (
              <div className="absolute inset-0 z-0 opacity-40">
                <div className="absolute inset-0 border-[0.5px] border-indigo-400/40 rounded-full animate-[spin_12s_linear_infinite]"></div>
                <div className="absolute inset-1 border-[0.5px] border-dashed border-indigo-300/20 rounded-full animate-[spin_18s_linear_infinite_reverse]"></div>
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_transparent_50%,_rgba(129,140,248,0.2)_100%)]"></div>
              </div>
            )}

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 opacity-90 relative z-10">
              <g style={{ animation: 'subtleBreathe 10s ease-in-out infinite' }}>

                {/* Horizontal Scanline for Vision Sensing */}
                {isAnalytical && (
                  <rect x="2" y="10" width="36" height="0.8" fill="#818cf8" className="animate-[irisScan_1.8s_ease-in-out_infinite]" />
                )}

                {/* Eyes with Blinking Logic */}
                <g key={blinkKey} style={{ animation: `organicBlink 0.18s linear forwards`, transformOrigin: 'center 18px' }}>
                  <circle cx="14" cy="18" r="1.1" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-500 shadow-sm" />
                  <circle cx="26" cy="18" r="1.1" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-500 shadow-sm" />

                  {isAnalytical && (
                    <circle cx="20" cy="18" r="12" stroke="#818cf8" fill="none" className="animate-[visionPulse_4s_ease-in-out_infinite]" />
                  )}
                </g>

                {/* Mouth and Expression State */}
                {isSpeaking ? (
                  <circle cx="20" cy="27" r="1.8" fill="white" className="animate-[speechWave_0.15s_ease-in-out_infinite] blur-[0.1px]" />
                ) : isListening ? (
                  <circle cx="20" cy="27" r="1.4" fill="#22d3ee" className="animate-[listenWave_0.6s_ease-in-out_infinite] blur-[0.3px]" />
                ) : (
                  <path 
                    d={mood === AdhiMood.JOYFUL ? "M17 26.5 Q20 28.5 23 26.5" : "M19 27.5 Q20 27.7 21 27.5"} 
                    stroke="white" 
                    strokeWidth="0.8" 
                    fill="none" 
                    strokeLinecap="round"
                    className="transition-all duration-1000 opacity-60"
                  />
                )}
              </g>
            </svg>
          </div>
        </div>

        {/* Voice Selection Context Menu */}
        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-6 bg-slate-950/95 backdrop-blur-3xl border border-white/10 p-5 rounded-[2.5rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.7)] z-[100] min-w-[220px] animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between px-2 py-2 border-b border-white/10 mb-4">
              <p className="text-[10px] text-white/40 uppercase tracking-[0.4em] font-black">Vocal Matrix</p>
              <button 
                onClick={(e) => { e.stopPropagation(); setShowVoiceMenu(false); }}
                className="text-white/30 hover:text-white/80 transition-colors"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="space-y-2">
              {VOICE_OPTIONS.map(v => (
                <div 
                  key={v}
                  className={`group/voice flex items-center gap-2 w-full rounded-2xl transition-all duration-300 ${selectedVoice === v ? 'bg-indigo-600/30 ring-1 ring-indigo-500/50' : 'hover:bg-white/5'}`}
                >
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onVoiceChange?.(v);
                      playPreview(v);
                    }} 
                    className={`flex-grow text-left px-5 py-4 text-[13px] transition-all flex items-center justify-between ${selectedVoice === v ? 'text-white font-bold' : 'text-white/50 hover:text-white'}`}
                  >
