                  </div>
                  <div className="flex items-center gap-4">
                    {isListening && (
                      <div className="flex items-center gap-2.5 px-4 py-1.5 bg-cyan-500/10 rounded-full border border-cyan-500/20 animate-in zoom-in-95 duration-300">
