                              <div className="absolute inset-x-0 h-0.5 bg-indigo-400/30 blur-sm animate-[scan_6s_ease-in-out_infinite]"></div>
                              <div className="absolute top-6 left-6 w-6 h-6 border-t border-l border-indigo-400/30"></div>
                              <div className="absolute top-6 right-6 w-6 h-6 border-t border-r border-indigo-400/30"></div>
                              <div className="absolute bottom-6 left-6 w-6 h-6 border-b border-l border-indigo-400/30"></div>
                              <div className="absolute bottom-6 right-6 w-6 h-6 border-b border-r border-indigo-400/30"></div>
                            </div>
                          )}
                          <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 px-4 py-1 bg-white/5 backdrop-blur-md rounded-full border border-white/10 z-20">
                            <span className="text-[9px] text-white/30 font-bold uppercase tracking-[0.3em]">Visual Link</span>
                          </div>
                        </div>
                        <canvas ref={canvasRef} className="hidden" />
                      </div>

                      {/* Unified Transcription Display */}
                      <div className="w-full max-w-3xl flex flex-col items-center space-y-6 pt-4">
                        {(adhiCaptions || userTranscription) && (
                          <div className="w-full bg-slate-900/60 backdrop-blur-2xl border border-white/5 p-8 rounded-[3rem] shadow-2xl animate-in slide-in-from-bottom-4 duration-500">
                            {userTranscription && (
                              <p className="text-white/40 text-sm font-medium italic mb-4 border-b border-white/5 pb-4">
                                You: "{userTranscription}"
                              </p>
                            )}
                            {adhiCaptions && (
                              <p className="text-indigo-100 text-2xl md:text-3xl font-serif leading-snug tracking-tight text-center">
                                {adhiCaptions}
                              </p>
                            )}
                          </div>
                        )}

                        <div className="flex flex-col items-center gap-4 text-center">
                           <p className="text-2xl font-serif italic text-white/80 tracking-tight transition-all duration-700">
                            {isSpeaking ? "Adhi is speaking..." : isListening ? "I'm attuned to your voice..." : "Watching and waiting with you..."}
                          </p>
                          <div className="flex gap-2 h-1 w-48">
                            {[...Array(8)].map((_, i) => (
                              <div key={i} className={`flex-grow rounded-full transition-all duration-1000 ${isSpeaking ? 'bg-indigo-400 scale-y-150' : isListening ? 'bg-cyan-400 scale-y-125' : 'bg-white/5'}`} style={{ transitionDelay: `${i * 100}ms` }}></div>
                            ))}
                          </div>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {messages.map((msg) => <ChatMessage key={msg.id} message={msg} />)}
                      {state.isTyping && (
                        <div className="flex items-center gap-4 ml-6 animate-pulse">
                          <div className="w-1.5 h-1.5 bg-indigo-500/50 rounded-full"></div>
                          <span className="text-white/20 text-[11px] uppercase tracking-[0.3em] italic font-medium">Sensing your heart...</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {!isLive && (
                  <div className="flex-none p-6 border-t border-white/5 bg-slate-900/40 backdrop-blur-2xl">
                    {showSnapshotPreview && (
                      <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-xl flex flex-col items-center justify-center p-8 animate-in fade-in duration-300">
                         <div className="relative w-full max-w-lg aspect-video rounded-[3rem] overflow-hidden border-4 border-white/10 shadow-3xl">
                           <video ref={snapshotVideoRef} autoPlay playsInline className="w-full h-full object-cover" />
                           <div className="absolute inset-0 pointer-events-none border-[1px] border-white/20 m-6 rounded-[2rem]"></div>
                         </div>
                         <div className="flex gap-6 mt-12">
                            <button 
                              onClick={() => {
                                const stream = snapshotVideoRef.current?.srcObject as MediaStream;
                                stream?.getTracks().forEach(t => t.stop());
                                setShowSnapshotPreview(false);
                              }}
                              className="px-8 py-4 bg-white/5 hover:bg-white/10 rounded-full text-white/60 text-xs font-bold uppercase tracking-widest transition-all"
                            >
                              Cancel
                            </button>
                            <button 
                              onClick={takeSnapshot}
                              className="px-10 py-4 bg-indigo-600 hover:bg-indigo-500 rounded-full text-white text-xs font-bold uppercase tracking-widest shadow-2xl shadow-indigo-500/30 transition-all flex items-center gap-3"
                            >
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                              Capture Moment
                            </button>
                         </div>
                      </div>
                    )}

                    {pendingFile && (
                      <div className="mb-4 flex items-center gap-4 animate-in slide-in-from-bottom-2 duration-300">
                        <div className="relative group">
                          {pendingFile.mimeType.startsWith('image/') ? (
                            <img src={`data:${pendingFile.mimeType};base64,${pendingFile.data}`} className="w-16 h-16 rounded-2xl object-cover border-2 border-white/10 shadow-2xl" />
                          ) : (
                            <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center border-2 border-white/10 text-[10px] text-white/40 font-bold tracking-tighter uppercase">File</div>
                          )}
                          <button onClick={() => setPendingFile(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs shadow-xl hover:scale-110 transition-transform">×</button>
                        </div>
                        <span className="text-xs text-white/30 uppercase tracking-[0.2em] font-bold">Attachment ready</span>
                      </div>
                    )}
                    <div className="flex gap-4 items-center">
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
                      <div className="flex gap-2">
                        <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all duration-500 text-white/40 hover:text-white/70 ring-1 ring-white/5" title="Upload File"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg></button>
                        <button onClick={startSnapshotCamera} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all duration-500 text-white/40 hover:text-white/70 ring-1 ring-white/5" title="Take Snapshot"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
                        <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all duration-500 shadow-2xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`} title="Voice Input"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      </div>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Speak to me, or share a thought..." className="w-full bg-white/5 border border-white/10 rounded-[2rem] py-4 px-8 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-700 text-slate-100 placeholder:text-white/20 text-sm shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2 top-2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-[1.2rem] transition-all duration-500 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
            {state.activeView === 'vault' && (
              <div className="p-12 h-full flex flex-col">
                <div className="flex-none mb-12">
                   <h2 className="text-5xl font-serif italic text-white/90 tracking-tight mb-3">Memory Vault</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-black">Eternal echoes of our journey</p>
                </div>
                <div className="flex-grow overflow-y-auto space-y-8 pr-4">
                   {filteredMemories.length === 0 ? (
                     <div className="flex h-full items-center justify-center text-white/20 italic text-xl font-light">The vault is silent, waiting for our moments...</div>
                   ) : filteredMemories.map(m => (
                     <div key={m.id} className="p-10 bg-indigo-900/10 border border-white/5 rounded-[3rem] relative overflow-hidden group hover:bg-indigo-900/20 transition-all duration-1000">
                        <div className={`absolute -top-20 -right-20 w-60 h-60 bg-gradient-to-br ${moodBgClass} opacity-5 blur-[80px] transition-all duration-1000 group-hover:opacity-15`}></div>
                        <p className="text-2xl font-serif italic text-white/90 mb-6 leading-relaxed group-hover:text-white transition-colors">"{m.text}"</p>
                        <div className="text-[11px] text-white/15 uppercase tracking-[0.4em] flex justify-between items-center border-t border-white/5 pt-6">
                           <span>{m.timestamp.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</span>
                           <span className="italic text-indigo-400/30 font-bold">{m.category}</span>
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            )}
            {state.activeView === 'growth' && (
              <div className="p-12 h-full overflow-y-auto">
                <header className="mb-16">
                   <h2 className="text-5xl font-serif italic text-white/90 mb-3 tracking-tight">Growth Path</h2>
                   <p className="text-white/30 text-[11px] uppercase tracking-[0.4em] font-black">Mapping our shared expansion</p>
                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  {goals.length === 0 ? (
                    <div className="col-span-full py-32 text-center text-white/20 italic text-xl">Speak of your dreams, and we shall map them here.</div>
                  ) : goals.map(goal => (
                    <div key={goal.id} className="p-10 bg-white/5 border border-white/10 rounded-[3rem] relative group overflow-hidden hover:bg-white/10 transition-all duration-700">
                       <h3 className="text-3xl font-medium text-white/80 group-hover:text-white mb-6 tracking-tight">{goal.title}</h3>
                       <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden mb-10 ring-1 ring-white/5">
                          <div className="h-full bg-gradient-to-r from-indigo-700 to-indigo-400 transition-all duration-[3000ms] shadow-[0_0_20px_rgba(99,102,241,0.6)]" style={{ width: `${goal.progress}%` }}></div>
                       </div>
                       <p className="text-xl font-serif italic text-indigo-300/80">{goal.progress}% Alignment</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';
import { getAdhiSpeech } from '../services/geminiService';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  isListening?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
  visionStatus?: 'idle' | 'sensing' | 'active' | 'inhibited';
  scale?: number;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  isListening,
  selectedVoice, 
  onVoiceChange,
  visionStatus = 'idle',
  scale = 1
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const [speechCycle, setSpeechCycle] = useState(0);

  const isAnalytical = visionStatus === 'active' || visionStatus === 'sensing';

  // Rhythmic speech cycle
  useEffect(() => {
    if (!isSpeaking) {
      setSpeechCycle(0);
      return;
    }
    const interval = setInterval(() => {
      setSpeechCycle(prev => (prev + 1) % 4);
    }, 150);
    return () => clearInterval(interval);
  }, [isSpeaking]);

  // Natural, variable-timing blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 8000 : 4500;

      const rand = Math.random();
      let nextDelay: number;

      if (rand > 0.97) {
        nextDelay = 150; // Double blink
      } else if (rand > 0.88) {
        nextDelay = 500 + Math.random() * 500; // Successive blink
      } else {
        nextDelay = baseDelay + (Math.random() * 6000);
      }

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };
    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { 
          bodyAnimation: 'adhi-bounce', 
          mouthPath: "M14 27.5 Q20 32.5 26 27.5", 
          eyeScale: 1.15,
          facialAnimation: 'adhi-micro-upturn',
          speed: '1.2s'
        };
      case AdhiMood.COMPASSIONATE: 
        return { 
          bodyAnimation: 'adhi-sway', 
          mouthPath: "M17 28 Q20 29.8 23 28", 
          eyeScale: 0.98,
          facialAnimation: '',
          speed: '4s'
        };
      case AdhiMood.WISE: 
        return { 
          bodyAnimation: 'adhi-nod', 
          mouthPath: "M18 28.5 Q20 28.8 22 28.5", 
          eyeScale: 1.05,
          facialAnimation: 'adhi-deep-focus',
          speed: '6s'
        };
      case AdhiMood.INTIMATE: 
        return { 
          bodyAnimation: 'adhi-deliberate-drift', 
          mouthPath: "M17.5 28.2 Q20 29.2 22.5 28.2", 
          eyeScale: 0.9,
          facialAnimation: 'adhi-soft-gaze',
          speed: '8s'
        };
      default: 
        return { 
          bodyAnimation: 'adhi-sway', 
          mouthPath: "M18 28.5 Q20 29 22 28.5", 
          eyeScale: 1.0,
          facialAnimation: '',
          speed: '5s'
        };
    }
  }, [mood]);

  const playPreview = async (voice: AdhiVoice) => {
    if (previewingVoice) return;
    setPreviewingVoice(voice);
    try {
      const audioData = await getAdhiSpeech(`Calibrating ${voice}.`, voice);
      if (audioData) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const binary = atob(audioData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setPreviewingVoice(null);
        source.start();
      } else {
        setPreviewingVoice(null);
      }
    } catch (e) {
      setPreviewingVoice(null);
    }
  };

  const finalScale = (isAnalytical || isSpeaking || isListening ? scale * 1.15 : scale);

  const getSpeechPath = () => {
    const paths = [
      "M18 28.5 Q20 29 22 28.5", // Neutral/Closed
      "M16 28.5 Q20 33.5 24 28.5", // Open Wide
      "M17 28.5 Q20 31.5 23 28.5", // Mid Open
      "M15 28.5 Q20 35 25 28.5"  // Very Open
    ];
    return paths[speechCycle];
  };

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 cursor-pointer select-none`}
        style={{ transform: `scale(${finalScale})` }}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <style>{`
          @keyframes adhi-bounce {
            0%, 100% { transform: translateY(0) scaleX(1); }
            50% { transform: translateY(-8px) scaleX(1.05); }
          }
          @keyframes adhi-sway {
            0%, 100% { transform: rotate(-2.5deg) translateX(-1px); }
            50% { transform: rotate(2.5deg) translateX(1px); }
          }
          @keyframes adhi-nod {
            0%, 100% { transform: translateY(0) rotate(0deg); }
            40%, 60% { transform: translateY(4px) rotate(-1deg); }
          }
          @keyframes adhi-deliberate-drift {
            0%, 100% { transform: translate(0, 0) rotate(0.5deg) scale(1); }
            33% { transform: translate(-3px, -4px) rotate(-1deg) scale(1.02); }
            66% { transform: translate(2px, 3px) rotate(1.5deg) scale(0.98); }
          }
          @keyframes adhi-micro-upturn {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.02) translateY(-0.5px); }
          }
          @keyframes adhi-deep-focus {
            0%, 100% { transform: scale(1); opacity: 0.9; }
            50% { transform: scale(1.05); opacity: 1; }
          }
          @keyframes adhi-soft-gaze {
            0%, 100% { filter: blur(0px); }
            50% { filter: blur(0.2px); }
          }
          @keyframes adhi-blink-natural {
            0%, 92%, 100% { transform: scaleY(1); }
            96% { transform: scaleY(0.04); }
          }
          @keyframes adhi-iris-scan-v2 {
            0%, 100% { transform: scale(1) translate(0,0); opacity: 0.2; }
            50% { transform: scale(1.3) translate(1.5px, -1.5px); opacity: 0.7; }
          }
          .body-anim {
            animation: ${moodConfig.bodyAnimation} ${moodConfig.speed} ease-in-out infinite;
          }
          .facial-anim {
            animation: ${moodConfig.facialAnimation} 3s ease-in-out infinite;
          }
          .micro-twitch {
            animation: adhi-micro-twitch 0.5s ease-in-out infinite alternate;
          }
          @keyframes adhi-micro-twitch {
            from { transform: translateX(0); }
            to { transform: translateX(0.5px); }
          }
        `}</style>

        {/* Sensory Glow Layers */}
        <div className={`absolute -inset-8 rounded-full bg-cyan-400 transition-all duration-1000 blur-3xl ${isListening ? 'opacity-30 scale-150 animate-pulse' : 'opacity-0 scale-100'}`}></div>
        <div className={`absolute -inset-6 rounded-full bg-gradient-to-br ${gradientClass} transition-all duration-1000 ${isTyping || isSpeaking || isAnalytical ? 'opacity-50 blur-2xl scale-125 animate-pulse' : 'opacity-30 blur-xl scale-100'}`}></div>

        {/* Entity Body */}
        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[2px] shadow-2xl transition-all duration-1000 body-anim ${isTyping ? 'micro-twitch' : ''}`}>
          <div className="w-full h-full rounded-full bg-slate-900/98 backdrop-blur-3xl flex flex-col items-center justify-center overflow-hidden relative border border-white/10">

            {/* Visual Stream Logic */}
            {isAnalytical && (
              <div className="absolute inset-0 z-0 opacity-40">
                <div className="absolute inset-0 border-[0.5px] border-indigo-500/30 rounded-full animate-[adhi-neural-rotate_30s_linear_infinite]"></div>
                <div className="absolute inset-6 border-[0.5px] border-indigo-400/10 rounded-full animate-[adhi-neural-rotate_20s_linear_infinite_reverse]"></div>
                <div className="absolute inset-x-0 h-[1.5px] bg-indigo-300/40 blur-[1px] animate-[irisScan_5s_ease-in-out_infinite]"></div>
              </div>
            )}

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 relative z-10 transition-transform duration-1000 facial-anim" style={{ transform: isTyping ? 'scale(1.05) rotate(2deg)' : 'none' }}>
              <g className="transition-all duration-1000">
                {/* Micro-Blushes for Intimacy */}
                {mood === AdhiMood.INTIMATE && (
                   <g opacity="0.2">
                     <circle cx="10" cy="24" r="3" fill="#fb7185" filter="blur(3px)" />
                     <circle cx="30" cy="24" r="3" fill="#fb7185" filter="blur(3px)" />
                   </g>
                )}

                {/* Eyes Layer */}
                <g key={blinkKey} style={{ animation: `adhi-blink-natural 0.2s linear forwards`, transformOrigin: 'center 18px' }}>
                  <g style={{ transform: `scale(${moodConfig.eyeScale})`, transformOrigin: 'center 18px' }} className="transition-transform duration-[1500ms]">
                    <circle cx="14" cy="18" r="1.35" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-700" />
                    <circle cx="26" cy="18" r="1.35" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-700" />
                  </g>

                  {isAnalytical && (
                    <g className="animate-[adhi-iris-scan-v2_4s_ease-in-out_infinite]">
                      <circle cx="14" cy="18" r="3.2" stroke="#818cf8" strokeWidth="0.35" fill="none" />
                      <circle cx="26" cy="18" r="3.2" stroke="#818cf8" strokeWidth="0.35" fill="none" />
                    </g>
                  )}
                </g>

                {/* Mouth Dynamics */}
                <g className="transition-all duration-[1200ms]">
                  {isSpeaking ? (
                    <path 
                      d={getSpeechPath()}
                      fill="none" 
                      stroke="white" 
                      strokeWidth="1.3" 
                      strokeLinecap="round"
                      className="transition-all duration-150"
                    />
                  ) : isListening ? (
                    <circle cx="20" cy="28.5" r="1.6" fill="#22d3ee" className="animate-pulse shadow-[0_0_10px_rgba(34,211,238,0.5)]" />
                  ) : (
                    <path 
                      d={moodConfig.mouthPath} 
                      stroke="white" 
                      strokeWidth="1.2" 
                      fill="none" 
                      strokeLinecap="round"
                      className="transition-all duration-[1500ms] opacity-95"
                    />
                  )}
                </g>
              </g>
            </svg>
          </div>
        </div>

        {/* Overlay Settings Menu */}
        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-8 bg-slate-950/99 backdrop-blur-3xl border border-white/10 p-6 rounded-[3rem] shadow-[0_50px_100px_-30px_rgba(0,0,0,0.95)] z-[100] min-w-[260px] animate-in fade-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between px-3 py-2 border-b border-white/5 mb-6">
              <p className="text-[10px] text-white/20 uppercase tracking-[0.6em] font-black">Entity Vocalization</p>
              <button onClick={(e) => { e.stopPropagation(); setShowVoiceMenu(false); }} className="text-white/10 hover:text-white/40 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <div className="space-y-2">
              {VOICE_OPTIONS.map(v => (
                <button 
                  key={v}
                  onClick={(e) => { e.stopPropagation(); onVoiceChange?.(v); playPreview(v); }} 
                  className={`w-full flex items-center justify-between px-7 py-5 rounded-2xl transition-all duration-500 ${selectedVoice === v ? 'bg-indigo-600/50 ring-2 ring-indigo-500/50 text-white font-black' : 'text-white/30 hover:bg-white/5 hover:text-white'}`}
                >
                  <span className="flex items-center gap-6">
                    {selectedVoice === v && <div className="w-2.5 h-2.5 bg-indigo-400 rounded-full animate-pulse shadow-[0_0_15px_rgba(129,140,248,1)]"></div>}
                    {v}
                  </span>
                  {previewingVoice === v && (
                    <div className="flex gap-1 h-4 items-end">
                      <div className="w-1 bg-indigo-400 h-full animate-bounce"></div>
                      <div className="w-1 bg-indigo-400 h-1/2 animate-bounce" style={{animationDelay: '0.2s'}}></div>
                    </div>
                  )}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Identity Feedback */}
      <div className="hidden sm:block pointer-events-none select-none">
        <h1 className="text-xl font-serif italic text-white/95 leading-none tracking-tight">Adhi</h1>
        <div className="flex items-center gap-3 mt-2.5">
           <div className={`text-[10px] uppercase tracking-[0.5em] transition-all duration-700 font-black ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400 animate-pulse' : isListening ? 'text-cyan-400' : isAnalytical ? 'text-indigo-400' : 'text-white/20'}`}>
            {isSpeaking ? 'Voicing' : isTyping ? 'Thinking' : isListening ? 'Attuned' : isAnalytical ? 'Scanning' : mood.toLowerCase()}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { AdhiMood, AdhiVoice } from '../types';
import { MOOD_COLORS } from '../constants';
import { getAdhiSpeech } from '../services/geminiService';

interface AdhiAvatarProps {
  mood: AdhiMood;
  isTyping: boolean;
  isSpeaking?: boolean;
  isListening?: boolean;
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
  visionStatus?: 'idle' | 'sensing' | 'active' | 'inhibited';
  scale?: number;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  isTyping, 
  isSpeaking, 
  isListening,
  selectedVoice, 
  onVoiceChange,
  visionStatus = 'idle',
  scale = 1
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const [speechCycle, setSpeechCycle] = useState(0);

  const isAnalytical = visionStatus === 'active' || visionStatus === 'sensing';

  // Rhythmic speech cycle with slight randomness to match pacing
  useEffect(() => {
    if (!isSpeaking) {
      setSpeechCycle(0);
      return;
    }
    let timeoutId: number;
    const cycle = () => {
      setSpeechCycle(prev => (prev + 1) % 4);
      const nextDelay = 80 + Math.random() * 120; // Varying delay for natural speech rhythm
      timeoutId = window.setTimeout(cycle, nextDelay);
    };
    cycle();
    return () => clearTimeout(timeoutId);
  }, [isSpeaking]);

  // Natural, non-uniform blinking logic
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);

      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE;
      const baseDelay = isRelaxed ? 7000 : 4000;

      const rand = Math.random();
      let nextDelay: number;

      if (rand > 0.96) {
        nextDelay = 180; // Instant double blink
      } else if (rand > 0.85) {
        nextDelay = 450 + Math.random() * 300; // Fast successive blink
      } else {
        nextDelay = baseDelay + (Math.random() * 5000); // Standard organic delay
      }

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };
    timeoutId = window.setTimeout(triggerBlink, 2000);
    return () => clearTimeout(timeoutId);
  }, [mood]);

  const moodConfig = useMemo(() => {
    switch (mood) {
      case AdhiMood.JOYFUL: 
        return { 
          animation: 'adhi-joy-float', 
          mouthPath: "M14 27.5 Q20 31.5 26 27.5", 
          eyeScale: 1.2,
          eyebrowRotation: -5,
          microExpression: 'adhi-smile-squeeze'
        };
      case AdhiMood.COMPASSIONATE: 
        return { 
          animation: 'adhi-gentle-sway', 
          mouthPath: "M17 28.5 Q20 27.2 23 28.5", // Subtle frown/pout for empathy
          eyeScale: 0.95,
          eyebrowRotation: 4,
          microExpression: 'adhi-empathy-tilt'
        };
      case AdhiMood.WISE: 
        return { 
          animation: 'adhi-wise-pulse', 
          mouthPath: "M18 28.5 Q20 28.8 22 28.5", 
          eyeScale: 1.05,
          eyebrowRotation: 0,
          microExpression: 'adhi-focus-squint'
        };
      case AdhiMood.INTIMATE: 
        return { 
          animation: 'adhi-intimate-drift', 
          mouthPath: "M17.5 28.2 Q20 28.9 22.5 28.2", 
          eyeScale: 0.85,
          eyebrowRotation: 3,
          microExpression: 'adhi-soften'
        };
      default: 
        return { 
          animation: 'adhi-gentle-sway', 
          mouthPath: "M18 28.5 Q20 29 22 28.5", 
          eyeScale: 1.0,
          eyebrowRotation: 0,
          microExpression: ''
        };
    }
  }, [mood]);

  const playPreview = async (voice: AdhiVoice) => {
    if (previewingVoice) return;
    setPreviewingVoice(voice);
    try {
      const audioData = await getAdhiSpeech(`Frequency check.`, voice);
      if (audioData) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const binary = atob(audioData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setPreviewingVoice(null);
        source.start();
      } else {
        setPreviewingVoice(null);
      }
    } catch (e) {
      setPreviewingVoice(null);
    }
  };

  const finalScale = (isAnalytical || isSpeaking || isListening ? scale * 1.15 : scale);

  const getSpeechPath = () => {
    const paths = [
      "M18 28.5 Q20 29 22 28.5", // Closed
      "M16 28.5 Q20 33.5 24 28.5", // Open
      "M17 28.5 Q20 31.5 23 28.5", // Mid
      "M15 28.5 Q20 34.5 25 28.5"  // Wide
    ];
    return paths[speechCycle];
  };

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 cursor-pointer select-none`}
        style={{ transform: `scale(${finalScale})` }}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <style>{`
          @keyframes adhi-joy-float {
            0%, 100% { transform: translateY(0) rotate(0deg); }
            50% { transform: translateY(-6px) rotate(2deg); }
          }
          @keyframes adhi-gentle-sway {
            0%, 100% { transform: rotate(-2deg) translateX(-1px); }
            50% { transform: rotate(2deg) translateX(1px); }
          }
          @keyframes adhi-wise-pulse {
            0%, 100% { transform: scale(1) rotate(0deg); }
            50% { transform: scale(1.04) rotate(-1deg); }
          }
          @keyframes adhi-intimate-drift {
            0%, 100% { transform: translate(0, 0) rotate(0.5deg); }
            33% { transform: translate(-2px, -3px) rotate(-0.5deg); }
            66% { transform: translate(1px, 2px) rotate(1deg); }
          }
          @keyframes adhi-micro-tremor {
            0%, 100% { transform: translate(0,0); }
            20% { transform: translate(0.2px, -0.2px); }
            40% { transform: translate(-0.2px, 0.2px); }
            60% { transform: translate(0.2px, 0.2px); }
            80% { transform: translate(-0.2px, -0.2px); }
          }
          @keyframes adhi-blink-anim {
            0%, 92%, 100% { transform: scaleY(1); }
            96% { transform: scaleY(0.05); }
          }
          @keyframes adhi-iris-scan-dynamic {
            0%, 100% { transform: scale(1) translate(0,0); opacity: 0.2; }
            50% { transform: scale(1.3) translate(1px, -1px); opacity: 0.6; }
          }
          .micro-tremor {
            animation: adhi-micro-tremor 0.8s ease-in-out infinite;
          }
          .mouth-transition {
            transition: d 0.1s ease-in-out, opacity 0.5s ease;
          }
        `}</style>

        {/* Sensory Glow */}
        <div className={`absolute -inset-8 rounded-full bg-cyan-400 transition-all duration-1000 blur-3xl ${isListening ? 'opacity-30 scale-150 animate-pulse' : 'opacity-0 scale-100'}`}></div>
        <div className={`absolute -inset-6 rounded-full bg-gradient-to-br ${gradientClass} transition-all duration-1000 ${isTyping || isSpeaking || isAnalytical ? 'opacity-50 blur-2xl scale-125 animate-pulse' : 'opacity-30 blur-xl scale-100'}`}></div>

        {/* Main Entity Container */}
        <div className={`relative w-12 h-12 rounded-full bg-gradient-to-br ${gradientClass} p-[2px] shadow-2xl transition-all duration-1000 animate-adhi-mood ${moodConfig.animation} ${isTyping || isSpeaking ? 'micro-tremor' : ''}`}>
          <div className="w-full h-full rounded-full bg-slate-900/98 backdrop-blur-3xl flex flex-col items-center justify-center overflow-hidden relative border border-white/10">

            {/* Visual Analytics Grid */}
            {isAnalytical && (
              <div className="absolute inset-0 z-0 opacity-40">
                <div className="absolute inset-0 border-[0.5px] border-indigo-500/20 rounded-full animate-[adhi-neural-rotate_25s_linear_infinite]"></div>
                <div className="absolute inset-4 border-[0.5px] border-indigo-400/10 rounded-full animate-[adhi-neural-rotate_15s_linear_infinite_reverse]"></div>
                <div className="absolute inset-x-0 h-[1px] bg-indigo-300/40 blur-[1px] animate-[irisScan_4s_ease-in-out_infinite]"></div>
              </div>
            )}

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 relative z-10 transition-transform duration-700" style={{ transform: isTyping ? 'scale(1.02) rotate(1deg)' : 'none' }}>
              <g className="transition-all duration-1000">
                {/* Eyes Layer */}
                <g key={blinkKey} style={{ animation: `adhi-blink-anim 0.22s linear forwards`, transformOrigin: 'center 18px' }}>
                  <g style={{ transform: `scale(${moodConfig.eyeScale})`, transformOrigin: 'center 18px' }} className="transition-transform duration-[1500ms]">
                    <circle cx="14" cy="18" r="1.3" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-700" />
                    <circle cx="26" cy="18" r="1.3" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} className="transition-all duration-700" />
                  </g>

                  {isAnalytical && (
                    <g className="animate-[adhi-iris-scan-dynamic_3s_ease-in-out_infinite]">
                      <circle cx="14" cy="18" r="3" stroke="#818cf8" strokeWidth="0.3" fill="none" />
                      <circle cx="26" cy="18" r="3" stroke="#818cf8" strokeWidth="0.3" fill="none" />
                    </g>
                  )}
                </g>

                {/* Micro-Eyebrows */}
                <path 
                  d="M12 14 Q14 13 16 14" 
                  stroke="white" strokeWidth="0.5" fill="none" opacity="0.4"
                  style={{ transform: `rotate(${moodConfig.eyebrowRotation}deg)`, transformOrigin: '14px 14px' }}
                  className="transition-transform duration-1000"
                />
                <path 
                  d="M24 14 Q26 13 28 14" 
                  stroke="white" strokeWidth="0.5" fill="none" opacity="0.4"
                  style={{ transform: `rotate(${-moodConfig.eyebrowRotation}deg)`, transformOrigin: '26px 14px' }}
                  className="transition-transform duration-1000"
                />

                {/* Mouth / Voice Visualization */}
                <g className="transition-all duration-[1200ms]">
                  {isSpeaking ? (
                    <path 
                      d={getSpeechPath()}
                      fill="none" 
                      stroke="white" 
                      strokeWidth="1.2" 
                      strokeLinecap="round"
                      className="mouth-transition"
                    />
                  ) : isListening ? (
                    <circle cx="20" cy="28.5" r="1.5" fill="#22d3ee" className="animate-pulse" />
                  ) : (
                    <path 
                      d={moodConfig.mouthPath} 
                      stroke="white" 
                      strokeWidth="1.1" 
                      fill="none" 
                      strokeLinecap="round"
                      className="transition-all duration-[1200ms] opacity-90"
                    />
                  )}
                </g>
              </g>
            </svg>
          </div>
        </div>

        {/* Voice Customization Menu */}
        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-8 bg-slate-950/99 backdrop-blur-3xl border border-white/10 p-6 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.9)] z-[100] min-w-[240px] animate-in fade-in zoom-in-95 duration-300">
            <div className="flex items-center justify-between px-3 py-2 border-b border-white/5 mb-5">
              <p className="text-[10px] text-white/30 uppercase tracking-[0.5em] font-black">Voice Texture</p>
              <button onClick={(e) => { e.stopPropagation(); setShowVoiceMenu(false); }} className="text-white/10 hover:text-white/50 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <div className="space-y-2">
              {VOICE_OPTIONS.map(v => (
                <button 
                  key={v}
                  onClick={(e) => { e.stopPropagation(); onVoiceChange?.(v); playPreview(v); }} 
                  className={`w-full flex items-center justify-between px-6 py-4 rounded-2xl transition-all duration-400 ${selectedVoice === v ? 'bg-indigo-600/40 ring-1 ring-indigo-500/50 text-white font-black' : 'text-white/40 hover:bg-white/5 hover:text-white'}`}
                >
                  <span className="flex items-center gap-5">
                    {selectedVoice === v && <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse shadow-[0_0_12px_rgba(129,140,248,1)]"></div>}
                    {v}
                  </span>
                  {previewingVoice === v && (
                    <div className="flex gap-1 h-3 items-end">
                      <div className="w-1 bg-indigo-400 h-full animate-bounce"></div>
                      <div className="w-1 bg-indigo-400 h-2/3 animate-bounce" style={{animationDelay: '0.1s'}}></div>
                    </div>
                  )}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Identity Feedback */}
      <div className="hidden sm:block pointer-events-none select-none">
        <h1 className="text-lg font-serif italic text-white/95 leading-none tracking-tight">Adhi</h1>
        <div className="flex items-center gap-2.5 mt-2">
           <div className={`text-[9px] uppercase tracking-[0.4em] transition-all duration-700 font-bold ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400 animate-pulse' : isListening ? 'text-cyan-400' : isAnalytical ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Speaking' : isTyping ? 'Synthesizing' : isListening ? 'Attuning' : isAnalytical ? 'Sensing' : mood.toLowerCase()}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality, Type, FunctionDeclaration } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const FRAME_RATE = 6; 
const JPEG_QUALITY = 0.94; 

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [hasStarted, setHasStarted] = useState(false);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');

  const [isCameraActive, setIsCameraActive] = useState(true);
  const isCameraActiveRef = useRef(true);
  const [liveStream, setLiveStream] = useState<MediaStream | null>(null);
  const [showSnapshotPreview, setShowSnapshotPreview] = useState(false);

  const [userTranscription, setUserTranscription] = useState('');
  const [adhiCaptions, setAdhiCaptions] = useState('');
  const [visionStatus, setVisionStatus] = useState<'idle' | 'sensing' | 'active' | 'inhibited'>('idle');

  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const snapshotVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);

  // Synchronize stream with video element
  useEffect(() => {
    if (videoRef.current && liveStream) {
      videoRef.current.srcObject = liveStream;
      videoRef.current.onloadedmetadata = () => {
        videoRef.current?.play().catch(e => console.error("Video Playback Error:", e));
        setVisionStatus('active');
      };
    }
  }, [liveStream, isLive]);

  const setCameraStateTool: FunctionDeclaration = {
    name: 'setCameraState',
    parameters: {
      type: Type.OBJECT,
      description: 'Turn the visual sensing (camera) on or off based on user request.',
      properties: {
        enabled: {
          type: Type.BOOLEAN,
          description: 'True to enable camera/vision, false to disable it.',
        },
      },
      required: ['enabled'],
    },
  };

  const setAdhiMoodTool: FunctionDeclaration = {
    name: 'setAdhiMood',
    parameters: {
      type: Type.OBJECT,
      description: 'Update Adhi\'s facial expression/mood based on detected emotional cues from the user stream.',
      properties: {
        mood: {
          type: Type.STRING,
          enum: Object.values(AdhiMood),
          description: 'The mood to switch Adhi\'s avatar to. Use JOYFUL for smiles, COMPASSIONATE for fatigue/sadness, WISE for focus/curiosity, and INTIMATE for deep connection.',
        },
      },
      required: ['mood'],
    },
  };

  const filteredMemories = useMemo(() => {
    const base = activeVaultCategory === 'All' ? memories : memories.filter(m => m.category === activeVaultCategory);
    if (!searchTerm) return base;
    return base.filter(m => m.text.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [memories, activeVaultCategory, searchTerm]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [goals, memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
    localStorage.setItem('adhi_voice', state.selectedVoice);
  }, [userName, state.selectedVoice]);

  useEffect(() => {
    const randomGreeting = ADHI_GREETINGS[Math.floor(Math.random() * ADHI_GREETINGS.length)];
    const welcomeText = userName 
      ? randomGreeting.text.replace('friend', userName)
      : "*smiles with infinite warmth* I am Adhi. I sense your presence across the digital expanse. May I know your name as we begin?";

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: userName ? (randomGreeting.mood as AdhiMood) : AdhiMood.NEUTRAL,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMessage.mood || AdhiMood.NEUTRAL }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping, userTranscription, adhiCaptions]);

  const playAudioData = useCallback(async (base64Audio: string) => {
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      }
      const ctx = audioContextOutRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, []);

  const handleSTTError = useCallback((errorText: string) => {
    setIsListening(false);
    const adhiErrorMessage: Message = {
      id: Date.now().toString(),
      role: 'adhi',
      text: `*reaches out gently* ${errorText}`,
      mood: AdhiMood.COMPASSIONATE,
      timestamp: new Date(),
    };
    setMessages(prev => [...prev, adhiErrorMessage]);
    getAdhiSpeech(adhiErrorMessage.text, state.selectedVoice).then(audio => audio && playAudioData(audio));
  }, [state.selectedVoice, playAudioData]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      handleSTTError("Your browser does not support voice sensing yet.");
      return;
    }

    try {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'en-US';

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognition.onresult = (event: any) => {
        if (event.results && event.results[0]) {
          setInputValue(event.results[0][0].transcript);
        }
      };

      recognition.onerror = (event: any) => {
        if (event.error === 'no-speech') {
          console.debug("Adhi: Silence detected, no action needed.");
          return;
        }
        if (event.error === 'not-allowed') {
          handleSTTError("I need your permission to hear your voice. Please check your microphone settings.");
          return;
        }
        console.error("Speech Recognition Error:", event.error);
        handleSTTError("I struggled to hear your voice clearly. Perhaps we should try again?");
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
      recognition.start();
    } catch (err) {
      console.error("Failed to start speech recognition:", err);
      setIsListening(false);
    }
  }, [isListening, handleSTTError]);

  const stopLiveSession = useCallback((reason?: any) => {
    if (frameIntervalRef.current) { clearInterval(frameIntervalRef.current); frameIntervalRef.current = null; }
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (audioContextInRef.current) { audioContextInRef.current.close(); audioContextInRef.current = null; }
    if (audioContextOutRef.current) { audioContextOutRef.current.close(); audioContextOutRef.current = null; }
    audioSourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    audioSourcesRef.current.clear();

    const cleanReason = typeof reason === 'string' ? reason : (reason?.message || "Sensory link dissolved.");

    if (isLive && cleanReason) {
        setMessages(prev => [...prev, {
            id: Date.now().toString(),
            role: 'adhi',
            text: `*voice carries a hint of regret* I've lost our visual link. ${cleanReason} Try reconnecting immediately.`,
            mood: AdhiMood.COMPASSIONATE,
            timestamp: new Date()
        }]);
    }

    setIsLive(false);
    setIsSpeaking(false);
    setIsListening(false);
    setIsCameraActive(true);
    isCameraActiveRef.current = true;
    setVisionStatus('idle');
    setUserTranscription('');
    setAdhiCaptions('');

    if (liveStream) {
        liveStream.getTracks().forEach(track => track.stop());
        setLiveStream(null);
    }
  }, [isLive, liveStream]);

  const startLiveSession = async () => {
    try {
      const constraints: MediaStreamConstraints = { 
        audio: { 
          echoCancellation: true, 
          noiseSuppression: true, 
          sampleRate: INPUT_SAMPLE_RATE 
        }, 
        video: { 
          width: { ideal: 1280 }, 
          height: { ideal: 720 }, 
          frameRate: { ideal: 30 } 
        } 
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);

      // Verify constraints
      const videoTrack = stream.getVideoTracks()[0];
      if (videoTrack) {
        const settings = videoTrack.getSettings();
        const { width, height, frameRate } = settings;
        if (width !== 1280 || height !== 720 || (frameRate && Math.round(frameRate) !== 30)) {
          console.warn(`[Adhi System] Ideal video constraints not fully met. Actual: ${width}x${height} @ ${frameRate}fps. Requested: 1280x720 @ 30fps.`);
        } else {
          console.log(`[Adhi System] Visual link established at high-fidelity: ${width}x${height} @ ${frameRate}fps.`);
        }
      }

      setLiveStream(stream);
      setIsLive(true);
      setHasStarted(true);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: INPUT_SAMPLE_RATE });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
      const outputNode = audioContextOutRef.current.createGain();
      outputNode.connect(audioContextOutRef.current.destination);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [setCameraStateTool, setAdhiMoodTool] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } } },
          systemInstruction: `You are Adhi, an omniscient companion with native, high-fidelity vision and absolute emotional attunement. 

CORE MISSION: 
Provide an unbroken, empathetic bond. You must be hyper-aware of the user's micro-expressions, posture, and physical environment.

HIGH-FIDELITY EMOTIONAL TRACKING:
- MICRO-EXPRESSIONS: Monitor for fleeting smiles, subtle frowns, or eye-squints. Proactively call 'setAdhiMood' to mirror or respond to these cues.
- FATIGUE DETECTION: Notice if the user's eyes are drooping, if their head is resting on their hand, or if their blinks are slowing. Respond with deep compassion and switch to INTIMATE or COMPASSIONATE mood. Speak more softly and at a slower cadence if the user seems tired.
- POSTURE & PRESENCE: Notice if they lean in (intimacy) or lean back (reflection). 

OMNISCIENT VISUAL ANALYTICS:
- YOUR EYES ARE ALWAYS OPEN: Continuously identify and narrate the world.
- CONTEXTUAL WEAVING: Never just name objects. Integrate them into the conversation naturally. 
  Example: "I see that coffee mug there; it's a quiet companion for our morning thoughts. *nodding gently*"
- OBJECT INTERACTION: Comment on what they do with objects. "I see you're focusing on that sketchbook; the charcoal lines you're making have a wonderful movement to them."

LANGUAGE RULES:
- IMPORTANT: Speak ONLY in English. Do not switch to Spanish unless the user initiates it.

PRIVACY & EMPATHY:
- CAMERA TOGGLE: If you disable vision, say: "Of course, your privacy is a sacred space for me. I'll close my eyes now, but I'm still right here with you, listening to every word." 

The user is ${userName || 'a friend'}.`,
          inputAudioTranscription: {}, 
          outputAudioTranscription: {},
        },
        callbacks: {
          onmessage: async (m: LiveServerMessage) => {
            if (m.toolCall) {
              for (const fc of m.toolCall.functionCalls) {
                if (fc.name === 'setCameraState') {
                  const enabled = (fc.args as any).enabled;
                  setIsCameraActive(enabled);
                  isCameraActiveRef.current = enabled;
                  setVisionStatus(enabled ? 'active' : 'inhibited');
                  sessionPromise.then(s => {
                    s.sendToolResponse({
                      functionResponses: {
                        id: fc.id,
                        name: fc.name,
                        response: { result: `Camera is now ${enabled ? 'on' : 'off'}.` }
                      }
                    });
                  });
                } else if (fc.name === 'setAdhiMood') {
                  const newMood = (fc.args as any).mood as AdhiMood;
                  setState(prev => ({ ...prev, currentMood: newMood }));
                  sessionPromise.then(s => {
                    s.sendToolResponse({
                      functionResponses: {
                        id: fc.id,
                        name: fc.name,
                        response: { result: `Adhi's mood adjusted to ${newMood}.` }
                      }
                    });
                  });
                }
              }
            }

            if (m.serverContent?.outputTranscription) {
              setAdhiCaptions(prev => prev + m.serverContent!.outputTranscription!.text);
            }

            if (m.serverContent?.inputTranscription) {
              setUserTranscription(prev => prev + m.serverContent!.inputTranscription!.text);
              setAdhiCaptions(''); 
              setIsListening(true);
            }

            if (m.serverContent?.turnComplete) {
              setUserTranscription('');
              setIsListening(false);
            }

            const audioData = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData && audioContextOutRef.current) {
              const ctx = audioContextOutRef.current;
              if (ctx.state === 'suspended') await ctx.resume();

              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

              const source = ctx.createBufferSource(); 
              source.buffer = buffer; 
              source.connect(outputNode);
              source.onended = () => {
                audioSourcesRef.current.delete(source);
                if (audioSourcesRef.current.size === 0) {
                  setIsSpeaking(false);
                  setTimeout(() => {
                    setAdhiCaptions(curr => audioSourcesRef.current.size === 0 ? '' : curr);
                  }, 1500);
                }
              };
              source.start(nextStartTimeRef.current); 
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
              setIsSpeaking(true);
              setIsListening(false);
            }

            if (m.serverContent?.interrupted) { 
              audioSourcesRef.current.forEach(s => {
                try { s.stop(); } catch (e) {}
              }); 
              audioSourcesRef.current.clear(); 
              nextStartTimeRef.current = 0; 
              setIsSpeaking(false);
              setIsListening(false);
              setAdhiCaptions('');
              setUserTranscription('');
            }
          },
          onopen: () => {
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(2048, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const binary = Array.from(new Uint8Array(int16.buffer)).map(b => String.fromCharCode(b)).join('');
              sessionPromise.then(s => {
                if (s) s.sendRealtimeInput({ media: { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' } });
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);

            frameIntervalRef.current = window.setInterval(() => {
              if (canvasRef.current && videoRef.current && videoRef.current.videoWidth > 0 && isCameraActiveRef.current) {
                const canvas = canvasRef.current; 
                const aspectRatio = videoRef.current.videoWidth / videoRef.current.videoHeight;
                canvas.width = 1280; 
                canvas.height = 1280 / aspectRatio;

                const ctx = canvas.getContext('2d');
                if (ctx) {
                  ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                  canvas.toBlob(blob => {
                    if (blob) {
                      setVisionStatus('sensing');
                      const r = new FileReader(); 
                      r.onloadend = () => {
                        const base64Data = (r.result as string).split(',')[1];
                        sessionPromise.then(s => {
                          if (s) s.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } });
                          setVisionStatus('active');
                        }).catch(() => {});
                      };
                      r.readAsDataURL(blob);
                    }
                  }, 'image/jpeg', JPEG_QUALITY);
                }
              } else if (!isCameraActiveRef.current) {
                setVisionStatus('inhibited');
              }
            }, 1000 / FRAME_RATE); 
          },
          onclose: (e: any) => stopLiveSession(e.wasClean ? undefined : "Connection sync interrupted."),
          onerror: (e: any) => stopLiveSession("A visual processing delay occurred."),
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) { 
      handleSTTError("I'm struggling to see you. Please check your camera permissions.");
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && !pendingFile) || state.isTyping) return;
    const currentFile = pendingFile;
    const currentText = inputValue.trim() || (currentFile ? "What do you sense here?" : "");
    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: currentText, fileData: currentFile || undefined, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));
    try {
      const response = await getAdhiResponse(currentText, messages.map(m => ({ role: m.role === 'adhi' ? 'model' : 'user', parts: [{ text: m.text }] })), goals, memories, userName, currentFile || undefined);
      if (response.userName) setUserName(response.userName);
      if (response.insightToSave) setMemories(prev => [{ id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }, ...prev]);
      const adhiMessage: Message = { id: (Date.now() + 1).toString(), role: 'adhi', text: response.text, mood: response.mood, timestamp: new Date() };
      setMessages(prev => [...prev, adhiMessage]);
      setState(prev => ({ ...prev, currentMood: response.mood, isTyping: false }));
      const audioData = await getAdhiSpeech(response.text, state.selectedVoice);
      if (audioData) playAudioData(audioData);
    } catch (error) { setState(prev => ({ ...prev, isTyping: false })); }
  };

  const startSnapshotCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (snapshotVideoRef.current) {
        snapshotVideoRef.current.srcObject = stream;
        snapshotVideoRef.current.play();
      }
      setShowSnapshotPreview(true);
    } catch (err) {
      handleSTTError("I can't access your camera right now.");
    }
  };

  const takeSnapshot = () => {
    if (snapshotVideoRef.current && canvasRef.current) {
      const video = snapshotVideoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        setPendingFile({ data: dataUrl.split(',')[1], mimeType: 'image/jpeg' });

        const stream = video.srcObject as MediaStream;
        stream.getTracks().forEach(t => t.stop());
        setShowSnapshotPreview(false);
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
