        )}
      </div>

      {/* Identity Feedback */}
      <div className="hidden sm:block pointer-events-none select-none">
        <h1 className="text-lg font-serif italic text-white/95 leading-none tracking-tight">Adhi</h1>
        <div className="flex items-center gap-2.5 mt-2">
           <div className={`text-[9px] uppercase tracking-[0.4em] transition-all duration-700 font-bold ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400 animate-pulse' : isListening ? 'text-cyan-400' : isAnalytical ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Speaking' : isTyping ? 'Synthesizing' : isListening ? 'Attuning' : isAnalytical ? 'Sensing' : mood.toLowerCase()}
          </div>
