                        <button onClick={toggleListening} className={`p-4 rounded-2xl transition-all duration-500 shadow-2xl ${isListening ? 'bg-red-500/20 text-red-400 ring-2 ring-red-500/50 animate-pulse' : 'bg-white/5 text-white/40 hover:text-white/70 ring-1 ring-white/5'}`} title="Voice Input"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                      </div>
                      <div className="flex-grow relative">
                        <input type="text" value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Speak to me, or share a thought..." className="w-full bg-white/5 border border-white/10 rounded-[2rem] py-4 px-8 focus:outline-none focus:border-indigo-500/50 focus:bg-white/10 transition-all duration-700 text-slate-100 placeholder:text-white/20 text-sm shadow-inner" />
                        <button onClick={handleSend} disabled={state.isTyping} className="absolute right-2 top-2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-[1.2rem] transition-all duration-500 shadow-xl shadow-indigo-500/30 disabled:opacity-30 disabled:scale-95"><svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
                      </div>
                    </div>
