      </header>

      <main className="flex-1 overflow-hidden relative flex flex-col md:flex-row">
        {/* Enhanced Immersive Live Panel */}
        {isLive && (
          <div className="w-full md:w-[45%] h-[60vh] md:h-full relative flex flex-col md:flex-row border-b md:border-b-0 md:border-r border-white/10 bg-slate-950 animate-in slide-in-from-left duration-700">
             {/* User Presence Card */}
