                        <span className="text-[10px] uppercase tracking-[0.3em] font-black text-white/90">Sensing Mode</span>
                    </div>
                    {/* Focus UI */}
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 border border-indigo-500/20 rounded-full animate-[ping_3s_linear_infinite] opacity-40 pointer-events-none" />
                </div>
             </div>

             {/* Adhi Presence Card - Immersive Avatar */}
             <div className="flex-1 relative p-4 md:p-6 md:pl-0">
                <div className={`w-full h-full rounded-[2.5rem] overflow-hidden border border-white/10 relative flex flex-col items-center justify-center shadow-2xl bg-slate-900/50`}>
                    <div className={`absolute inset-0 bg-gradient-to-br ${MOOD_COLORS[state.currentMood]} opacity-30 transition-all duration-1000`} />
                    <div className="absolute inset-0 bg-slate-950/40 backdrop-blur-2xl" />

                    <AdhiAvatar 
                        mood={state.currentMood} 
