                    <div className="absolute bottom-6 left-8 flex items-center gap-3">
                        <div className={`w-2.5 h-2.5 rounded-full ${isSpeaking ? 'bg-indigo-400 animate-pulse shadow-[0_0_10px_#818cf8]' : 'bg-white/20'}`}></div>
                        <span className="text-[10px] uppercase tracking-[0.3em] font-black text-white/90">Adhi Active</span>
                    </div>

                    {/* Speech Visualizer */}
                    <div className="absolute bottom-0 inset-x-0 h-1 flex items-end px-12 pb-4 gap-[2px] opacity-40">
                      {[...Array(12)].map((_, i) => (
                        <div 
