             </div>

             {liveError && (
                 <div className="absolute bottom-20 inset-x-4 z-50">
                    <div className="bg-rose-500/20 backdrop-blur-xl border border-rose-500/40 p-4 rounded-2xl text-[11px] text-rose-300 font-medium animate-in slide-in-from-bottom-2">
