import React, { useMemo, useState, useEffect, useRef } from 'react';
import { AdhiMood, AdhiVoice, MicroExpression } from '../types';
import { MOOD_COLORS } from '../constants';
import { getAdhiSpeech } from '../services/geminiService';

interface AdhiAvatarProps {
  mood: AdhiMood;
  microExpression?: MicroExpression;
  isTyping: boolean;
  isSpeaking?: boolean;
  isListening?: boolean;
  volume?: number; // Real-time volume for lip-sync
  selectedVoice?: AdhiVoice;
  onVoiceChange?: (voice: AdhiVoice) => void;
  visionStatus?: 'idle' | 'sensing' | 'active' | 'inhibited';
  scale?: number;
}

const VOICE_OPTIONS: AdhiVoice[] = ['Zephyr', 'Kore', 'Puck', 'Charon', 'Fenrir'];

const AdhiAvatar: React.FC<AdhiAvatarProps> = ({ 
  mood, 
  microExpression = 'none',
  isTyping, 
  isSpeaking, 
  isListening,
  volume = 0,
  selectedVoice, 
  onVoiceChange,
  visionStatus = 'idle',
  scale = 1
}) => {
  const gradientClass = MOOD_COLORS[mood] || MOOD_COLORS.NEUTRAL;
  const [blinkKey, setBlinkKey] = useState(0);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const [eyeOffset, setEyeOffset] = useState({ x: 0, y: 0 });

  const isAnalytical = visionStatus === 'active' || visionStatus === 'sensing';

  // Natural gaze shifts
  useEffect(() => {
    let timeoutId: number;
    const shiftGaze = () => {
      const magnitude = isTyping ? 1.5 : (isSpeaking || isListening) ? 0.3 : 0.8;

      setEyeOffset({
        x: (Math.random() - 0.5) * magnitude,
        y: (Math.random() - 0.5) * magnitude
      });

      const nextDelay = isTyping ? 800 + Math.random() * 1200 : 2500 + Math.random() * 5000;
      timeoutId = window.setTimeout(shiftGaze, nextDelay);
    };

    timeoutId = window.setTimeout(shiftGaze, 1000);
    return () => clearTimeout(timeoutId);
  }, [isTyping, isSpeaking, isListening]);

  // Non-uniform blinking
  useEffect(() => {
    let timeoutId: number;
    const triggerBlink = () => {
      setBlinkKey(prev => prev + 1);
      const isRelaxed = mood === AdhiMood.WISE || mood === AdhiMood.INTIMATE || microExpression === 'fatigue';
      const baseDelay = isRelaxed ? 8000 : 5000;

      const rand = Math.random();
      let nextDelay: number;
      if (rand > 0.95) nextDelay = 150; 
      else if (rand > 0.8) nextDelay = 400 + Math.random() * 300;
      else nextDelay = baseDelay + (Math.random() * 4000);

      timeoutId = window.setTimeout(triggerBlink, nextDelay);
    };
    timeoutId = window.setTimeout(triggerBlink, 3000);
    return () => clearTimeout(timeoutId);
  }, [mood, microExpression]);

  const moodConfig = useMemo(() => {
    let config = {
      animation: 'adhi-gentle-sway', 
      mouthPath: "M18 28.5 Q20 29 22 28.5", 
      eyeScale: 1.0,
      eyebrowRotation: 0,
      lidScale: 1.0,
      eyeGlow: 'none'
    };

    switch (mood) {
      case AdhiMood.JOYFUL: 
        config = { 
          animation: 'adhi-joy-float', 
          mouthPath: "M14 27.5 Q20 31.5 26 27.5", 
          eyeScale: 1.3,
          eyebrowRotation: -7,
          lidScale: 1.0,
          eyeGlow: '0 0 15px rgba(255, 255, 255, 0.5)'
        };
        break;
      case AdhiMood.COMPASSIONATE: 
        config = { 
          animation: 'adhi-gentle-sway', 
          mouthPath: "M17 28.5 Q20 27.5 23 28.5", 
          eyeScale: 0.9,
          eyebrowRotation: 4,
          lidScale: 0.65, 
          eyeGlow: 'none'
        };
        break;
      case AdhiMood.WISE: 
        config = { 
          animation: 'adhi-wise-pulse', 
          mouthPath: "M18 28.5 Q20 28.8 22 28.5", 
          eyeScale: 1.15,
          eyebrowRotation: 0,
          lidScale: 0.9, 
          eyeGlow: '0 0 10px rgba(129, 140, 248, 0.4)'
        };
        break;
      case AdhiMood.INTIMATE: 
        config = { 
          animation: 'adhi-intimate-drift', 
          mouthPath: "M17.5 28.2 Q20 28.9 22.5 28.2", 
          eyeScale: 0.85,
          eyebrowRotation: 5,
          lidScale: 0.6, 
          eyeGlow: 'none'
        };
        break;
    }

    // Overlay Micro-Expressions
    switch (microExpression) {
      case 'smile':
        config.mouthPath = "M16 27.5 Q20 30.5 24 27.5";
        config.eyebrowRotation = config.eyebrowRotation - 3;
        break;
      case 'concern':
        config.mouthPath = "M18 29 Q20 27.5 22 29";
        config.eyebrowRotation = config.eyebrowRotation + 6;
        break;
      case 'surprise':
        config.eyeScale = config.eyeScale * 1.2;
        config.lidScale = 1.0;
        config.eyebrowRotation = config.eyebrowRotation - 10;
        config.mouthPath = "M19 28.5 Q20 31 21 28.5";
        break;
      case 'fatigue':
        config.lidScale = config.lidScale * 0.5;
        config.animation = 'adhi-intimate-drift';
        break;
      case 'focus':
        config.eyeScale = config.eyeScale * 0.9;
        config.eyebrowRotation = config.eyebrowRotation + 2;
        break;
    }

    return config;
  }, [mood, microExpression]);

  const playPreview = async (voice: AdhiVoice) => {
    if (previewingVoice) return;
    setPreviewingVoice(voice);
    try {
      const audioData = await getAdhiSpeech(`I am Adhi.`, voice);
      if (audioData) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const binary = atob(audioData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setPreviewingVoice(null);
        source.start();
      } else {
        setPreviewingVoice(null);
      }
    } catch (e) {
      setPreviewingVoice(null);
    }
  };

  const finalScale = (isAnalytical || isSpeaking || isListening ? scale * 1.12 : scale);

  const getDynamicMouthPath = () => {
    const activeVolume = isSpeaking ? volume : 0;

    if (activeVolume < 0.02) {
      if (isListening && !isSpeaking) return null; 
      return moodConfig.mouthPath;
    }

    const t = Math.pow(activeVolume, 0.7);
    const drop = 1 + (t * 12); 
    const width = 18 - (t * 5); 
    const left = 20 - (width / 2);
    const right = 20 + (width / 2);

    return `M${left} 28.5 Q20 ${28.5 + drop} ${right} 28.5`;
  };

  return (
    <div className="flex items-center gap-4 transition-all duration-1000 relative">
      <div 
        className={`relative group transition-all duration-1000 cursor-pointer select-none`}
        style={{ transform: `scale(${finalScale})` }}
        onClick={() => setShowVoiceMenu(!showVoiceMenu)}
      >
        <style>{`
          @keyframes adhi-joy-float {
            0%, 100% { transform: translateY(0) rotate(0deg); }
            50% { transform: translateY(-8px) rotate(4deg); }
          }
          @keyframes adhi-gentle-sway {
            0%, 100% { transform: rotate(-2deg) translateX(-0.5px); }
            50% { transform: rotate(2deg) translateX(0.5px); }
          }
          @keyframes adhi-wise-pulse {
            0%, 100% { transform: scale(1) rotate(0deg); }
            50% { transform: scale(1.04) rotate(-1deg); }
          }
          @keyframes adhi-intimate-drift {
            0%, 100% { transform: translate(0, 0) rotate(0.5deg); }
            33% { transform: translate(-2px, -3px) rotate(-0.5deg); }
            66% { transform: translate(1px, 2px) rotate(1deg); }
          }
          @keyframes adhi-blink-anim {
            0%, 94%, 100% { transform: scaleY(1); }
            97% { transform: scaleY(0.05); }
          }
          @keyframes iris-analytical-scan {
            0%, 100% { transform: scale(1); opacity: 0.6; }
            50% { transform: scale(1.4); opacity: 1; filter: blur(2px); }
          }
          .mouth-transition {
            transition: d 0.05s linear;
          }
          .eye-gaze-transition {
            transition: cx 0.4s ease-out, cy 0.4s ease-out;
          }
        `}</style>

        {/* Sensory Link Glows */}
        <div className={`absolute -inset-10 rounded-full bg-cyan-400 transition-all duration-1000 blur-3xl ${isListening ? 'opacity-40 scale-160 animate-pulse' : 'opacity-0 scale-100'}`}></div>
        <div className={`absolute -inset-8 rounded-full bg-gradient-to-br ${gradientClass} transition-all duration-1000 ${isTyping || isSpeaking || isAnalytical ? 'opacity-60 blur-2xl scale-130 animate-pulse' : 'opacity-30 blur-xl scale-100'}`}></div>

        {/* Entity Orb */}
        <div className={`relative w-14 h-14 rounded-full bg-gradient-to-br ${gradientClass} p-[2.5px] shadow-3xl transition-all duration-1000 animate-adhi-mood ${moodConfig.animation}`}>
          <div className="w-full h-full rounded-full bg-slate-900/98 backdrop-blur-3xl flex flex-col items-center justify-center overflow-hidden relative border border-white/10">

            {isAnalytical && (
              <div className="absolute inset-0 z-0 opacity-40">
                <div className="absolute inset-0 border-[0.5px] border-indigo-400/30 rounded-full animate-[spin_10s_linear_infinite]"></div>
                <div className="absolute inset-x-0 h-[1px] bg-cyan-200/40 blur-[1px] animate-[scan_3s_ease-in-out_infinite]"></div>
                <div className="absolute inset-y-0 w-[1px] bg-indigo-200/40 blur-[1px] left-1/2 animate-[scan_5s_ease-in-out_infinite]"></div>
              </div>
            )}

            <svg viewBox="0 0 40 40" className="w-full h-full p-2 relative z-10">
              <g className="transition-all duration-1000">
                <g key={blinkKey} style={{ animation: `adhi-blink-anim 0.2s linear forwards`, transformOrigin: 'center 18px' }}>
                  <g style={{ transform: `scale(${moodConfig.eyeScale})`, transformOrigin: 'center 18px' }}>
                    <circle cx={14 + eyeOffset.x} cy={18 + eyeOffset.y} r="1.4" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} style={{ filter: moodConfig.eyeGlow, animation: isAnalytical ? 'iris-analytical-scan 2s ease-in-out infinite' : 'none' }} className="eye-gaze-transition" />
                    <circle cx={26 + eyeOffset.x} cy={18 + eyeOffset.y} r="1.4" fill={isListening ? "#22d3ee" : isAnalytical ? "#818cf8" : "white"} style={{ filter: moodConfig.eyeGlow, animation: isAnalytical ? 'iris-analytical-scan 2s ease-in-out infinite' : 'none' }} className="eye-gaze-transition" />
                  </g>
                  <g style={{ transform: `scaleY(${moodConfig.lidScale})`, transformOrigin: 'center 16px' }} className="transition-transform duration-[1000ms]">
                    <rect x="10" y="14" width="8" height="2" fill="#0f172a" opacity="0.85" />
                    <rect x="22" y="14" width="8" height="2" fill="#0f172a" opacity="0.85" />
                  </g>
                </g>
                <path d="M12 14.5 Q14 13.5 16 14.5" stroke="white" strokeWidth="0.6" fill="none" opacity="0.4" style={{ transform: `rotate(${moodConfig.eyebrowRotation}deg)`, transformOrigin: '14px 14.5px' }} />
                <path d="M24 14.5 Q26 13.5 28 14.5" stroke="white" strokeWidth="0.6" fill="none" opacity="0.4" style={{ transform: `rotate(${-moodConfig.eyebrowRotation}deg)`, transformOrigin: '26px 14.5px' }} />

                <g>
                  {isListening && !isSpeaking ? (
                    <circle cx="20" cy="29" r="1.8" fill="#22d3ee" className="animate-pulse shadow-[0_0_10px_#22d3ee]" />
                  ) : (
                    <path d={getDynamicMouthPath() || moodConfig.mouthPath} fill="none" stroke="white" strokeWidth="1.4" strokeLinecap="round" className="mouth-transition" />
                  )}
                </g>
              </g>
            </svg>
          </div>
        </div>

        {showVoiceMenu && (
          <div className="absolute top-full left-0 mt-8 bg-slate-950/98 backdrop-blur-3xl border border-white/10 p-5 rounded-[2.5rem] shadow-[0_50px_100px_-30px_rgba(0,0,0,1)] z-[100] min-w-[280px] animate-in fade-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between px-4 py-2 border-b border-white/5 mb-4">
              <p className="text-[10px] text-white/30 uppercase tracking-[0.4em] font-black">Voice Texture</p>
              <button onClick={(e) => { e.stopPropagation(); setShowVoiceMenu(false); }} className="text-white/10 hover:text-white/50 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <div className="space-y-1.5">
              {VOICE_OPTIONS.map(v => (
                <div key={v} className="flex items-center gap-1 group/item">
                  <button onClick={(e) => { e.stopPropagation(); onVoiceChange?.(v); }} className={`flex-1 flex items-center justify-between px-5 py-3.5 rounded-l-2xl transition-all duration-400 group/btn ${selectedVoice === v ? 'bg-indigo-600/40 ring-1 ring-indigo-500/50 text-white shadow-xl shadow-indigo-500/10' : 'text-white/40 hover:bg-white/5 hover:text-white'}`}>
                    <div className="flex items-center gap-4">
                      <div className={`w-1.5 h-1.5 rounded-full transition-all duration-500 ${selectedVoice === v ? 'bg-indigo-400 scale-125 shadow-[0_0_8px_#818cf8]' : 'bg-white/10 scale-100 group-hover/btn:bg-white/30'}`}></div>
                      <span className={`text-sm tracking-wide transition-all ${selectedVoice === v ? 'font-black' : 'font-light'}`}>{v}</span>
                    </div>
                  </button>
                  <button onClick={(e) => { e.stopPropagation(); playPreview(v); }} className={`px-4 py-3.5 rounded-r-2xl border-l border-white/5 transition-all ${previewingVoice === v ? 'bg-indigo-500/20 text-indigo-400' : 'bg-white/5 hover:bg-indigo-600/20 text-white/20 hover:text-indigo-400'}`}>
                    {previewingVoice === v ? (
                      <div className="flex gap-0.5 h-3 items-center">
                        {[1,2,3].map(i => <div key={i} className="w-0.5 bg-current h-full animate-bounce" style={{animationDelay: `${i*0.1}s`}}></div>)}
                      </div>
                    ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" /></svg>
                    )}
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="hidden sm:block pointer-events-none select-none">
        <h1 className="text-xl font-serif italic text-white/95 leading-none tracking-tight">{microExpression !== 'none' ? `Adhi (${microExpression})` : 'Adhi'}</h1>
        <div className="flex items-center gap-2.5 mt-2.5">
           <div className={`text-[9.5px] uppercase tracking-[0.4em] transition-all duration-700 font-bold ${isSpeaking ? 'text-indigo-300' : isTyping ? 'text-indigo-400 animate-pulse' : isListening ? 'text-cyan-400' : isAnalytical ? 'text-indigo-400' : 'text-white/30'}`}>
            {isSpeaking ? 'Speaking' : isTyping ? 'Synthesizing' : isListening ? 'Attuned' : isAnalytical ? 'Iris Active' : mood.toLowerCase()}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdhiAvatar;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AdhiMood, Message, AdhiState, Goal, Memory, FileData, AdhiVoice, MicroExpression } from './types';
import { getAdhiResponse, getAdhiSpeech } from './services/geminiService';
import AdhiAvatar from './components/AdhiAvatar';
import ChatMessage from './components/ChatMessage';
import { GoogleGenAI, LiveServerMessage, Modality, Type, FunctionDeclaration } from '@google/genai';
import { ADHI_GREETINGS, MOOD_COLORS, ADHI_SYSTEM_PROMPT } from './constants';

const INPUT_SAMPLE_RATE = 16000;
const OUTPUT_SAMPLE_RATE = 24000;
const FRAME_RATE = 6; 
const JPEG_QUALITY = 0.94; 

function uint8ToBase64(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

const App: React.FC = () => {
  const [userName, setUserName] = useState<string | null>(() => localStorage.getItem('adhi_user_name'));
  const [messages, setMessages] = useState<Message[]>([]);
  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('adhi_goals');
    return saved ? JSON.parse(saved) : [];
  });
  const [memories, setMemories] = useState<Memory[]>(() => {
    const saved = localStorage.getItem('adhi_memories');
    return saved ? JSON.parse(saved).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [pendingFile, setPendingFile] = useState<FileData | null>(null);
  const [isLive, setIsLive] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [speechVolume, setSpeechVolume] = useState(0);
  const [activeVaultCategory, setActiveVaultCategory] = useState('All');
  const [isCameraActive, setIsCameraActive] = useState(true);
  const [liveStream, setLiveStream] = useState<MediaStream | null>(null);
  const [visionStatus, setVisionStatus] = useState<'idle' | 'sensing' | 'active' | 'inhibited'>('idle');
  const [liveError, setLiveError] = useState<string | null>(null);

  const [state, setState] = useState<AdhiState>({
    currentMood: AdhiMood.NEUTRAL,
    microExpression: 'none',
    isTyping: false,
    activeView: 'chat',
    selectedVoice: (localStorage.getItem('adhi_voice') as AdhiVoice) || 'Kore'
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const frameIntervalRef = useRef<number | null>(null);
  const recognitionRef = useRef<any>(null);
  const volumeUpdateRef = useRef<number | null>(null);

  useEffect(() => {
    if (videoRef.current && liveStream) {
      videoRef.current.srcObject = liveStream;
      videoRef.current.onloadedmetadata = () => {
        videoRef.current?.play().catch(e => console.error("Video Playback Error:", e));
        setVisionStatus('active');
      };
    }
  }, [liveStream, isLive]);

  // Real-time volume analysis for lip-sync
  useEffect(() => {
    if (isSpeaking && analyserRef.current) {
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      const updateVolume = () => {
        if (!analyserRef.current) return;
        analyserRef.current.getByteFrequencyData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
          sum += dataArray[i];
        }
        const average = sum / dataArray.length;
        setSpeechVolume(Math.min(1, average / 60)); // Normalized 0-1
        volumeUpdateRef.current = requestAnimationFrame(updateVolume);
      };
      volumeUpdateRef.current = requestAnimationFrame(updateVolume);
    } else {
      if (volumeUpdateRef.current) cancelAnimationFrame(volumeUpdateRef.current);
      setSpeechVolume(0);
    }
    return () => {
      if (volumeUpdateRef.current) cancelAnimationFrame(volumeUpdateRef.current);
    };
  }, [isSpeaking]);

  const setCameraStateTool: FunctionDeclaration = {
    name: 'setCameraState',
    parameters: {
      type: Type.OBJECT,
      description: 'Turn visual sensing on or off.',
      properties: { enabled: { type: Type.BOOLEAN } },
      required: ['enabled'],
    },
  };

  const setAdhiMoodTool: FunctionDeclaration = {
    name: 'setAdhiMood',
    parameters: {
      type: Type.OBJECT,
      description: 'Update Adhi\'s mood to mirror emotional cues.',
      properties: { mood: { type: Type.STRING, enum: Object.values(AdhiMood) } },
      required: ['mood'],
    },
  };

  const setMicroExpressionTool: FunctionDeclaration = {
    name: 'setMicroExpression',
    parameters: {
      type: Type.OBJECT,
      description: 'Mirror a fleeting micro-expression from the user.',
      properties: { expression: { type: Type.STRING, enum: ['smile', 'concern', 'surprise', 'fatigue', 'focus', 'none'] } },
      required: ['expression'],
    },
  };

  const filteredMemories = useMemo(() => {
    const base = activeVaultCategory === 'All' ? memories : memories.filter(m => m.category === activeVaultCategory);
    if (!searchTerm) return base;
    return base.filter(m => m.text.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [memories, activeVaultCategory, searchTerm]);

  useEffect(() => {
    localStorage.setItem('adhi_goals', JSON.stringify(goals));
    localStorage.setItem('adhi_memories', JSON.stringify(memories));
  }, [goals, memories]);

  useEffect(() => {
    if (userName) localStorage.setItem('adhi_user_name', userName);
    localStorage.setItem('adhi_voice', state.selectedVoice);
    localStorage.setItem('adhi_last_mood', state.currentMood);
    localStorage.setItem('adhi_last_seen', new Date().toISOString());
  }, [userName, state.selectedVoice, state.currentMood]);

  // Enhanced initial greeting logic
  useEffect(() => {
    const lastMood = localStorage.getItem('adhi_last_mood') as AdhiMood || AdhiMood.NEUTRAL;
    const lastSeenStr = localStorage.getItem('adhi_last_seen');
    let welcomeText = "";
    let initialMood = AdhiMood.NEUTRAL;

    if (userName) {
      let moodGreetings: any[];
      const now = new Date();
      const lastSeen = lastSeenStr ? new Date(lastSeenStr) : now;
      const hoursSinceLastSeen = (now.getTime() - lastSeen.getTime()) / (1000 * 60 * 60);

      // Determine greeting category based on time
      if (hoursSinceLastSeen < 4 && lastSeenStr) {
        moodGreetings = ADHI_GREETINGS.RETURNING.RECENT[lastMood] || ADHI_GREETINGS.RETURNING.RECENT.NEUTRAL;
      } else if (hoursSinceLastSeen > 24) {
        moodGreetings = ADHI_GREETINGS.RETURNING.LONG_ABSENCE[lastMood] || ADHI_GREETINGS.RETURNING.LONG_ABSENCE.NEUTRAL;
      } else {
        moodGreetings = ADHI_GREETINGS.RETURNING[lastMood] || ADHI_GREETINGS.RETURNING.NEUTRAL;
      }

      const greetingObj = moodGreetings[Math.floor(Math.random() * moodGreetings.length)];
      welcomeText = greetingObj.text.replace('{name}', userName);
      initialMood = greetingObj.mood as AdhiMood;
    } else {
      // First time greeting
      const greetingObj = ADHI_GREETINGS.NEW_USER[Math.floor(Math.random() * ADHI_GREETINGS.NEW_USER.length)];
      welcomeText = greetingObj.text;
      initialMood = greetingObj.mood as AdhiMood;
    }

    const initialMessage: Message = {
      id: '0',
      role: 'adhi',
      text: welcomeText,
      mood: initialMood,
      timestamp: new Date(),
    };
    setMessages([initialMessage]);
    setState(prev => ({ ...prev, currentMood: initialMood }));
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, state.isTyping]);

  const flushAudioQueue = useCallback(() => {
    audioSourcesRef.current.forEach(s => {
      try { 
        s.onended = null;
        s.stop(); 
      } catch (e) {}
    });
    audioSourcesRef.current.clear();
    if (audioContextOutRef.current) {
      nextStartTimeRef.current = audioContextOutRef.current.currentTime + 0.05;
    } else {
      nextStartTimeRef.current = 0;
    }
    setIsSpeaking(false);
  }, []);

  const playAudioData = useCallback(async (base64Audio: string) => {
    if (isLive) return; 
    try {
      if (!audioContextOutRef.current) {
        audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: OUTPUT_SAMPLE_RATE });
        analyserRef.current = audioContextOutRef.current.createAnalyser();
        analyserRef.current.fftSize = 256;
        analyserRef.current.connect(audioContextOutRef.current.destination);
      }
      const ctx = audioContextOutRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const binary = atob(base64Audio);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(analyserRef.current!);
      source.onended = () => {
        audioSourcesRef.current.delete(source);
        if (audioSourcesRef.current.size === 0) setIsSpeaking(false);
      };
      setIsSpeaking(true);
      source.start();
      audioSourcesRef.current.add(source);
    } catch (e) {
      console.error("Adhi Audio Error:", e);
    }
  }, [isLive]);

  const toggleListening = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;

    try {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'en-US';
      recognition.onstart = () => setIsListening(true);
      recognition.onresult = (event: any) => {
        if (event.results && event.results[0]) {
          setInputValue(event.results[0][0].transcript);
        }
      };
      recognition.onerror = () => setIsListening(false);
      recognition.onend = () => setIsListening(false);
      recognitionRef.current = recognition;
      recognition.start();
    } catch (e) {
      console.error("Speech Recognition Error:", e);
      setIsListening(false);
    }
  }, [isListening]);

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || inputValue;
    if (!textToSend.trim() && !pendingFile) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      fileData: pendingFile || undefined,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setPendingFile(null);
    setState(prev => ({ ...prev, isTyping: true }));

    const history = messages.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));

    const response = await getAdhiResponse(textToSend, history, goals, memories, userName, userMessage.fileData);

    setState(prev => ({ 
      ...prev, 
      isTyping: false, 
      currentMood: response.mood 
    }));

    const adhiMessage: Message = {
      id: (Date.now() + 1).toString(),
      role: 'adhi',
      text: response.text,
      mood: response.mood,
      timestamp: new Date(),
      sources: response.sources
    };

    setMessages(prev => [...prev, adhiMessage]);

    if (response.userName) setUserName(response.userName);
    if (response.insightToSave) {
      setMemories(prev => [
        ...prev, 
        { id: Date.now().toString(), text: response.insightToSave!, timestamp: new Date(), category: 'Insight' }
      ]);
    }
    if (response.goalUpdate) {
      setGoals(prev => {
        const existing = prev.find(g => g.title === response.goalUpdate?.title);
        if (existing) {
          return prev.map(g => g.title === response.goalUpdate?.title ? { 
            ...g, 
            progress: response.goalUpdate?.progressUpdate ?? g.progress,
            steps: response.goalUpdate?.suggestedStep ? [...g.steps, { text: response.goalUpdate.suggestedStep, completed: false }] : g.steps
          } : g);
        } else {
          return [...prev, {
            id: Date.now().toString(),
            title: response.goalUpdate?.title || 'New Goal',
            description: '',
            progress: response.goalUpdate?.progressUpdate || 0,
            category: 'General',
            steps: response.goalUpdate?.suggestedStep ? [{ text: response.goalUpdate.suggestedStep, completed: false }] : []
          }];
        }
      });
    }

    const audio = await getAdhiSpeech(response.text, state.selectedVoice);
    if (audio) playAudioData(audio);
  };

  const toggleLive = async () => {
    if (isLive) {
      sessionRef.current?.close();
      sessionRef.current = null;
      if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
      if (liveStream) {
        liveStream.getTracks().forEach(track => track.stop());
      }
      setIsLive(false);
      setLiveStream(null);
      setIsSpeaking(false);
      setVisionStatus('idle');
      setLiveError(null);
      setState(prev => ({ ...prev, microExpression: 'none' }));
      return;
    }

    setLiveError(null);

    if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await window.aistudio.openSelectKey();
        }
    }

    let stream: MediaStream | null = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: isCameraActive });
      setLiveStream(stream);
      setIsLive(true);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: state.selectedVoice } }
          },
          systemInstruction: ADHI_SYSTEM_PROMPT,
          tools: [{ functionDeclarations: [setCameraStateTool, setAdhiMoodTool, setMicroExpressionTool] }],
        },
        callbacks: {
          onopen: () => {
             if (!audioContextInRef.current) audioContextInRef.current = new AudioContext({ sampleRate: INPUT_SAMPLE_RATE });
             const ctx = audioContextInRef.current;
             if (ctx.state === 'suspended') ctx.resume();

             const source = ctx.createMediaStreamSource(stream!);
             const processor = ctx.createScriptProcessor(4096, 1, 1);
             processor.onaudioprocess = (e) => {
               const inputData = e.inputBuffer.getChannelData(0);
               const int16 = new Int16Array(inputData.length);
               for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
               const base64 = uint8ToBase64(new Uint8Array(int16.buffer));
               sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'audio/pcm;rate=16000' } }));
             };
             source.connect(processor);
             processor.connect(ctx.destination);

             if (isCameraActive) {
               frameIntervalRef.current = window.setInterval(() => {
                 if (videoRef.current && canvasRef.current) {
                   const c = canvasRef.current;
                   const ctxImg = c.getContext('2d');
                   c.width = videoRef.current.videoWidth;
                   c.height = videoRef.current.videoHeight;
                   ctxImg?.drawImage(videoRef.current, 0, 0);
                   c.toBlob(blob => {
                     if (blob) {
                       const reader = new FileReader();
                       reader.onloadend = () => {
                         const base64 = (reader.result as string).split(',')[1];
                         sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
                       };
                       reader.readAsDataURL(blob);
                     }
                   }, 'image/jpeg', JPEG_QUALITY);
                 }
               }, 1000 / FRAME_RATE);
             }
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data) {
              const base64 = msg.serverContent.modelTurn.parts[0].inlineData.data;
              if (!audioContextOutRef.current) {
                audioContextOutRef.current = new AudioContext({ sampleRate: OUTPUT_SAMPLE_RATE });
                analyserRef.current = audioContextOutRef.current.createAnalyser();
                analyserRef.current.fftSize = 256;
                analyserRef.current.connect(audioContextOutRef.current.destination);
              }
              const ctx = audioContextOutRef.current;
              if (ctx.state === 'suspended') await ctx.resume();
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const binary = atob(base64);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
              const dataInt16 = new Int16Array(bytes.buffer);
              const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
              const channelData = buffer.getChannelData(0);
              for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(analyserRef.current!);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              setIsSpeaking(true);
              source.onended = () => {
                if (ctx.currentTime >= nextStartTimeRef.current - 0.1) setIsSpeaking(false);
                audioSourcesRef.current.delete(source);
              };
              audioSourcesRef.current.add(source);
            }

            if (msg.toolCall) {
              for (const fc of msg.toolCall.functionCalls) {
                if (fc.name === 'setAdhiMood') {
                  setState(prev => ({ ...prev, currentMood: fc.args.mood as AdhiMood }));
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: [{ id: fc.id, name: fc.name, response: { result: 'ok' } }] }));
                } else if (fc.name === 'setMicroExpression') {
                  setState(prev => ({ ...prev, microExpression: fc.args.expression as MicroExpression }));
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: [{ id: fc.id, name: fc.name, response: { result: 'ok' } }] }));
                } else if (fc.name === 'setCameraState') {
                  setIsCameraActive(fc.args.enabled);
                  sessionPromise.then(s => s.sendToolResponse({ functionResponses: [{ id: fc.id, name: fc.name, response: { result: 'ok' } }] }));
                }
              }
            }

            if (msg.serverContent?.interrupted) {
              flushAudioQueue();
            }
          },
          onerror: (e: any) => {
            console.error("Live Error:", e);
            const errMsg = e.message || String(e);
            setLiveError(errMsg);
            if (errMsg.includes("Requested entity was not found") || errMsg.includes("Network error") || errMsg.includes("failed to connect")) {
                if (typeof window.aistudio !== 'undefined') window.aistudio.openSelectKey();
                setIsLive(false);
                setVisionStatus('idle');
            }
          },
          onclose: () => {
            setIsLive(false);
            setVisionStatus('idle');
          }
        }
      });
      sessionRef.current = await sessionPromise;

    } catch (e: any) {
      console.error("Live Connection Error:", e);
      const errMsg = e.message || String(e);
      setLiveError(errMsg);
      setIsLive(false);
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      setLiveStream(null);
      if (errMsg.includes("Requested entity was not found") || errMsg.includes("Network error")) {
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPendingFile({
          data: (reader.result as string).split(',')[1],
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden flex flex-col">
      <header className="p-6 flex items-center justify-between border-b border-white/5 bg-slate-950/50 backdrop-blur-xl z-50">
        <AdhiAvatar 
          mood={state.currentMood} 
          microExpression={state.microExpression}
          isTyping={state.isTyping} 
          isSpeaking={isSpeaking}
          volume={speechVolume}
          isListening={isListening || (isLive && !isSpeaking)}
          selectedVoice={state.selectedVoice}
          onVoiceChange={(v) => setState(prev => ({ ...prev, selectedVoice: v }))}
          visionStatus={visionStatus}
        />

        <nav className="flex items-center bg-white/5 rounded-full p-1.5 border border-white/10">
          {(['chat', 'growth', 'vault'] as const).map(view => (
            <button
              key={view}
              onClick={() => setState(prev => ({ ...prev, activeView: view }))}
              className={`px-6 py-2 rounded-full text-xs font-bold uppercase tracking-[0.2em] transition-all duration-500 ${state.activeView === view ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-white/40 hover:text-white/70'}`}
            >
              {view}
            </button>
          ))}
        </nav>

        <button 
          onClick={toggleLive}
